import json
import re

# Validate JSON data against a schema
def validate_json(data):
    """Validates that the data is a dictionary and contains required fields."""
    if not isinstance(data, dict):
        raise ValueError('Data must be a dictionary')
    if 'name' not in data or 'age' not in data:
        raise ValueError('Missing required fields: name, age')
    if not isinstance(data['age'], int) or data['age'] < 0:
        raise ValueError('Age must be a non-negative integer')
    if not re.match(r'^[a-zA-Z\s]+$', data['name']):
        raise ValueError('Name must contain only letters and spaces')

# Serialize data to JSON
def serialize_to_json(data, filename):
    """Serializes and saves validated data to a JSON file."""
    validate_json(data)
    with open(filename, 'w') as json_file:
        json.dump(data, json_file)

# Example usage
data = {
    'name': 'Alice',
    'age': 30
}

serialize_to_json(data, 'validated.json')
print('Valid data saved as JSON')

import json

# Custom encoder for objects
class CustomEncoder(json.JSONEncoder):
    def default(self, obj):
        if hasattr(obj, '__dict__'):
            return obj.__dict__
        return super().default(obj)

def serialize_to_json(data, filename):
    """Serializes a list of objects to a JSON file."""
    with open(filename, 'w') as json_file:
        json.dump(data, json_file, cls=CustomEncoder)

def deserialize_from_json(filename):
    """Deserializes a list of objects from a JSON file."""
    with open(filename, 'r') as json_file:
        data = json.load(json_file)
        return [Object(**item) for item in data]

class Object:
    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)

    def __repr__(self):
        return f"Object({self.__dict__})"

# Example usage
objects = [Object(name='Alice', age=30), Object(name='Bob', age=25)]
serialize_to_json(objects, 'objects.json')
data = deserialize_from_json('objects.json')
print('Deserialized objects:', data)

'''
Property Demo: Shows how to use Python properties to manage class attributes.
'''

class Temperature:
    def __init__(self, celsius=0):
        self._celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("Temperature cannot be below absolute zero.")
        self._celsius = value

    @property
    def fahrenheit(self):
        return (self._celsius * 9/5) + 32

    @fahrenheit.setter
    def fahrenheit(self, value):
        self._celsius = (value - 32) * 5/9

temp = Temperature(25)
print(f"Celsius: {temp.celsius}")
print(f"Fahrenheit: {temp.fahrenheit}")
temp.celsius = 30
print(f"New Celsius: {temp.celsius}")
print(f"New Fahrenheit: {temp.fahrenheit}")

'''
Type Checker: Uses a descriptor to enforce type constraints on class attributes.
'''

class TypeChecker:
    def __init__(self, expected_type):
        self.expected_type = expected_type

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return instance.__dict__[self.name]

    def __set__(self, instance, value):
        if not isinstance(value, self.expected_type):
            raise TypeError(f"Expected {self.expected_type.__name__}, got {type(value).__name__}")
        instance.__dict__[self.name] = value

    def __set_name__(self, owner, name):
        self.name = name
class Person:
    name = TypeChecker(str)
    age = TypeChecker(int)

    def __init__(self, name, age):
        self.name = name
        self.age = age

    def __str__(self):
        return f"{self.name} is {self.age} years old."

p = Person("Alice", 30)
print(p)
p.name = "Bob"
print(p)
