'''
Database Descriptor: Manages a database connection using a descriptor.
'''

class DatabaseConnection:
    def __init__(self, db_name):
        self.db_name = db_name
        self.connection = None

    def __get__(self, instance, owner):
        if self.connection is None:
            self.connection = self._connect()
        return self.connection

    def __set__(self, instance, value):
        raise AttributeError("Cannot assign a new connection directly")

    def _connect(self):
        print(f"Connecting to {self.db_name}")
        return f"{self.db_name} connection object"

class App:
    db = DatabaseConnection("my_database")

    def query(self):
        conn = self.db
        print(f"Querying {conn}")

app = App()
app.query()

