'''Custom Iterator Example using __iter__'''

class CountIterator:
    def __init__(self, start=0, end=10):
        self.current = start
        self.end = end

    def __iter__(self):
        return self

    def __next__(self):
        if self.current > self.end:
            raise StopIteration
        else:
            self.current += 1
            return self.current - 1

