'''Find the longest common subsequence between two strings'''def longest_common_subsequence(s1, s2):
    """Returns the longest common subsequence of s1 and s2."""
    m, n = len(s1), len(s2)
    dp = [["" for _ in range(n+1)] for _ in range(m+1)]
    for i in range(m):
        for j in range(n):
            if s1[i] == s2[j]:
                dp[i+1][j+1] = dp[i][j] + s1[i]
            else:
                dp[i+1][j+1] = max(dp[i+1][j], dp[i][j+1], key=len)
    return dp[m][n]if __name__ == "__main__":
    str1 = input("Enter the first string: ")
    str2 = input("Enter the second string: ")
    lcs = longest_common_subsequence(str1, str2)
    print(f"Longest Common Subsequence: {lcs}")

'''Implement the Knuth-Morris-Pratt (KMP) algorithm for string matching'''def compute_lps(pattern):
    """Compute the Longest Prefix Suffix (LPS) array for the pattern."""
    lps = [0] * len(pattern)
    length = 0
    i = 1
    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    return lpsdef kmp_search(text, pattern):
    """Search for pattern in text using KMP algorithm."""
    n = len(text)
    m = len(pattern)
    lps = compute_lps(pattern)
    i = 0
    j = 0
    while i < n:
        if pattern[j] == text[i]:
            i += 1
            j += 1
            if j == m:
                print(f"Pattern found at index {i - j}")
                j = lps[j - 1]
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1if __name__ == "__main__":
    text = input("Enter the text: ")
    pattern = input("Enter the pattern: ")
    kmp_search(text, pattern)

import heapq

class Dijkstra:
    """Class to implement Dijkstra's algorithm on a graph."""
    def __init__(self, graph):
        """Initialize with a graph as an adjacency list."""
        self.graph = graph

    def shortest_paths(self, start):
        """Find the shortest path from start to all other nodes."""
        distances = {node: float('infinity') for node in self.graph}
        distances[start] = 0
        pq = [(0, start)]

        while pq:
            current_dist, current_node = heapq.heappop(pq)
            if current_dist > distances[current_node]:
                continue
            for neighbor, weight in self.graph[current_node]:
                new_dist = current_dist + weight
                if new_dist < distances[neighbor]:
                    distances[neighbor] = new_dist
                    heapq.heappush(pq, (new_dist, neighbor))
        return distances

if __name__ == "__main__":
    # Example graph
    graph = {
        'A': [('B', 3), ('C', 1)],
        'B': [('A', 3), ('D', 2)],
        'C': [('A', 1), ('D', 4)],
        'D': [('B', 2), ('C', 4)]
    }
    dijkstra = Dijkstra(graph)
    start_node = 'A'
    distances = dijkstra.shortest_paths(start_node)
    print(f"Shortest distances from {start_node}:")
    for node, dist in distances.items():
        print(f"{node}: {dist}")

