class DNode:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None

    def insert(self, data):
        new_node = DNode(data)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node
        new_node.prev = last

    def delete(self, key):
        current = self.head
        while current:
            if current.data == key:
                if current.prev:
                    current.prev.next = current.next
                else:
                    self.head = current.next
                if current.next:
                    current.next.prev = current.prev
                return
            current = current.next

    def display(self):
        current = self.head
        while current:
            print(current.data, end=" <-> ")
            current = current.next
        print("None")

if __name__ == "__main__":
    dll = DoublyLinkedList()
    dll.insert(10)
    dll.insert(20)
    dll.insert(30)
    dll.display()
    dll.delete(20)
    dll.display()

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def get_length(self):
        count = 0
        current = self.head
        while current:
            count += 1
            current = current.next
        return count

    def get_intersection(self, other_list):
        len1 = self.get_length()
        len2 = other_list.get_length()
        current1 = self.head
        current2 = other_list.head
        if len1 > len2:
            for _ in range(len1 - len2):
                current1 = current1.next
        else:
            for _ in range(len2 - len1):
                current2 = current2.next
        while current1 and current2:
            if current1.data == current2.data:
                return current1.data
            current1 = current1.next
            current2 = current2.next
        return None

if __name__ == "__main__":
    llist1 = LinkedList()
    llist1.append(1)
    llist1.append(2)
    llist1.append(3)
    llist1.append(4)
    llist2 = LinkedList()
    llist2.append(5)
    llist2.append(2)
    llist2.append(3)
    llist2.append(4)
    print("Intersection node:", llist1.get_intersection(llist2))

