'''0/1 Knapsack Problem using Dynamic Programming'''def knapsack_01(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(values[i - 1] + dp[i - 1][w - weights[i - 1]], dp[i - 1][w])
            else:
                dp[i][w] = dp[i - 1][w]

    return dp[n][capacity]

if __name__ == "__main__":
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(knapsack_01(weights, values, capacity))

'''Unbounded Knapsack Problem using Dynamic Programming'''def unbounded_knapsack(values, weights, capacity):
    n = len(weights)
    dp = [0] * (capacity + 1)

    for w in range(capacity + 1):
        for i in range(n):
            if weights[i] <= w:
                dp[w] = max(dp[w], values[i] + dp[w - weights[i]])

    return dp[capacity]

if __name__ == "__main__":
    weights = [1, 2, 3]
    values = [10, 15, 40]
    capacity = 5
    print(unbounded_knapsack(weights, values, capacity))

'''Knapsack Problem using Memoization'''from functools import lru_cachedef knapsack_memo(weights, values, capacity):
    @lru_cache(maxsize=None)
    def knapsack(i, w):
        if i == 0 or w == 0:
            return 0
        if weights[i - 1] > w:
            return knapsack(i - 1, w)
        else:
            return max(knapsack(i - 1, w), values[i - 1] + knapsack(i - 1, w - weights[i - 1]))

    return knapsack(len(weights), capacity)

if __name__ == "__main__":
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(knapsack_memo(weights, values, capacity))

