class Node:
    """Node for a linked list."""
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    """Linked list with cycle detection."""
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def has_cycle(self):
        """Detects if the linked list has a cycle."""
        slow = self.head
        fast = self.head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
            if slow == fast:
                return True
        return False

    def display(self):
        current = self.head
        while current:
            print(current.data, end=" -> ")
            current = current.next
        print("None")

if __name__ == "__main__":
    llist = LinkedList()
    llist.append(1)
    llist.append(2)
    llist.append(3)
    llist.display()
    # Create a cycle
    llist.head.next.next.next = llist.head
    print("Cycle detected" if llist.has_cycle() else "No cycle")

