'''Dynamic Programming solution for the 0/1 Knapsack problem'''def knapsack(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i-1] <= w:
                dp[i][w] = max(values[i-1] + dp[i-1][w - weights[i-1]], dp[i-1][w])
            else:
                dp[i][w] = dp[i-1][w]
    return dp[n][capacity]

if __name__ == "__main__":
    weights = [1, 2, 3]
    values = [10, 15, 40]
    capacity = 4
    print(f"Maximum value: {knapsack(weights, values, capacity)}")

'''Dynamic Programming solution for the unbounded knapsack problem'''def unbounded_knapsack(values, weights, capacity):
    dp = [0] * (capacity + 1)
    for w in range(capacity + 1):
        for i in range(len(weights)):
            if weights[i] <= w:
                dp[w] = max(dp[w], values[i] + dp[w - weights[i]])
    return dp[capacity]

if __name__ == "__main__":
    values = [10, 30, 50]
    weights = [1, 2, 3]
    capacity = 5
    print(f"Maximum value: {unbounded_knapsack(values, weights, capacity)}")

'''Dynamic Programming solution for the 0/1 Knapsack problem using memoization'''def knapsack_memo(weights, values, capacity):
    memo = {}
    def helper(index, remaining_capacity):
        if index == 0 or remaining_capacity == 0:
            return 0
        if (index, remaining_capacity) in memo:
            return memo[(index, remaining_capacity)]
        if weights[index-1] > remaining_capacity:
            result = helper(index - 1, remaining_capacity)
        else:
            result = max(helper(index - 1, remaining_capacity), 
                   values[index-1] + helper(index - 1, remaining_capacity - weights[index-1]))
        memo[(index, remaining_capacity)] = result
        return result
    return helper(len(weights), capacity)

if __name__ == "__main__":
    weights = [1, 2, 3]
    values = [10, 15, 40]
    capacity = 4
    print(f"Maximum value: {knapsack_memo(weights, values, capacity)}")

