    pq.add("Task A", 3)
    pq.add("Task B", 1)
    pq.add("Task C", 2)

    while not pq.is_empty():
        print(pq.remove())

import heapq

# Find the k largest elements in a list using a min-heap
# This is more memory-efficient for large lists

def find_k_largest(nums, k):
    """Returns a list of the k largest elements in nums using a min-heap."""
    if k <= 0 or k > len(nums):
        raise ValueError("Invalid value of k")

    heap = []
    for num in nums:
        if len(heap) < k:
            heapq.heappush(heap, num)
        else:
            if num > heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, num)
    return sorted(heap, reverse=True)

# Example usage
if __name__ == "__main__":
    nums = [4, 1, 3, 5, 2, 6]
    k = 3
    print(f"The {k} largest elements are: {find_k_largest(nums, k)}")

import heapq

# Task Scheduler Using a Priority Queue
# This script simulates processing tasks with different priorities

class Task:
    """Represents a task with a priority and a description"""
    def __init__(self, priority, description):
        self.priority = priority
        self.description = description

    def __lt__(self, other):
        return self.priority < other.priority

    def __repr__(self):
        return f"Task(priority={self.priority}, description='{self.description}')"

class TaskScheduler:
    """A priority queue that processes tasks based on their priority"""

    def __init__(self):
        self._heap = []

    def add_task(self, task):
        heapq.heappush(self._heap, task)

    def process_tasks(self):
        while self._heap:
            task = heapq.heappop(self._heap)
            print(f"Processing task: {task.description} (Priority: {task.priority})")

# Example usage
if __name__ == "__main__":
    scheduler = TaskScheduler()
    scheduler.add_task(Task(3, "Emails"))
    scheduler.add_task(Task(1, "System Update"))
    scheduler.add_task(Task(2, "Data Backup"))
    scheduler.process_tasks()

