# top_down_knapsack.py
# Solves the 0/1 knapsack problem using top-down dynamic programming with memoization

from functools import lru_cache
def knapsack(weights, values, capacity):
    n = len(weights)

    @lru_cache(maxsize=None)
    def dp(i, w):
        if i == 0 or w == 0:
            return 0
        if weights[i - 1] > w:
            return dp(i - 1, w)
        else:
            return max(dp(i - 1, w), dp(i - 1, w - weights[i - 1]) + values[i - 1])

    return dp(n, capacity)

# Example usage
if __name__ == "__main__":
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    capacity = 5
    print(f"Maximum value: {knapsack(weights, values, capacity)}")

