# bubble_sort_performance.py
# Implements bubble sort and evaluates its performance on different data sizes

import time
import random

def bubble_sort(arr):
    n = len(arr)
    swaps = 0
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swaps += 1
    return swaps

if __name__ == "__main__":
    sizes = [10, 100, 500, 1000]
    for size in sizes:
        arr = list(range(size, 0, -1))  # Reverse-sorted array
        start = time.time()
        swaps = bubble_sort(arr)
        end = time.time()
        print(f"Size: {size} | Time: {end - start:.6f}s | Swaps: {swaps}")

