import time
import random

def bubble_sort(arr):
    n = len(arr)
    swaps = 0
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swaps += 1
    return swaps

def quick_sort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[0]
    left = [x for x in arr[1:] if x < pivot]
    right = [x for x in arr[1:] if x >= pivot]
    return quick_sort(left) + [pivot] + quick_sort(right)

if __name__ == "__main__":
    sample = [random.randint(1, 1000) for _ in range(500)]
    arr1 = sample.copy()
    arr2 = sample.copy()

    start = time.time()
    bubble_sort(arr1)
    end = time.time()
    print(f"Bubble sort time: {end - start:.6f}s")

    start = time.time()
    quick_sort(arr2)
    end = time.time()
    print(f"Quick sort time: {end - start:.6f}s")

