import time
import random

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

if __name__ == "__main__":
    data = [random.randint(1, 1000) for _ in range(1000)]

    start_time = time.time()
    bubble_sort(data.copy())
    bubble_time = time.time() - start_time

    start_time = time.time()
    merge_sort(data.copy())
    merge_time = time.time() - start_time

    print(f"Bubble Sort time: {bubble_time:.6f} seconds")
    print(f"Merge Sort time: {merge_time:.6f} seconds")

import time

def fibonacci(n, cache=None):
    if cache is None:
        cache = {}
    if n in cache:
        return cache[n]
    if n <= 1:
        return n
    cache[n] = fibonacci(n - 1, cache) + fibonacci(n - 2, cache)
    return cache[n]

def fibonacci_no_cache(n):
    if n <= 1:
        return n
    return fibonacci_no_cache(n - 1) + fibonacci_no_cache(n - 2)

if __name__ == "__main__":
    n = 35
    start_time = time.time()
    fib_cache = fibonacci(n)
    cache_time = time.time() - start_time

    start_time = time.time()
    fib_no_cache = fibonacci_no_cache(n)
    no_cache_time = time.time() - start_time

    print(f"Fibonacci with cache: {fib_cache} (time: {cache_time:.6f} s)")
    print(f"Fibonacci without cache: {fib_no_cache} (time: {no_cache_time:.6f} s)")

import time

def precompute_squares(limit):
    return {i: i*i for i in range(limit)}

def get_square(n, squares):
    return squares[n]

