import time

def generate_numbers(limit):
    for i in range(limit):
        yield i

def process_numbers(limit):
    total = 0
    for num in generate_numbers(limit):
        total += num
    return total

if __name__ == "__main__":
    limit = 1000000
    start_time = time.time()
    result = process_numbers(limit)
    duration = time.time() - start_time
    print(f"Processed {limit} numbers. Total: {result}, Time: {duration:.6f} seconds")

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True

    def search(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end

if __name__ == "__main__":
    trie = Trie()
    words = ["apple", "app", "apricot", "banana", "bat"]
    for word in words:
        trie.insert(word)

    print("Search 'app':", trie.search("app"))
    print("Search 'apples':", trie.search("apples"))

import time

def factorial(n, memo=None):
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 1
    memo[n] = n * factorial(n - 1, memo)
    return memo[n]

def factorial_no_memo(n):
    if n == 0:
        return 1
    return n * factorial_no_memo(n - 1)

