'''Perform a simple wildcard match with '*' and '?''''def wildcard_match(pattern, text):
    if not pattern:
        return True
    if not text:
        return False
    if pattern[0] == '?':
        return wildcard_match(pattern[1:], text[1:])
    elif pattern[0] == '*':
        return wildcard_match(pattern[1:], text) or wildcard_match(pattern, text[1:])
    elif pattern[0] == text[0]:
        return wildcard_match(pattern[1:], text[1:])
    else:
        return Falseif __name__ == '__main__':
