'''Find the longest common substring between two strings'''def longest_common_substring(s1, s2):
    m = len(s1)
    n = len(s2)
    dp = [[0]*(n+1) for _ in range(m+1)]
    max_len = 0
    end_idx = 0
    for i in range(1, m+1):
        for j in range(1, n+1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
                if dp[i][j] > max_len:
                    max_len = dp[i][j]
                    end_idx = i
            else:
                dp[i][j] = 0
    return s1[end_idx - max_len:end_idx]if __name__ == '__main__':
    s1 = input('Enter first string: ')
    s2 = input('Enter second string: ')
    lcs = longest_common_substring(s1, s2)
    print(f'Longest common substring: {lcs}')

'''Check string similarity using Levenshtein distance'''def levenshtein_distance(s1, s2):
    m = len(s1)
    n = len(s2)
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1):
        dp[i][0] = i
    for j in range(n+1):
        dp[0][j] = j
    for i in range(1, m+1):
        for j in range(1, n+1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[m][n]if __name__ == '__main__':
    s1 = input('Enter first string: ')
    s2 = input('Enter second string: ')
    distance = levenshtein_distance(s1, s2)
    print(f'Levenshtein distance: {distance}')

