"""Checks if a string has a substring of length k with all unique characters."""
def has_unique_chars(s, k):
    if not s or k <= 0 or k > len(s):
        return False
    chars = set()
    for i in range(len(s)):
        if i >= k:
            chars.remove(s[i - k])
        if s[i] in chars:
            return False
        chars.add(s[i])
    return True

if __name__ == "__main__":
    string = "abcdefg"
    k = 3
    print(f"Has unique chars in window of size {k}: {has_unique_chars(string, k)}")

