"""Finds all anagrams of a string within another string using sliding window."""
def find_anagrams(s, p):
    if len(p) > len(s):
        return []
    p_count = [0] * 26
    s_count = [0] * 26
    for char in p:
        p_count[ord(char) - ord('a')] += 1
    for i in range(len(p)):
        s_count[ord(s[i]) - ord('a')] += 1
    result = []
    for i in range(len(p), len(s)):
        if s_count == p_count:
            result.append(i - len(p))
        s_count[ord(s[i]) - ord('a')] += 1
        s_count[ord(s[i - len(p)]) - ord('a')] -= 1
    if s_count == p_count:
        result.append(len(s) - len(p))
    return result

if __name__ == "__main__":
    s = "cbaacb"
    p = "abc"
    print(f"Anagrams of '{p}' in '{s}': {find_anagrams(s, p)}")

