"""Counts the number of substrings with exactly k distinct characters using sliding window."""
def k_distinct_substrings(s, k):
    from collections import defaultdict
    def at_most_k(k):
        count = 0
        left = 0
        freq = defaultdict(int)
        for right in range(len(s)):
            freq[s[right]] += 1
            while len(freq) > k:
                freq[s[left]] -= 1
                if freq[s[left]] == 0:
                    del freq[s[left]]
                left += 1
            count += right - left + 1
        return count
    return at_most_k(k) - at_most_k(k - 1)

if __name__ == "__main__":
    string = "abc"
    k = 2
    print(f"Number of substrings with exactly {k} distinct chars: {k_distinct_substrings(string, k)}")

