def has_cycle(graph, start):
    visited = set()
    queue = [(start, -1)]

    while queue:
        node, parent = queue.pop(0)
        if node in visited:
            return True
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor != parent:
                queue.append((neighbor, node))
    return False

