    test_string = "(())" 
    print(f"{test_string} is balanced: {is_balanced(test_string)}")

'''
Stack implementation using a linked list
'''
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class Stack:
    def __init__(self):
        self.top = None

    def push(self, data):
        new_node = Node(data)
        new_node.next = self.top
        self.top = new_node

    def pop(self):
        if self.top is None:
            return None
        data = self.top.data
        self.top = self.top.next
        return data

    def peek(self):
        return self.top.data if self.top else None

    def is_empty(self):
        return self.top is None

if __name__ == "__main__":
    s = Stack()
    s.push(10)
    s.push(20)
    print(f"Popped: {s.pop()}")
    print(f"Peek: {s.peek()}")

