    def delete(self, word):
        node = self.root
        path = []
        for ch in word:
            if ch not in node.children:
                return
            path.append((node, ch))
            node = node.children[ch]
        if not node.is_end:
            return
        node.is_end = False
        for parent, ch in reversed(path):
            if len(parent.children[ch].children) > 0:
