# Uses Union-Find to detect cycles in an undirected graph

def has_cycle(graph, vertices):
    uf = UnionFind(len(vertices))
    for u, v in graph:
        if uf.find(u) == uf.find(v):
            return True
        uf.union(u, v)
    return False

