# Performs BFS and returns the path from start to goal node

def bfs_path(graph, start, goal):
    queue = [(start, [start])]
    while queue:
        node, path = queue.pop(0)
        if node == goal:
            return path
        for neighbor in graph.get(node, []):
            if neighbor not in path:
                queue.append((neighbor, path + [neighbor]))
    return None

