# knapsack_memo.py
# Solves the 0/1 knapsack problem using recursion with memoization

# Input: weights, values, capacity
# Output: Maximum value that can be carried

def knapsack(weights, values, capacity):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def helper(i, w):
        if i == 0 or w == 0:
            return 0
        if weights[i - 1] > w:
            return helper(i - 1, w)
        else:
            return max(helper(i - 1, w), helper(i - 1, w - weights[i - 1]) + values[i - 1])

    return helper(len(weights), capacity)

