def find_components(graph):
    visited = set()
    components = []
    def _dfs(node, component):
        if node not in visited:
            visited.add(node)
            component.append(node)
            for neighbor in graph[node]:
                _dfs(neighbor, component)
    for node in graph:
        if node not in visited:
            component = []
            _dfs(node, component)
            components.append(component)
    return components

