def has_cycle(graph):
    visited = set()
    def _dfs(node, parent):
        if node in visited:
            return True
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor != parent:
                if _dfs(neighbor, node):
                    return True
        return False

    for node in graph:
        if node not in visited:
            if _dfs(node, -1):
                return True
    return False

