def count_paths(graph, start, end):
    count = 0
    def _dfs(node, path):
        nonlocal count
        if node == end:
            count += 1
            return
        for neighbor in graph[node]:
            _dfs(neighbor, path + [neighbor])
    _dfs(start, [start])
    return count

if __name__ == "__main__":
    graph = {
        'A': ['B', 'C'],
        'B': ['A', 'D'],
        'C': ['A', 'D'],
        'D': ['B', 'C']
    }
    print(count_paths(graph, 'A', 'D'))

# This script counts all paths between two nodes using DFS.

def find_path(graph, start, end):
    def _dfs(node, path):
        if node == end:
            return path
        for neighbor in graph[node]:
            if neighbor not in path:
                result = _dfs(neighbor, path + [neighbor])
                if result:
                    return result
        return None

    return _dfs(start, [start])

