def two_sum(nums, target):
    """Check if there are two numbers in the list that add up to the target using the two pointers technique."""
    nums.sort()
    left, right = 0, len(nums) - 1
    while left < right:
        current_sum = nums[left] + nums[right]
        if current_sum == target:
            return True
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    return False

if __name__ == "__main__":
    numbers = [1, 4, 45, 6, 10, 8]
    target = 16
    print(two_sum(numbers, target))

def reverse_string(s):
    """Reverse a string in place using the two pointers technique."""
    s = list(s)
    left, right = 0, len(s) - 1
    while left < right:
        s[left], s[right] = s[right], s[left]
        left += 1
        right -= 1
    return ''.join(s)

