'''Decorator to restrict function access based on user role.'''
def require_role(role):
    def decorator(func):
        def wrapper(user, *args, **kwargs):
            if user['role'] != role:
                raise PermissionError(f'You do not have {role} access')
            return func(user, *args, **kwargs)
        return wrapper
    return decorator

