'''Decorator to memoize function results based on parameters.'''
def memoize(func):
    cache = {}
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            return cache[key]
        result = func(*args, **kwargs)
        cache[key] = result
        return result
    return wrapper

@memoize
def multiply(a, b):
    return a * b

print(multiply(2, 3))
