'''Trie with wildcard pattern matching''' class TrieNode: 
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True

    def wildcard_search(self, pattern):
        return self._dfs(self.root, pattern, 0, '')

    def _dfs(self, node, pattern, index, current):
        if index == len(pattern):
            return [current] if node.is_end else []

        results = []
        char = pattern[index]
        if char == '?':
            for child_char, child_node in node.children.items():
                results.extend(self._dfs(child_node, pattern, index + 1, current + child_char))
        elif char == '*':
            # Handle * as 0 or more characters
            results.extend(self._dfs(node, pattern, index + 1, current))  # match 0 chars
            for child_char, child_node in node.children.items():
                results.extend(self._dfs(child_node, pattern, index + 1, current + child_char))
        else:
            if char in node.children:
                results.extend(self._dfs(node.children[char], pattern, index + 1, current + char))
        return results

# Example usage
