'''
Topological sort with multiple algorithm implementations
'''

def topological_sort_kahn(graph):
    """Kahn's algorithm for topological sorting.

    Args:
        graph: A dictionary where keys are nodes and values are lists of adjacent nodes.

    Returns:
        A list of nodes in topological order.
    """
    in_degree = {node: 0 for node in graph}
    for node in graph:
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    queue = [node for node in in_degree if in_degree[node] == 0]
    result = []

    while queue:
        current = queue.pop(0)
        result.append(current)
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(graph):
        raise ValueError("Graph has a cycle and cannot be topologically sorted")
    return result

def topological_sort_dfs(graph):
    """DFS-based topological sort.

    Args:
        graph: A dictionary where keys are nodes and values are lists of adjacent nodes.

    Returns:
        A list of nodes in topological order.
    """
    visited = set()
    result = []

    def dfs(node):
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs(neighbor)
        result.append(node)

    for node in graph:
        if node not in visited:
            dfs(node)

    return result[::-1]

if __name__ == "__main__":
    graph = {
        'A': ['B', 'C'],
        'B': ['D'],
        'C': ['D'],
        'D': []
    }
    print("Kahn's algorithm:", topological_sort_kahn(graph))
    print("DFS-based algorithm:", topological_sort_dfs(graph))

