# fib_memo.py
# A memoized Fibonacci function to calculate numbers efficiently

def fib(n, memo={1: 1, 2: 1}):
    """Returns the nth Fibonacci number using memoization."""
    if n not in memo:
        memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]

if __name__ == "__main__":
    print(fib(10))

# fact_memo.py
# A memoized factorial function for efficient computation

def factorial(n, memo={}):
    """Returns the factorial of n using memoization."""
    if n in memo:
        return memo[n]
    if n == 0:
        return 1
    memo[n] = n * factorial(n - 1, memo)
    return memo[n]

if __name__ == "__main__":
    print(factorial(5))

# memo_decorator.py
# Using a decorator to memoize a function

def memoize(func):
    """Decorator to memoize function results."""
    cache = {}
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

@memoize
def add(a, b):
    """Returns the sum of a and b."""
    return a + b

if __name__ == "__main__":
    print(add(2, 3))

