# memo_recursion.py
# A memoized recursive function with a cache

def memoize(func):
    """Decorator to memoize a recursive function."""
    cache = {}
    def wrapper(n):
        if n not in cache:
            cache[n] = func(n)
        return cache[n]
    return wrapper

@memoize
def count_down(n):
    """Counts down from n to 0."""
    if n == 0:
        return 0
    return count_down(n - 1)

if __name__ == "__main__":
    print(count_down(10))

# even_sum_memo.py
# Memoizes the sum of even numbers in a list

def memoize(func):
    """Decorator to memoize function calls."""
    cache = {}
    def wrapper(lst):
        key = tuple(lst)
        if key not in cache:
            cache[key] = func(lst)
        return cache[key]
    return wrapper

@memoize
def even_sum(lst):
    """Returns the sum of even numbers in the list."""
    return sum(x for x in lst if x % 2 == 0)

if __name__ == "__main__":
    print(even_sum([1, 2, 3, 4, 5]))

