import time

def timer(func):
    """Decorator that prints the execution time of a function."""
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} executed in {end - start:.4f} seconds")
        return result
    return wrapper

@timer
def count_up(n):
    """Counts up from 1 to n."""
    for i in range(n):
        print(i)

if __name__ == "__main__":
    count_up(5)

def logger(func):
    """Decorator that logs function arguments and return value."""
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__} with args: {args}, kwargs: {kwargs}")
        result = func(*args, **kwargs)
        print(f"{func.__name__} returned: {result}")
        return result
    return wrapper

@logger
def add(a, b):
    """Returns the sum of a and b."""
    return a + b

if __name__ == "__main__":
    add(3, 5)

def validate_types(*types):
    """Decorator that validates the types of arguments passed to a function."""
    def decorator(func):
        def wrapper(*args):
            for arg, type_ in zip(args, types):
                if not isinstance(arg, type_):
                    raise TypeError(f"Argument {arg} is not of type {type_}")
            return func(*args)
        return wrapper
    return decorator

@validate_types(int, int)
def add(a, b):
    """Returns the sum of two integers."""
    return a + b

if __name__ == "__main__":
    print(add(3, 5))

def cache(func):
    """Decorator that caches the results of a function."""
    cache_dict = {}
    def wrapper(*args):
        if args in cache_dict:
            print("Returning cached result")
            return cache_dict[args]
        result = func(*args)
        cache_dict[args] = result
        return result
    return wrapper

@cache
def square(n):
    """Returns the square of a number."""
    return n * n

if __name__ == "__main__":
    print(square(4))
    print(square(4))

def add_prefix(prefix):
    """Decorator that adds a prefix to the output of a function."""
    def decorator(func):
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            return f"{prefix} {result}"
        return wrapper
    return decorator

@add_prefix("Result:")
def greet(name):
    """Returns a greeting message."""
    return f"Hello, {name}!"

