def require_admin(func):
    """Decorator that restricts access to a function if the user is not an admin."""
    def wrapper(user, *args, **kwargs):
        if user != "admin":
            raise PermissionError("Only admins can access this function")
        return func(user, *args, **kwargs)
    return wrapper

@require_admin
def delete_user(user):
    """Deletes a user if the user is an admin."""
    print(f"{user} deleted the user")

if __name__ == "__main__":
