        print(chunk)

'''A script that runs a command and prints its output in real-time.'''
import subprocess
import sys

def live_output(command):
    '''Run a command and print its output in real-time.'''
    process = subprocess.Popen(
        command,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        shell=True
    )
    while True:
        output = process.stdout.readline()
        if output == '' and process.poll() is not None:
            break
        if output:
            print(output.strip())

if __name__ == '__main__':
    live_output('ping -c 5 localhost')

