'''This script demonstrates handling division by zero and custom exceptions in Python.'''

class InvalidInputError(Exception):
    """Raised when the input is not valid for division."""


def divide(a, b):
    """Divides a by b, raising InvalidInputError if inputs are not numbers."""
    if not (isinstance(a, (int, float)) and isinstance(b, (int, float))):
        raise InvalidInputError("Both inputs must be numbers")
    if b == 0:
        raise ZeroDivisionError("Division by zero is not allowed")
    return a / b

if __name__ == "__main__":
    try:
        result = divide(10, 0)
    except InvalidInputError as e:
        print(f"Error: {e}")
    except ZeroDivisionError as e:
        print(f"Error: {e}")
    else:
        print(f"Result: {result}")

