'''This script converts temperature between Celsius and Fahrenheit with custom exceptions.'''

class InvalidTemperatureError(Exception):
    """Raised when the temperature value is not valid."""


def convert_temperature(value, unit):
    """Converts a temperature value between Celsius and Fahrenheit."""
    if unit.lower() == 'c':
        return (value * 9/5) + 32
    elif unit.lower() == 'f':
        return (value - 32) * 5/9
    else:
        raise InvalidTemperatureError("Unit must be 'C' or 'F'")

if __name__ == "__main__":
    try:
        print(convert_temperature(100, 'c'))
        print(convert_temperature(212, 'f'))
        print(convert_temperature(32, 'k'))
    except InvalidTemperatureError as e:
        print(f"Error: {e}")

