'''Finds the height of a binary search tree''' class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
class BST:
    def __init__(self):
        self.root = None
    def insert(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)
    def _insert_recursive(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursive(node.left, value)
        else:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursive(node.right, value)
    def height(self):
        return self._height_recursive(self.root)
    def _height_recursive(self, node):
        if node is None:
            return -1
        left_height = self._height_recursive(node.left)
        right_height = self._height_recursive(node.right)
        return max(left_height, right_height) + 1

if __name__ == "__main__":
    data = [10, 5, 15, 3, 7, 12, 18]
    bst = BST()
    for num in data:
        bst.insert(num)
    print("Height of the tree:", bst.height())

'''Deletes a node from a binary search tree''' class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
class BST:
    def __init__(self):
        self.root = None
    def insert(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)
    def _insert_recursive(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursive(node.left, value)
        else:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursive(node.right, value)
    def delete(self, value):
        self.root = self._delete_recursive(self.root, value)
    def _delete_recursive(self, node, value):
        if node is None:
            return node
        if value < node.value:
            node.left = self._delete_recursive(node.left, value)
        elif value > node.value:
            node.right = self._delete_recursive(node.right, value)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            else:
                temp = self._min_value_node(node.right)
                node.value = temp.value
                node.right = self._delete_recursive(node.right, temp.value)
        return node
    def _min_value_node(self, node):
        current = node
        while current.left:
            current = current.left
        return current

if __name__ == "__main__":
    data = [10, 5, 15, 3, 7, 12, 18]
    bst = BST()
    for num in data:
        bst.insert(num)
    print("Original tree:", bst.in_order_traversal())
    bst.delete(10)
    print("After deleting 10:", bst.in_order_traversal())

'''Checks if a binary search tree is valid''' class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
class BST:
    def __init__(self):
        self.root = None
    def insert(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)
    def _insert_recursive(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursive(node.left, value)
        else:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursive(node.right, value)
    def is_valid(self):
        return self._is_valid_recursive(self.root, float('-inf'), float('inf'))
    def _is_valid_recursive(self, node, min_val, max_val):
        if node is None:
            return True
        if node.value < min_val or node.value > max_val:
            return False
        return self._is_valid_recursive(node.left, min_val, node.value) and self._is_valid_recursive(node.right, node.value, max_val)

if __name__ == "__main__":
    data = [10, 5, 15, 3, 7, 12, 18]
    bst = BST()
    for num in data:
        bst.insert(num)
    print("Is the tree valid?", bst.is_valid())

