from functools import lru_cache

@lru_cache(maxsize=None)
def fibonacci(n):
    """Calculate the nth Fibonacci number using lru_cache for memoization."""
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

