from functools import lru_cache, partial, wraps

def log_message(msg):
    """Log a message to the console."""
    print(f"[LOG] {msg}")

@lru_cache(maxsize=None)
def cached_function(x):
    return x * 2

@partial(log_message, "Function called with x=5")
def function_with_partial(x):
    return x + 1

@wraps(function_with_partial)
def wrapped_function(x):
    return function_with_partial(x)

if __name__ == "__main__":
    print(cached_function(5))
    print(function_with_partial(5))
    print(wrapped_function(5))

