from functools import lru_cache

def factorial(n):
    """Calculate the factorial of a number."""
    if n == 0:
        return 1
    return n * factorial(n - 1)

@lru_cache(maxsize=None)
def cached_factorial(n):
    return factorial(n)

if __name__ == "__main__":
    print(cached_factorial(5))

