# nqueens_backtrack.py
# Solves N-Queens problem using backtracking

def solve_n_queens(n):
    board = [[0 for _ in range(n)] for _ in range(n)]
    solutions = []

    def is_safe(row, col):
        for i in range(col):
            if board[row][i] == 1:
                return False
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False
        for i, j in zip(range(row, n), range(col, -1, -1))):
            if board[i][j] == 1:
                return False
        return True

    def backtrack(col):
        if col >= n:
            solutions.append([row[:] for row in board])
            return
        for row in range(n):
            if is_safe(row, col):
                board[row][col] = 1
                backtrack(col + 1)
                board[row][col] = 0

    backtrack(0)
    return solutions

if __name__ == "__main__":
    n = 8
    solutions = solve_n_queens(n)
    print(f"Found {len(solutions)} solutions for {n}-queens problem.")

