def merge_sort(arr):
    """Sorts an array using the mergesort algorithm."""
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    """Merges two sorted lists into one sorted list."""
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

if __name__ == "__main__":
    sample = [38, 27, 43, 3, 9, 82, 10]
    sorted_sample = merge_sort(sample)
    print("Sorted array:", sorted_sample)

def fibonacci(n):
    """Calculate the nth Fibonacci number using dynamic programming."""
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    fib = [0] * (n + 1)
    fib[0] = 0
    fib[1] = 1
    for i in range(2, n + 1):
        fib[i] = fib[i - 1] + fib[i - 2]
    return fib[n]

if __name__ == "__main__":
    print(fibonacci(10))

def print_fibonacci_sequence(limit):
    """Print the Fibonacci sequence up to the given limit using dynamic programming."""
    if limit < 0:
        print("Invalid input: limit must be a non-negative integer.")
        return
    a, b = 0, 1
    while a <= limit:
        print(a, end=' ')
        a, b = b, a + b

if __name__ == "__main__":
    print_fibonacci_sequence(100)

def compute_fibonacci(n):
    """Compute the first n Fibonacci numbers using dynamic programming and return as a list."""
    if n <= 0:
        return []
    fib = [0] * n
    fib[0] = 0
    if n > 1:
        fib[1] = 1
    for i in range(2, n):
        fib[i] = fib[i - 1] + fib[i - 2]
    return fib

def save_fibonacci_to_file(n, filename):
    """Save the first n Fibonacci numbers to the specified file."""
    with open(filename, 'w') as f:
        for num in compute_fibonacci(n):
            f.write(f'{num}\n')

if __name__ == "__main__":
    save_fibonacci_to_file(10, 'fib_sequence.txt')

def fibonacci(n, memo={}):
    """Calculate the nth Fibonacci number using dynamic programming with memoization."""
    if n in memo:
        return memo[n]
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo)
    return memo[n]

if __name__ == "__main__":
    print(fibonacci(10))

def sum_of_fibonacci(n):
    """Calculate the sum of the first n Fibonacci numbers using dynamic programming."""
    if n <= 0:
        return 0
    fib = [0] * n
    fib[0] = 0
    if n > 1:
        fib[1] = 1
    for i in range(2, n):
        fib[i] = fib[i - 1] + fib[i - 2]
    return sum(fib)

if __name__ == "__main__":
    print(sum_of_fibonacci(10))

