# Validates a password using regular expressions based on specific criteria
import re

def is_valid_password(password):
    """Returns True if password meets criteria: 8+ characters, 1 uppercase, 1 lowercase, 1 digit"""
    if len(password) < 8:
        return False
    if not re.search(r'[A-Z]', password):
        return False
    if not re.search(r'[a-z]', password):
        return False
    if not re.search(r'[0-9]', password):
        return False
    return True

if __name__ == "__main__":
    test_passwords = ["Pass1234", "pass1234", "PASS1234", "P@ss1234"]
    for pwd in test_passwords:
        print(f'{pwd}: {is_valid_password(pwd)}')

