    start = time.time()
    print(f'Is {number} prime (loop): {is_prime_loop(number)}')
    print(f'Loop time: {time.time() - start:.6f}s')

    start = time.time()
    primes = sieve_of_eratosthenes(number)
    print(f'Primes up to {number} (sieve): {len(primes)} primes found')
    print(f'Sieve time: {time.time() - start:.6f}s')

