#!/usr/bin/env python3
"""A script to calculate Fibonacci numbers using memoization."""

def fibonacci(n, memo=None):
    """Calculate the nth Fibonacci number using memoization."
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    return memo[n]

if __name__ == "__main__":
    import sys
    n = int(sys.argv[1])
    print(f"Fibonacci({n}) = {fibonacci(n)}")

