"""A script to calculate factorials with memoization."""

def factorial(n, memo=None):
    """Calculate the factorial of n using memoization."
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return 1
    memo[n] = n * factorial(n-1, memo)
    return memo[n]

if __name__ == "__main__":
