    print(f"Factorial({n}) = {factorial(n)}")

#!/usr/bin/env python3
"""A script to check if a number is prime with memoization."""

def is_prime(n, memo=None):
    """Check if n is a prime number using memoization."
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n < 2:
        memo[n] = False
        return False
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            memo[n] = False
            return False
    memo[n] = True
    return True

if __name__ == "__main__":
    import sys
    n = int(sys.argv[1])
    print(f"{n} is prime? {is_prime(n)}")

#!/usr/bin/env python3
"""A script to compute the sum of digits of a number with memoization."""

def sum_digits(n, memo=None):
    """Compute the sum of the digits of n using memoization."
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    memo[n] = n % 10 + sum_digits(n // 10, memo)
    return memo[n]

if __name__ == "__main__":
    import sys
    n = int(sys.argv[1])
    print(f"Sum of digits of {n} is {sum_digits(n)}")

#!/usr/bin/env python3
"""A script to calculate the power of a number with memoization."""

def power(base, exponent, memo=None):
    """Calculate base^exponent using memoization."
    if memo is None:
        memo = {}
    key = (base, exponent)
    if key in memo:
        return memo[key]
    if exponent == 0:
        return 1
    if exponent % 2 == 0:
        result = power(base, exponent // 2, memo) ** 2
    else:
        result = base * power(base, exponent - 1, memo)
    memo[key] = result
    return result

if __name__ == "__main__":
    import sys
    base = int(sys.argv[1])
    exponent = int(sys.argv[2])
    print(f"{base}^{exponent} = {power(base, exponent)}")

