"""A script to calculate the number of ways to climb stairs using memoization."""

def climb_stairs(n, memo=None):
    """Calculate the number of ways to climb n stairs, where you can take 1 or 2 steps at a time."
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return 1
    memo[n] = climb_stairs(n - 1, memo) + climb_stairs(n - 2, memo)
    return memo[n]

