'''N-Queens problem using backtracking algorithm.'''

def solve_nqueens(n):
    '''Solve the N-Queens problem for a given n.'''
    board = [-1] * n
    solutions = []
    def is_safe(col, row):
        for i in range(row):
            if board[i] == col or abs(board[i] - col) == row - i:
                return False
        return True

    def backtrack(row):
        if row == n:
            solutions.append(board[:])
            return
        for col in range(n):
            if is_safe(col, row):
                board[row] = col
                backtrack(row + 1)
                board[row] = -1

    backtrack(0)
    return solutions

if __name__ == '__main__':
    n = 8
    solutions = solve_nqueens(n)
    print(f'Found {len(solutions)} solutions for N = {n}'))

