def knapsack_memo(values, weights, capacity, memo=None):
    """Solves 0/1 knapsack using memoization."""
    if memo is None:
        memo = {}
    n = len(values)
    key = (n, capacity)
    if key in memo:
        return memo[key]
    if n == 0 or capacity == 0:
        return 0
    if weights[-1] > capacity:
        result = knapsack_memo(values[:-1], weights[:-1], capacity, memo)
    else:
        result = max(
            knapsack_memo(values[:-1], weights[:-1], capacity, memo),
            knapsack_memo(values[:-1], weights[:-1], capacity - weights[-1], memo) + values[-1]
        )
    memo[key] = result
    return result

