def knapsack_1d(values, weights, capacity):
    """Solves 0/1 knapsack with a 1D DP array for space optimization."""
    dp = [0] * (capacity + 1)
    for i in range(len(values)):
        for w in range(capacity, weights[i] - 1, -1):
