        'C': ['A', 'D'],
        'D': ['B', 'C']
    }

    start = input("Enter start node:").strip()
    end = input("Enter end node:").strip()

    path = bfs_shortest_path(graph, start, end)

    if path:
        print("Shortest path:", ' -> '.join(path))
    else:
        print("No path found.")

