from functools import lru_cache

def knapsack_memoized(weights, values, capacity):
    @lru_cache(maxsize=None)
    def dp(n, w):
        if n == 0 or w == 0:
            return 0
        if weights[n - 1] > w:
            return dp(n - 1, w)
        else:
            return max(
                values[n - 1] + dp(n - 1, w - weights[n - 1]),
                dp(n - 1, w)
            )
    return dp(len(weights), capacity)

