def multiconstraint_knapsack(values, weights, capacities):
    n = len(values)
    m = len(capacities)
    dp = [[[0] * (capacities[i] + 1) for i in range(m)] for _ in range(n + 1)]
    for i in range(1, n + 1):
        for c in range(m):
            for w in range(capacities[c] + 1):
                if weights[i - 1] <= w:
                    dp[i][c][w] = max(dp[i - 1][c][w], values[i - 1] + dp[i - 1][c][w - weights[i - 1]])
                else:
                    dp[i][c][w] = dp[i - 1][c][w]
