'''
Convert temperature between Celsius and Fahrenheit with type checking.
'''
from typing import Union

def convert_temp(temp: Union[int, float], unit: str) -> Union[int, float]:
    """Convert temperature between Celsius and Fahrenheit."""
    if unit.lower() == 'c':
        return temp * 9/5 + 32
    elif unit.lower() == 'f':
        return (temp - 32) * 5/7
    else:
        raise ValueError("Invalid unit. Use 'c' or 'f'.")

if __name__ == "__main__":
    print(convert_temp(25, 'c'))
    print(convert_temp(77, 'f'))

