def binary_search(arr, target):
    """Performs binary search on a sorted list and returns the index of the target if found, otherwise returns -1."""
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

if __name__ == "__main__":
    sorted_list = [1, 3, 5, 7, 9, 11]
    result = binary_search(sorted_list, 7)
    print(f"Found at index: {result}")

def recursive_binary_search(arr, target, left, right):
    """Recursively performs binary search on a sorted list and returns the index of the target if found, otherwise returns -1."""
    if left > right:
        return -1
    mid = (left + right) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return recursive_binary_search(arr, target, mid + 1, right)
    else:
        return recursive_binary_search(arr, target, left, mid - 1)

if __name__ == "__main__":
    sorted_list = [1, 3, 5, 7, 9, 11]
    result = recursive_binary_search(sorted_list, 5, 0, len(sorted_list) - 1)
    print(f"Found at index: {result}")

def first_occurrence_binary_search(arr, target):
    """Finds the first occurrence of a target in a sorted list using binary search and returns its index, or -1 if not found."""
    left, right = 0, len(arr) - 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            result = mid
            right = mid - 1
        elif arr[mid] < target:
