def insertion_point_binary_search(arr, target):
    """Returns the index where the target should be inserted in a sorted list to maintain order."""
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

