def dfs_path(start, end, path=None, visited=None):
    if path is None:
        path = [start]
    if visited is None:
        visited = set()
    if start == end:
        return path
    visited.add(start)
    for neighbor in graph[start]:
        if neighbor not in visited:
            new_path = path + [neighbor]
            result = dfs_path(neighbor, end, new_path, visited)
            if result:
                return result
    return None

