import heapq

# A priority queue implementation using heapq
# Each item is a tuple (priority, item)

class PriorityQueue:
    def __init__(self):
        self._heap = []

    def push(self, item, priority):
        heapq.heappush(self._heap, (priority, item))

    def pop(self):
        return heapq.heappop(self._heap)[1]

    def is_empty(self):
        return len(self._heap) == 0

if __name__ == "__main__":
    pq = PriorityQueue()
    pq.push("task1", 3)
    pq.push("task2", 1)
    pq.push("task3", 2)
    while not pq.is_empty():
        print(pq.pop())

import heapq

# Find the k smallest numbers in a list using a heap

def find_k_smallest(nums, k):
    """Return the k smallest elements from nums using a heap."""
    if k <= 0 or k > len(nums):
        return []

    heap = nums[:k]
    heapq.heapify(heap)

    for num in nums[k:]:
        if num < heap[0]:
            heapq.heappushpop(heap, num)

    return sorted(heap)

if __name__ == "__main__":
    numbers = [4, 1, 3, 5, 2, 6, 7]
    k = 3
    print(f"The {k} smallest numbers are: {find_k_smallest(numbers, k)}")

