import heapq

# Find the k largest elements in a list using a heap

def find_k_largest(nums, k):
    """Return the k largest elements from nums using a heap."""
    if k <= 0 or k > len(nums):
        return []

    heap = [-num for num in nums[:k]]
    heapq.heapify(heap)

    for num in nums[k:]:
        if num > -heap[0]:
            heapq.heappushpop(heap, -num)

    return [-x for x in sorted(heap, reverse=True)]

if __name__ == "__main__":
    numbers = [4, 1, 3, 5, 2, 6, 7]
    k = 3
    print(f"The {k} largest numbers are: {find_k_largest(numbers, k)}")

