# Finds all start indices of a substring in a main string

def find_all_occurrences(main_str, sub_str):
    """Yields all starting indices of sub_str in main_str."""
    start = 0
    while True:
        pos = main_str.find(sub_str, start)
        if pos == -1:
            break
        yield pos
        start = pos + 1

