# Compares two strings and reports the first differing character

def find_first_difference(str1, str2):
    """Returns the index and characters where str1 and str2 first differ."""
    min_len = min(len(str1), len(str2))
    for i in range(min_len):
        if str1[i] != str2[i]:
            return (i, str1[i], str2[i])
    return (min_len, str1[min_len] if len(str1) > min_len else None, str2[min_len] if len(str2) > min_len else None)

