    result = find_first_difference("hello", "hallo")
    print(f"First difference at index {result[0]}: '{result[1]}' vs '{result[2]}'")

# kmp_matcher.py
# Implements the Knuth-Morris-Pratt (KMP) algorithm for substring matching

def compute_lps(pattern):
    """Computes the Longest Prefix Suffix (LPS) array for the pattern."""
    lps = [0] * len(pattern)
    length = 0
    i = 1
    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    return lps

def kmp_search(text, pattern):
    """Searches for the pattern in the text using KMP algorithm."""
    lps = compute_lps(pattern)
    i = j = 0
    while i < len(text):
        if pattern[j] == text[i]:
            i += 1
            j += 1
            if j == len(pattern):
                print(f"Pattern found at index {i - j}")
                j = lps[j - 1]
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

if __name__ == "__main__":
    kmp_search("abababab", "aba")

