'''
Uses Union-Find to find the number of islands in a binary matrix.
'''

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_x] = root_y

def count_islands(matrix):
    rows, cols = len(matrix), len(matrix[0])
    uf = UnionFind(rows * cols)
    directions = [(0,1), (1,0), (0,-1), (-1,0)]
    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 1:
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and matrix[nr][nc] == 1:
                        uf.union(r * cols + c, nr * cols + nc)
    roots = set()
    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 1:
                roots.add(uf.find(r * cols + c))
    return len(roots)

if __name__ == "__main__":
    matrix = [[1,1,0], [1,0,1], [0,1,1]]
    print(count_islands(matrix))

