# This script implements a simple LRU cache using both a dictionary and an OrderedDict,
# and compares their performance.
import time
import sys
from collections import OrderedDict


def lru_cache_dict(capacity):
    cache = {}
    def get(key):
        if key in cache:
            return cache.pop(key)
        else:
            return None
    def put(key, value):
        if key in cache:
            del cache[key]
        elif len(cache) >= capacity:
            cache.pop(next(iter(cache)))
        cache[key] = value
    return get, put

def lru_cache_ordered_dict(capacity):
    cache = OrderedDict()
    def get(key):
        if key in cache:
            cache.move_to_end(key)
            return cache[key]
        else:
            return None
    def put(key, value):
        if key in cache:
            cache.move_to_end(key)
        cache[key] = value
        if len(cache) > capacity:
            cache.popitem(last=False)
    return get, put

def measure_time_space(get, put, operations, data):
    start_time = time.time()
    for op, key, value in operations:
        if op == 'get':
            get(key)
        elif op == 'put':
            put(key, value)
    end_time = time.time()
    space_used = sys.getsizeof(data)
    return end_time - start_time, space_used

if __name__ == '__main__':
    capacity = 100
    operations = [('put', i, i) for i in range(200)] + [('get', i, None) for i in range(200)]
    get_dict, put_dict = lru_cache_dict(capacity)
    get_ordered_dict, put_ordered_dict = lru_cache_ordered_dict(capacity)

    print("Using Dictionary for LRU Cache:")
    time_taken, space_used = measure_time_space(get_dict, put_dict, operations, get_dict)
    print(f"Time: {time_taken:.6f} seconds, Space: {space_used} bytes")
    print("Using OrderedDict for LRU Cache:")
    time_taken, space_used = measure_time_space(get_ordered_dict, put_ordered_dict, operations, get_ordered_dict)
    print(f"Time: {time_taken:.6f} seconds, Space: {space_used} bytes")

# This script calculates the nth Fibonacci number using dynamic programming with both
# a bottom-up and a top-down approach, comparing their performance in terms of time and space.
import time
import sys
from functools import lru_cache


def bottom_up_fibonacci(n):
    if n <= 1:
        return n
    fib = [0] * (n + 1)
    fib[1] = 1
    for i in range(2, n + 1):
        fib[i] = fib[i - 1] + fib[i - 2]
    return fib[n]

def top_down_fibonacci(n):
    @lru_cache(maxsize=None)
    def fib(k):
        if k <= 1:
            return k
        return fib(k - 1) + fib(k - 2)
    return fib(n)

def measure_time_space(method, n):
    start_time = time.time()
    result = method(n)
    end_time = time.time()
    space_used = sys.getsizeof(result)
    return end_time - start_time, space_used

if __name__ == '__main__':
    n = 30
    print(f"Fibonacci of {n}: Bottom-Up")
    time_taken, space_used = measure_time_space(bottom_up_fibonacci, n)
    print(f"Time: {time_taken:.6f} seconds, Space: {space_used} bytes")
    print(f"Fibonacci of {n}: Top-Down")
    time_taken, space_used = measure_time_space(top_down_fibonacci, n)
    print(f"Time: {time_taken:.6f} seconds, Space: {space_used} bytes")

# This script demonstrates the use of a trie data structure for storing a dictionary of words
# and searching for a prefix, comparing its performance with a list-based approach.
import time
import sys

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()
    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True
    def search_prefix(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

def measure_time_space(method, words, prefix):
    start_time = time.time()
    result = method(words, prefix)
    end_time = time.time()
    space_used = sys.getsizeof(result)
    return end_time - start_time, space_used

def list_insert_search(words, prefix):
    return prefix in words

def trie_insert_search(words, prefix):
    trie = Trie()
    for word in words:
        trie.insert(word)
    return trie.search_prefix(prefix)

if __name__ == '__main__':
    words = [f'word{i}' for i in range(100000)]
    prefix = 'word10'

    print("Using List for Insert and Search:")
    time_taken, space_used = measure_time_space(list_insert_search, words, prefix)
    print(f"Time: {time_taken:.6f} seconds, Space: {space_used} bytes")

    print("Using Trie for Insert and Search:")
    time_taken, space_used = measure_time_space(trie_insert_search, words, prefix)
    print(f"Time: {time_taken:.6f} seconds, Space: {space_used} bytes")

