# This script implements a priority queue using a min heap.
import heapq

class PriorityQueue:
    def __init__(self):
        self._queue = []
        self._index = 0
    def push(self, item, priority):
        # Use a tuple of (priority, index, item) to ensure proper ordering
        heapq.heappush(self._queue, (-priority, self._index, item))
        self._index += 1
    def pop(self):
        # Pop the item with the highest priority (lowest negative value)
        return heapq.heappop(self._queue)[-1]

