# This script finds the k smallest elements in an unsorted list using a max heap.
import heapq

def find_k_smallest(nums, k):
    if k <= 0:
        return []
    if k >= len(nums):
        return sorted(nums)
    max_heap = [-x for x in nums[:k]]
    heapq.heapify(max_heap)
    for num in nums[k:]:
        if -num > max_heap[0]:
            heapq.heapreplace(max_heap, -num)
    return [-x for x in max_heap]

