# This script implements a custom priority queue class using a binary heap.
class PriorityQueue:
    def __init__(self):
        self._queue = []
    def _parent_index(self, index):
        return (index - 1) // 2
    def _left_child_index(self, index):
        return 2 * index + 1
    def _right_child_index(self, index):
        return 2 * index + 2
    def push(self, item, priority):
        self._queue.append((priority, item))
        self._heapify_up(len(self._queue) - 1)
    def pop(self):
        if len(self._queue) > 1:
            self._swap(0, len(self._queue) - 1)
        item = self._queue.pop()
        self._heapify_down(0)
        return item[1]
    def _heapify_up(self, index):
        parent = self._parent_index(index)
        if index and self._queue[index] < self._queue[parent]:
            self._swap(index, parent)
            self._heapify_up(parent)
    def _heapify_down(self, index):
        smallest = index
        left = self._left_child_index(index)
        right = self._right_child_index(index)
        if left < len(self._queue) and self._queue[left] < self._queue[smallest]:
            smallest = left
        if right < len(self._queue) and self._queue[right] < self._queue[smallest]:
            smallest = right
        if smallest != index:
            self._swap(index, smallest)
            self._heapify_down(smallest)
    def _swap(self, i, j):
        self._queue[i], self._queue[j] = self._queue[j], self._queue[i]

if __name__ == '__main__':
    pq = PriorityQueue()
    pq.push('task1', 5)
    pq.push('task2', 2)
    pq.push('task3', 1)
    pq.push('task4', 7)
    while pq._queue:
        print('Popped:', pq.pop())

# This script finds the first pair of numbers in a sorted array that add up to a target sum using the two pointers technique.
def find_first_pair_with_sum(arr, target):
    left, right = 0, len(arr) - 1
    while left < right:
        current_sum = arr[left] + arr[right]
        if current_sum == target:
            return arr[left], arr[right]
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    return None

