# This script removes all duplicates from a sorted array in-place using the two pointers technique, returning the new length of the array.
def remove_duplicates(nums):
    if not nums:
        return 0

    write_index = 1
    for read_index in range(1, len(nums)):
        if nums[read_index] != nums[read_index - 1]:
            nums[write_index] = nums[read_index]
            write_index += 1

    return write_index

