# This script determines if there exists a pair of elements in an array whose product is negative using the two pointers technique.
def has_negative_product_pair(arr):
    arr.sort()
    left, right = 0, len(arr) - 1

    while left < right:
        if arr[left] * arr[right] < 0:
            return True
        elif arr[left] >= 0:
            return False
        elif arr[right] <= 0:
            left += 1
        else:
            right -= 1

    return False

