'''circular_buffer.py
Implements a fixed‑size circular buffer with O(1) append and
negative‑index based retrieval of the newest elements.
The buffer supports standard indexing (0 = oldest) and negative
indices where -1 = most recent.
'''
class CircularBuffer:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError('capacity must be positive')
        self._size = capacity
        self._data = [None] * capacity
        self._head = 0   # points to the oldest element
        self._count = 0  # number of valid elements

    def append(self, value):
        """Add *value* to the buffer, overwriting the oldest when full."""
        idx = (self._head + self._count) % self._size
        self._data[idx] = value
        if self._count == self._size:
            # buffer full – move head forward
            self._head = (self._head + 1) % self._size
        else:
            self._count += 1

    def __len__(self):
        return self._count

    def _translate_index(self, i: int) -> int:
        """Convert a user index (positive or negative) to the internal list index.
        Positive indices count from the oldest element; negative indices count
        backwards from the most recent element.
        """
        if i < 0:
            i = self._count + i  # e.g. -1 becomes count-1
        if not 0 <= i < self._count:
            raise IndexError('index out of range')
        return (self._head + i) % self._size

    def __getitem__(self, i: int):
        return self._data[self._translate_index(i)]

    def __repr__(self):
        contents = [self[i] for i in range(self._count)]
        return f'CircularBuffer({contents})'

if __name__ == '__main__':
    cb = CircularBuffer(5)
    for n in range(7):
        cb.append(n)
        print(cb, ' - most recent:', cb[-1])

'''fib_fast_doubling.py
Fast doubling algorithm for Fibonacci numbers (O(log n) time).
Run: python fib_fast_doubling.py <n>
''' 
import sys

def fib_fast_doubling(n: int) -> int:
    """Return F(n) using the fast‑doubling recurrence.
    The function works recursively and returns the exact integer.
    """
    if n < 0:
        raise ValueError('n must be non‑negative')
    def _helper(k: int) -> tuple[int, int]:
        if k == 0:
            return (0, 1)
        else:
            a, b = _helper(k >> 1)
            c = a * ((b << 1) - a)
            d = a * a + b * b
            if k & 1:
                return (d, c + d)
            else:
                return (c, d)
    return _helper(n)[0]

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python fib_fast_doubling.py <non‑negative integer>')
        sys.exit(1)
    try:
        n = int(sys.argv[1])
    except ValueError:
        print('Please provide an integer.')
        sys.exit(1)
    print(f'F({n}) = {fib_fast_doubling(n)}')

'''fib_multi.py
Module exposing three Fibonacci implementations and a CLI menu.
Run: python fib_multi.py
''' 
import sys
from functools import lru_cache

def fib_iterative(n: int) -> int:
    """Iterative DP using two variables (O(n) time, O(1) space)."""
    if n < 0:
        raise ValueError('n must be non‑negative')
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

@lru_cache(maxsize=None)
def fib_memo(n: int) -> int:
    """Recursive Fibonacci with unlimited memoization (O(n) time)."""
    if n < 0:
        raise ValueError('n must be non‑negative')
    if n in (0, 1):
        return n
    return fib_memo(n - 1) + fib_memo(n - 2)

def fib_fast_doubling(n: int) -> int:
    """Fast‑doubling algorithm (O(log n) time)."""
    if n < 0:
        raise ValueError('n must be non‑negative')
    def _pair(k: int) -> tuple[int, int]:
        if k == 0:
            return (0, 1)
        a, b = _pair(k >> 1)
        c = a * ((b << 1) - a)
        d = a * a + b * b
        return (d, c + d) if k & 1 else (c, d)
    return _pair(n)[0]

def menu() -> None:
    options = {
        '1': ('Iterative DP', fib_iterative),
        '2': ('Memoized recursion', fib_memo),
        '3': ('Fast doubling', fib_fast_doubling),
    }
    print('Choose Fibonacci implementation:')
    for key, (name, _) in options.items():
        print(f'  {key}) {name}')
    choice = input('Enter 1, 2, or 3: ').strip()
    if choice not in options:
        print('Invalid choice.')
        return
    try:
        n = int(input('Enter non‑negative integer n: '))
    except ValueError:
        print('Please enter a valid integer.')
        return
    func_name, func = options[choice]
    try:
        result = func(n)
    except ValueError as e:
        print(e)
        return
    print(f'{func_name}: F({n}) = {result}')

if __name__ == '__main__':
    menu()

'''basic_trie.py
Simple Trie implementation with insert, search and starts_with methods.
''' 

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    """A classic prefix tree supporting insertion and lookup."""
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        """Insert a word into the trie."""
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True

    def search(self, word: str) -> bool:
        """Return True if the complete word exists in the trie."""
        node = self._find_node(word)
        return bool(node and node.is_end)

    def starts_with(self, prefix: str) -> bool:
        """Return True if any word in the trie starts with the given prefix."""
        return self._find_node(prefix) is not None

    def _find_node(self, prefix: str):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

# Example usage (can be removed when importing as a module)
if __name__ == "__main__":
    t = Trie()
    for w in ["apple", "app", "apply", "bat"]:
        t.insert(w)
    print(t.search("app"))        # True
    print(t.search("appl"))       # False
    print(t.starts_with("ap"))    # True
    print(t.starts_with("cat"))   # False

'''trie_with_enumeration.py
Trie that supports insertion, prefix search and enumeration of all words
under a given prefix.
''' 

from typing import List

class Node:
    __slots__ = ("children", "is_word")
    def __init__(self):
        self.children = {}
        self.is_word = False

class Trie:
    def __init__(self, words: List[str] = None):
        self.root = Node()
        if words:
            for w in words:
                self.insert(w)

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, Node())
        node.is_word = True

    def _collect(self, node: Node, prefix: str, out: List[str]):
        if node.is_word:
            out.append(prefix)
        for ch, child in node.children.items():
            self._collect(child, prefix + ch, out)

    def words_with_prefix(self, prefix: str) -> List[str]:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        result: List[str] = []
        self._collect(node, prefix, result)
        return result

if __name__ == "__main__":
    sample = ["cat", "car", "cart", "dog", "dot", "dove"]
    trie = Trie(sample)
    print(trie.words_with_prefix("ca"))   # ['cat', 'car', 'cart']
    print(trie.words_with_prefix("do"))   # ['dog', 'dot', 'dove']
    print(trie.words_with_prefix("z"))    # []

'''radix_trie.py
A simple radix (compact) trie implementation.
Each edge stores a string segment, reducing the number of nodes.
''' 

from typing import Dict, Optional

class RadixNode:
    def __init__(self, label: str = ""):
        self.label: str = label
        self.children: Dict[str, 'RadixNode'] = {}
        self.is_word: bool = False

class RadixTrie:
    def __init__(self):
        self.root = RadixNode()

    def insert(self, word: str) -> None:
        node = self.root
        while word:
            # Find a child whose label shares a prefix with the remaining word
            for edge, child in node.children.items():
                common = self._common_prefix(edge, word)
                if common:
                    if common == edge:
                        # Edge fully matches, descend
                        word = word[len(common):]
                        node = child
                        break
                    else:
                        # Split the edge
                        suffix = edge[len(common):]
                        split_node = RadixNode(suffix)
                        split_node.children = child.children
                        split_node.is_word = child.is_word
                        # Adjust original edge
                        node.children[common] = split_node
                        del node.children[edge]
                        if common == word:
                            split_node.is_word = True
                            return
                        else:
                            # Add remaining part as new child
                            new_child = RadixNode(word[len(common):])
                            new_child.is_word = True
                            split_node.children[new_child.label] = new_child
                            return
            else:
                # No matching edge, create a new leaf
                node.children[word] = RadixNode("")
                node.children[word].is_word = True
                return

    def search(self, word: str) -> bool:
        node = self.root
        while word:
            for edge, child in node.children.items():
                if word.startswith(edge):
                    word = word[len(edge):]
                    node = child
                    break
                if edge.startswith(word):
                    # word ends in the middle of an edge
                    return False
            else:
                return False
        return node.is_word

    @staticmethod
    def _common_prefix(a: str, b: str) -> str:
        i = 0
        while i < len(a) and i < len(b) and a[i] == b[i]:
            i += 1
        return a[:i]

if __name__ == "__main__":
    rt = RadixTrie()
    for w in ["test", "testing", "team", "toast"]:
        rt.insert(w)
    print(rt.search("test"))      # True
    print(rt.search("tes"))       # False
    print(rt.search("testing"))   # True
    print(rt.search("toast"))     # True
    print(rt.search("toaster"))   # False

'''trie_visualizer.py
