'''autocomplete_trie.py
Trie that stores words with a frequency count and returns up to five
most frequent completions for a given prefix.
''' 

import heapq
from typing import Dict, List, Tuple

class ANode:
    def __init__(self):
        self.children: Dict[str, ANode] = {}
        self.is_word: bool = False
        self.freq: int = 0  # frequency of the word ending here

class AutocompleteTrie:
    def __init__(self):
        self.root = ANode()

    def insert(self, word: str, count: int = 1) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, ANode())
        node.is_word = True
        node.freq += count

    def _collect(self, node: ANode, prefix: str, heap: List[Tuple[int, str]]):
        if node.is_word:
            # Use negative frequency because heapq is a min‑heap
            heapq.heappush(heap, (-node.freq, prefix))
            if len(heap) > 5:
                heapq.heappop(heap)
        for ch, child in node.children.items():
            self._collect(child, prefix + ch, heap)

    def suggest(self, prefix: str) -> List[str]:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        heap: List[Tuple[int, str]] = []
        self._collect(node, prefix, heap)
        # heap contains up to 5 items with highest freq (negative values)
        return [word for _, word in sorted(heap, reverse=True)]

if __name__ == "__main__":
    ac = AutocompleteTrie()
    data = [("apple", 5), ("app", 3), ("application", 2), ("apt", 4), ("apex", 1), ("banana", 6)]
    for w, c in data:
        ac.insert(w, c)
    print(ac.suggest("ap"))   # Expected top 5 among apple, app, application, apt, apex
    print(ac.suggest("ba"))   # ['banana']

'''concurrent_trie.py
Thread‑safe Trie implementation using a read‑write lock.
Multiple reader threads can search simultaneously, while writers obtain exclusive access.
''' 

import threading
from typing import Dict

class RWLock:
    """A simple reader‑writer lock allowing multiple concurrent reads."""
    def __init__(self):
        self._read_ready = threading.Condition(threading.Lock())
        self._readers = 0

    def acquire_read(self):
        with self._read_ready:
            self._readers += 1

    def release_read(self):
        with self._read_ready:
            self._readers -= 1
            if self._readers == 0:
                self._read_ready.notify_all()

    def acquire_write(self):
        self._read_ready.acquire()
        while self._readers > 0:
            self._read_ready.wait()

    def release_write(self):
        self._read_ready.release()

class CNode:
    def __init__(self):
        self.children: Dict[str, CNode] = {}
        self.is_word: bool = False

class ConcurrentTrie:
    def __init__(self):
        self.root = CNode()
        self.lock = RWLock()

    def insert(self, word: str) -> None:
        self.lock.acquire_write()
        try:
            node = self.root
            for ch in word:
                node = node.children.setdefault(ch, CNode())
            node.is_word = True
        finally:
            self.lock.release_write()

    def search(self, word: str) -> bool:
        self.lock.acquire_read()
        try:
            node = self.root
            for ch in word:
                if ch not in node.children:
                    return False
                node = node.children[ch]
            return node.is_word
        finally:
            self.lock.release_read()

