'''type_validated.py
Descriptor that enforces the type of an attribute at assignment time.
Includes a simple Person class that uses the descriptor for age and height.
''' 

class Typed:
    """Descriptor enforcing that assigned values match *expected_type*.
    Usage: name = Typed(int) creates an attribute that only accepts integers.
    """
    def __init__(self, expected_type, default=None):
        self.expected_type = expected_type
        self.default = default
        self.name = None  # will be set by __set_name__

    def __set_name__(self, owner, name):
        self.name = name
        # Store a private name to avoid recursion in __get__ and __set__
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name, self.default)

    def __set__(self, instance, value):
        if not isinstance(value, self.expected_type):
            raise TypeError(f"{self.name} must be of type {self.expected_type.__name__}")
        setattr(instance, self.private_name, value)

    def __delete__(self, instance):
        raise AttributeError(f"Can't delete attribute '{self.name}'")


class Person:
    """Simple class demonstrating Typed descriptors.
    *age* must be an int, *height* must be a float.
    """
    age = Typed(int, default=0)
    height = Typed(float, default=0.0)

    def __init__(self, name, age, height):
        self.name = name
        self.age = age          # validated by Typed
        self.height = height    # validated by Typed

    def __repr__(self):
        return f"Person(name={self.name!r}, age={self.age}, height={self.height})"


if __name__ == "__main__":
    p = Person("Alice", 30, 1.68)
    print(p)
    try:
        p.age = "thirty"
    except TypeError as e:
        print("Error:", e)
    p.height = 1.70  # valid update
    print("Updated height:", p.height)

'''tag_manager.py
A compact class that keeps a collection of unique tags.
The ``tags`` attribute is a property with custom getter, setter, and deleter.
''' 

class TagContainer:
    """Container that stores unique, sorted tags.
    The internal storage is a private list ``_tags``.  Assigning via the
    ``tags`` property replaces the collection after de‑duplicating and sorting.
    Deleting ``tags`` clears the list.
    """

    def __init__(self, initial=None):
        self._tags = []
        if initial:
            self.tags = initial  # invoke the setter for validation

    @property
    def tags(self):
        """Return a copy of the current tag list."""
        return list(self._tags)

    @tags.setter
    def tags(self, new_tags):
        """Replace tags with *new_tags* after removing duplicates.
        ``new_tags`` can be any iterable of hashable items.
        """
        # Convert to set to drop duplicates, then back to sorted list
        unique = sorted(set(new_tags))
        self._tags = unique

    @tags.deleter
    def tags(self):
        """Clear all tags."""
        self._tags.clear()

    def add(self, tag):
        """Add a single *tag* if it is not already present."""
        if tag not in self._tags:
            self._tags.append(tag)
            self._tags.sort()

    def remove(self, tag):
        """Remove *tag* if it exists; otherwise raise ValueError."""
        self._tags.remove(tag)

    def __repr__(self):
        return f"TagContainer(tags={self._tags})"


if __name__ == "__main__":
    tc = TagContainer(["python", "code", "python", "example"])
    print(tc)               # duplicates removed, sorted
    tc.add("tutorial")
    print(tc.tags)           # property returns a copy
    tc.tags = ["new", "code", "new"]
    print(tc)
    del tc.tags
    print("After delete:", tc)

'''readonly_once.py
Descriptor that computes a value on first access and then becomes immutable.
It mimics a read‑only @property but stores the result in the instance for
future accesses, preventing further recomputation.
''' 

class ReadOnlyOnce:
    """Descriptor that evaluates *func* once and then disallows changes.
    The wrapped function receives only the instance and should be pure.
    """
    def __init__(self, func):
        self.func = func
        self.name = func.__name__
        self.private_name = f"_{self.name}"

    def __set_name__(self, owner, name):
        # In case the descriptor is used with a different attribute name
        self.name = name
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        if not hasattr(instance, self.private_name):
            # First access – compute and store
            value = self.func(instance)
            setattr(instance, self.private_name, value)
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        raise AttributeError(f"{self.name} is read‑only and cannot be assigned")

    def __delete__(self, instance):
        raise AttributeError(f"{self.name} cannot be deleted")


def readonly_once(func):
    """Decorator shortcut for creating a ReadOnlyOnce descriptor."""
    return ReadOnlyOnce(func)


class Config:
    """Example class where ``uid`` is generated once and then immutable.
    The uid is a simple hash of the object's id combined with a random seed.
    """
    import os, hashlib
    _seed = os.urandom(8)

    @readonly_once
    def uid(self):
        # Heavy work simulated by hashing; runs only once per instance
        data = f"{id(self)}-{self._seed}".encode()
        return hashlib.sha256(data).hexdigest()[:16]

    def __repr__(self):
        return f"Config(uid={self.uid})"


if __name__ == "__main__":
    c1 = Config()
    c2 = Config()
    print("c1 uid:", c1.uid)
    print("c2 uid:", c2.uid)
    try:
        c1.uid = "newvalue"
    except AttributeError as e:
        print("Assignment error:", e)

'''logging_descriptor.py
A descriptor that prints a message whenever the managed attribute is accessed,
assigned, or deleted.  Used by the Sample class to show how descriptors can
hook into attribute lifecycle events.
''' 

class LoggedAttr:
    """Descriptor that logs access, assignment, and deletion.
    It stores the actual value in a private attribute on the instance.
    """
    def __init__(self, name, default=None):
        self.public_name = name
        self.private_name = f"_{name}"
        self.default = default

    def __set_name__(self, owner, name):
        # Allows the descriptor to be used with a different attribute name
        self.public_name = name
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        value = getattr(instance, self.private_name, self.default)
        print(f"[GET] {self.public_name!r} -> {value!r}")
        return value

    def __set__(self, instance, value):
        print(f"[SET] {self.public_name!r} = {value!r}")
        setattr(instance, self.private_name, value)

    def __delete__(self, instance):
        print(f"[DELETE] {self.public_name!r}")
        if hasattr(instance, self.private_name):
            delattr(instance, self.private_name)
        else:
            raise AttributeError(f"{self.public_name} not set")


class Sample:
    """Class using LoggedAttr for two attributes: ``x`` and ``y``.
    ``x`` has a default of 0, ``y`` starts unset.
    """
    x = LoggedAttr('x', default=0)
    y = LoggedAttr('y')

    def __init__(self, x=None, y=None):
        if x is not None:
            self.x = x
        if y is not None:
            self.y = y

    def __repr__(self):
        return f"Sample(x={self.x}, y={self.y})"


if __name__ == "__main__":
    s = Sample()
    s.x = 10          # triggers __set__ logging
    print(s.x)       # triggers __get__ logging
    s.y = "hello"
    print(s)
    del s.x           # triggers __delete__ logging
    try:
        del s.y
    except AttributeError as e:
        print("Error:", e)

'''bounded_property.py
Demonstrates a descriptor that stores a numeric value and a property
that validates the range on assignment.  The class ``Sensor`` uses the
combination to keep its ``level`` attribute between 0 and 100.
''' 

class BoundedNumber:
    """Descriptor storing a numeric value without validation.
    Validation is delegated to the owning class's property setter.
    """
    def __init__(self, name, default=0):
        self.name = name
        self.private_name = f"_{name}"
        self.default = default

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name, self.default)

    def __set__(self, instance, value):
        # Direct assignment bypasses validation – used only internally
        setattr(instance, self.private_name, value)

    def __delete__(self, instance):
        raise AttributeError(f"Can't delete attribute '{self.name}'")


class Sensor:
    """Example class where ``level`` must stay within 0‑100.
    The descriptor holds the raw value; the property setter enforces the range.
    """
    _level = BoundedNumber('level')  # internal storage via descriptor

    @property
    def level(self):
        """Return the current level (0‑100)."""
        return self._level

    @level.setter
    def level(self, value):
        """Validate *value* and store it through the descriptor.
        Raises ``ValueError`` if the value is outside the permitted range.
        """
        if not isinstance(value, (int, float)):
            raise TypeError('level must be a number')
        if not (0 <= value <= 100):
            raise ValueError('level must be between 0 and 100')
        self._level = value  # goes through BoundedNumber.__set__

    @level.deleter
    def level(self):
        """Reset the level to its default (0)."""
        self._level = 0

    def __repr__(self):
        return f"Sensor(level={self.level})"


if __name__ == "__main__":
    s = Sensor()
    print(s)
    s.level = 42
    print('Updated:', s)
    try:
        s.level = 150
    except ValueError as e:
        print('Error:', e)
    del s.level
    print('After delete:', s)

'''union_find_with_size.py
Union‑Find data structure that stores component sizes and can retrieve members.
'''

from collections import defaultdict

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.size = [1] * n
        # optional mapping from root to members for quick retrieval
        self.members = {i: {i} for i in range(n)}

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        # union by rank
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.members[ra].update(self.members[rb])
        del self.members[rb]
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        return True

    def component_size(self, x: int) -> int:
        return self.size[self.find(x)]

    def get_members(self, x: int) -> set:
        """Return a set of all vertices in the component containing `x`."""
        return self.members[self.find(x)]

    def connected(self, a: int, b: int) -> bool:
        return self.find(a) == self.find(b)

if __name__ == '__main__':
    uf = UnionFind(7)
    uf.union(0, 1)
    uf.union(1, 2)
    uf.union(4, 5)
    print('Size of component containing 1:', uf.component_size(1))
    print('Members of component containing 5:', uf.get_members(5))
    print('All component roots:', list(uf.members.keys()))

'''components_from_edges.py
Read an undirected graph as an edge list from standard input.
Each line: "u v" (0‑based vertex indices). The script outputs the count of connected components.
'''

import sys

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = n  # number of distinct sets

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        self.count -= 1

def main():
    edges = []
    max_vertex = -1
    for line in sys.stdin:
        if not line.strip():
            continue
        u, v = map(int, line.split())
        edges.append((u, v))
        max_vertex = max(max_vertex, u, v)
    if max_vertex < 0:
        print(0)
        return
    uf = UnionFind(max_vertex + 1)
    for u, v in edges:
        uf.union(u, v)
    print(uf.count)

if __name__ == '__main__':
    main()

'''union_find_undo.py
Union‑Find with persistent stack allowing the most recent union to be undone.
Useful for backtracking algorithms.
'''

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.stack = []  # history of changes for undo

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            self.stack.append(None)  # no change to undo
            return False
        # ensure ra has higher rank
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        # record state before modification
        self.stack.append((rb, self.parent[rb], ra, self.rank[ra]))
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        return True

    def undo(self) -> None:
        """Revert the most recent union (or no‑op if it did nothing)."""
        if not self.stack:
            return
        record = self.stack.pop()
        if record is None:
            return  # union had no effect
        rb, old_parent, ra, old_rank = record
        self.parent[rb] = old_parent
        self.rank[ra] = old_rank

    def connected(self, a: int, b: int) -> bool:
        return self.find(a) == self.find(b)

if __name__ == '__main__':
    uf = UnionFind(5)
    uf.union(0, 1)
    uf.union(1, 2)
    print('Connected 0‑2?', uf.connected(0, 2))
    uf.undo()
    print('After undo, connected 0‑2?', uf.connected(0, 2))

'''kruskal_mst.py
Provides `UnionFind` and `kruskal(edges, n)` which returns a list of edges in the Minimum Spanning Tree.
Edges are tuples ``(weight, u, v)`` with vertices numbered 0..n-1.
'''

from typing import List, Tuple

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        return True

def kruskal(edges: List[Tuple[int, int, int]], n: int) -> List[Tuple[int, int, int]]:
    """Return edges of the Minimum Spanning Tree using Kruskal's algorithm.
    `edges` must be ``(weight, u, v)``; `n` is number of vertices.
    """
    uf = UnionFind(n)
    mst: List[Tuple[int, int, int]] = []
    for w, u, v in sorted(edges, key=lambda e: e[0]):
        if uf.union(u, v):
            mst.append((w, u, v))
            if len(mst) == n - 1:
                break
    return mst

if __name__ == '__main__':
    example = [
        (1, 0, 1),
        (3, 0, 2),
        (2, 1, 2),
        (4, 1, 3),
        (5, 2, 3)
    ]
    tree = kruskal(example, 4)
    print('MST edges:', tree)
    print('Total weight:', sum(w for w, _, _ in tree))

'''friend_circles.py
Solution class for LeetCode 547 – Friend Circles (Number of Provinces).
Uses Union‑Find to merge directly connected students and counts distinct groups.
'''

from typing import List

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a: int, b: int) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1

class Solution:
    def findCircleNum(self, M: List[List[int]]) -> int:
        if not M:
            return 0
        n = len(M)
        uf = UnionFind(n)
        for i in range(n):
            for j in range(i + 1, n):
                if M[i][j] == 1:
                    uf.union(i, j)
        roots = {uf.find(i) for i in range(n)}
        return len(roots)

