# dictlist_to_indexed_dicts.py
"""Transform a mapping of column names to column values into indexed records.

Given something like:
    data = {"name": ["Ann", "Bob"], "score": [5, 7]}
the module produces:
    [{"idx": 0, "name": "Ann", "score": 5},
     {"idx": 1, "name": "Bob", "score": 7}]
"""

from __future__ import annotations

from typing import Dict, List, Any


def zip_dict_of_lists(data: Dict[str, List[Any]]) -> List[Dict[str, Any]]:
    """Return a list of records where each record is a dict of column/value pairs.

    The function first checks that all lists have the same length, then zips them
    preserving the original key order (Python 3.7+ guarantees insertion order).
    An "idx" key is added using enumerate.
    """
    if not data:
        return []
    # Ensure uniform length
    lengths = {len(v) for v in data.values()}
    if len(lengths) != 1:
        raise ValueError("All lists must have the same length")
    keys = list(data.keys())
    zipped = zip(*[data[k] for k in keys])
    result: List[Dict[str, Any]] = []
    for idx, values in enumerate(zipped):
        record = {"idx": idx}
        record.update(dict(zip(keys, values)))
        result.append(record)
    return result


def main() -> None:
    sample = {"name": ["Ann", "Bob", "Cathy"], "score": [5, 7, 9], "passed": [True, True, False]}
    for rec in zip_dict_of_lists(sample):
        print(rec)


if __name__ == "__main__":
    main()

'''custom_set.py
A minimal reimplementation of a mathematical set using a list internally.
The class supports basic operations: add, remove, __contains__, union, intersection.
It does not rely on Python's built‑in `set` type.
'''

from typing import Iterable, List, Any

class CustomSet:
    def __init__(self, iterable: Iterable[Any] = ()):
        """Create a new CustomSet containing unique elements from *iterable*."""
        self._data: List[Any] = []
        for item in iterable:
            self.add(item)

    def add(self, value: Any) -> None:
        """Add *value* if it is not already present."""
        if value not in self:
            self._data.append(value)

    def remove(self, value: Any) -> None:
        """Remove *value*; raise KeyError if absent."""
        try:
            self._data.remove(value)
        except ValueError:
            raise KeyError(value)

    def __contains__(self, item: Any) -> bool:
        return item in self._data

    def __len__(self) -> int:
        return len(self._data)

    def __iter__(self):
        return iter(self._data)

    def union(self, other: 'CustomSet') -> 'CustomSet':
        """Return a new CustomSet containing elements from self and other."""
        result = CustomSet(self)
        for elem in other:
            result.add(elem)
        return result

    def intersection(self, other: 'CustomSet') -> 'CustomSet':
        """Return a new CustomSet with elements common to both sets."""
        return CustomSet([elem for elem in self if elem in other])

    def __repr__(self) -> str:
        return f"CustomSet({self._data})"

if __name__ == "__main__":
    a = CustomSet([1, 2, 3])
    b = CustomSet([3, 4, 5])
    print("A:", a)
    print("B:", b)
    print("A union B:", a.union(b))
    print("A intersection B:", a.intersection(b))
    a.add(4)
    print("A after adding 4:", a)
    a.remove(2)
    print("A after removing 2:", a)

"""memoize_closure.py
Implements a simple memoization decorator using a closure.
"""

from functools import wraps

def memoize(func):
    """Return a wrapped version of *func* that caches results.
    The cache dictionary lives in the enclosing scope of the wrapper.
    """
    cache = {}

    @wraps(func)
    def wrapper(*args):
        if args in cache:
            return cache[args]
        result = func(*args)
        cache[args] = result
        return result

    return wrapper

# Example of an expensive calculation
@memoize
def fib(n: int) -> int:
    """Return the n‑th Fibonacci number using naive recursion.
    The memoizer makes repeated calls efficient.
    """
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

if __name__ == "__main__":
    for i in range(10):
        print(f"fib({i}) = {fib(i)}")
    # Second call demonstrates cache hit (no visible delay)
    print(f"fib(35) = {fib(35)}")
    print(f"fib(35) again = {fib(35)}")

'''price_report.py
Reads 'prices.csv' (product,price) and prints each line with the price formatted as US dollars.
The script demonstrates file I/O, CSV parsing, and f‑string numeric formatting.
'''

import csv
from pathlib import Path

def load_prices(csv_path: Path) -> list[tuple[str, float]]:
    """Return a list of (product, price) tuples from the CSV file.
    Assumes the second column can be converted to float.
    """
    records = []
    with csv_path.open(newline='') as f:
        reader = csv.reader(f)
        for row in reader:
            if len(row) != 2:
                continue  # skip malformed rows
            product, price_str = row
            try:
                price = float(price_str)
            except ValueError:
                continue
            records.append((product, price))
    return records

def format_currency(amount: float) -> str:
    """Format a number as US currency, e.g. 1234.5 -> $1,234.50"""
    return f"${amount:,.2f}"

def report(csv_file: str) -> None:
    path = Path(csv_file)
    if not path.is_file():
        print(f"File not found: {csv_file}")
        return
    for product, price in load_prices(path):
        print(f"{product:<20} {format_currency(price)}")

if __name__ == "__main__":
    # Example usage: python price_report.py prices.csv
    import sys
    if len(sys.argv) != 2:
        print("Usage: python price_report.py <csv_file>")
    else:
