'''copy_benchmark.py
Creates a large nested dictionary and measures time for shallow vs deep copy.
Outputs the elapsed seconds for each operation.
'''
import copy
import time

def build_structure(depth=5, breadth=10):
    """Return a nested dict where each level contains *breadth* keys.
    The leaf values are simple integers. This creates a fairly large object.
    """
    if depth == 0:
        return {i: i for i in range(breadth)}
    return {i: build_structure(depth - 1, breadth) for i in range(breadth)}

def time_copy(func, data, repeats=5):
    start = time.perf_counter()
    for _ in range(repeats):
        func(data)
    return time.perf_counter() - start

if __name__ == '__main__':
    print('Building nested structure...')
    nested = build_structure(depth=4, breadth=20)
    print('Structure built. Size approx:', len(str(nested)) // 1024, 'KB')
    shallow_time = time_copy(copy.copy, nested)
    deep_time = time_copy(copy.deepcopy, nested)
    print(f'Shallow copy time (5 runs): {shallow_time:.6f} seconds')
    print(f'Deep copy time   (5 runs): {deep_time:.6f} seconds')

