"""median_calc.py
A simple command‑line tool that receives one or more integers and prints their median value.
The integers are supplied after the script name; argparse uses ``nargs='+'`` to collect them.
"""
import argparse
import sys
from typing import List

def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description='Calculate the median of a list of integers.')
    parser.add_argument('numbers', nargs='+', type=int, help='Integers to process')
    return parser.parse_args()

def median(values: List[int]) -> float:
    """Return the median of *values*.
    The list is sorted; for an even length the median is the average of the two central values.
    """
    sorted_vals = sorted(values)
    n = len(sorted_vals)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_vals[mid])
    else:
        return (sorted_vals[mid - 1] + sorted_vals[mid]) / 2.0

def main() -> None:
    args = parse_args()
    if not args.numbers:
        sys.stderr.write('At least one integer is required.\n')
        sys.exit(1)
    print(median(args.numbers))

if __name__ == '__main__':
    main()

