'''copy_logger.py
Utility that detects if an argument received by a function is a shallow
or deep copy of a known original object. Uses identity comparison of
nested mutable elements.
'''

import copy
import types

def is_shallow_copy(orig, candidate):
    """Return True if *candidate* is a shallow copy of *orig*.
    Checks that the top‑level container is a different object but that
    all immediate mutable children are the same by identity.
    """
    if type(orig) is not type(candidate):
        return False
    if id(orig) == id(candidate):
        return False
    # For common containers only – extend as needed
    if isinstance(orig, (list, tuple)):
        return all(id(o) is id(c) for o, c in zip(orig, candidate))
    if isinstance(orig, dict):
        return all(id(orig[k]) is id(candidate[k]) for k in orig)
    return False

def is_deep_copy(orig, candidate):
    """Return True if *candidate* is a deep copy of *orig*.
    All nested mutable objects must have different identities.
    """
    if type(orig) is not type(candidate):
        return False
    if id(orig) == id(candidate):
        return False
    if isinstance(orig, (list, tuple)):
        return all(id(o) != id(c) for o, c in zip(orig, candidate))
    if isinstance(orig, dict):
        return all(id(orig[k]) != id(candidate[k]) for k in orig)
    return False

def copy_logger(func):
    """Decorator that logs copy type of the first argument.
    Assumes the original object is stored as func._original.
    """
    def wrapper(arg, *a, **kw):
        orig = getattr(func, '_original', None)
        if orig is None:
            raise AttributeError('Original object not set on function')
        if is_shallow_copy(orig, arg):
            print('Received a shallow copy')
        elif is_deep_copy(orig, arg):
            print('Received a deep copy')
        else:
            print('Argument is neither a shallow nor a deep copy of the original')
        return func(arg, *a, **kw)
    return wrapper

# Example usage
original_data = {'nums': [1, 2, 3]}

@copy_logger
def process(data):
    # Dummy processing – just return length of inner list
    return len(data['nums'])

# Attach the original for the decorator to compare against
process._original = original_data

if __name__ == '__main__':
    shallow = copy.copy(original_data)
    deep = copy.deepcopy(original_data)
    print('Result shallow:', process(shallow))
    print('Result deep   :', process(deep))

'''prime_stream.py
A minimal infinite prime generator using the classic trial‑division method.
The module also provides a helper to fetch the first *k* primes.
'''

import itertools

def _is_prime(n: int) -> bool:
    """Return ``True`` if *n* is a prime number using trial division."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    limit = int(n ** 0.5) + 1
    for d in range(3, limit, 2):
        if n % d == 0:
            return False
    return True

def primes() -> itertools.chain:
    """Yield an infinite sequence of prime numbers.

    The generator starts at 2 and tests each successive integer with
    ``_is_prime``.  Because it is infinite, callers typically combine it
    with ``itertools.islice`` or a simple ``for`` loop that breaks after a
    desired count.
    """
    candidate = 2
    while True:
        if _is_prime(candidate):
            yield candidate
        candidate += 1

def first_k_primes(k: int):
    """Return a list containing the first *k* primes produced by ``primes``.

    If *k* is non‑positive an empty list is returned.
    """
    if k <= 0:
        return []
    return list(itertools.islice(primes(), k))

if __name__ == "__main__":
    import sys
    try:
        number = int(sys.argv[1]) if len(sys.argv) > 1 else 10
    except ValueError:
        sys.exit("Please pass a positive integer.")
    print(f"First {number} primes:")
    print(first_k_primes(number))

'''batch_processor.py
Utility for splitting an iterable into fixed‑size batches using a generator.
Also contains a simple example processor that sums each batch.
'''

from typing import Iterable, Generator, List, Any

def batched(iterable: Iterable[Any], size: int) -> Generator[List[Any], None, None]:
    """Yield successive *size*-length chunks from *iterable*.

    If the total number of items is not a multiple of *size*, the final
    chunk contains the remaining items.
    """
    if size <= 0:
        raise ValueError("size must be a positive integer")
    batch: List[Any] = []
    for item in iterable:
        batch.append(item)
        if len(batch) == size:
            yield batch
            batch = []
    if batch:
        yield batch

def process_batch(batch: List[int]) -> int:
    """Example processing function – returns the sum of the integers in *batch*."""
    return sum(batch)

if __name__ == "__main__":
    data = list(range(1, 21))  # 1 .. 20
    batch_size = 6
    for i, b in enumerate(batched(data, batch_size), 1):
        result = process_batch(b)
        print(f"Batch {i} (size {len(b)}): {b} -> sum = {result}")

'''temp_environ.py
Context manager that temporarily overrides os.environ entries.
After the block finishes, the original environment is restored.
''' 

import os
from typing import Dict, Iterable, Tuple

class temporary_environ:
    """Temporarily set environment variables.

    Parameters
    ----------
    updates : dict
        Mapping of variable names to the temporary values. Variables set to None are
        removed for the duration of the block.
    """

    def __init__(self, updates: Dict[str, str]):
        self.updates = updates
        self.original: Dict[str, str] = {}
        self.removed: Iterable[str] = []

    def __enter__(self) -> None:
        # Save current state for keys we will touch
        for key in self.updates:
            if key in os.environ:
                self.original[key] = os.environ[key]
            else:
                self.removed = (*self.removed, key)
        # Apply updates
        for key, value in self.updates.items():
            if value is None:
                os.environ.pop(key, None)
            else:
                os.environ[key] = value

    def __exit__(self, exc_type, exc_val, exc_tb) -> bool:
        # Restore original values
        for key in self.updates:
            if key in self.original:
                os.environ[key] = self.original[key]
            else:
                os.environ.pop(key, None)
        # Propagate any exception
        return False

# Demo when executed directly
if __name__ == "__main__":
    os.environ["EXAMPLE"] = "original"
    print("Before: EXAMPLE=", os.getenv("EXAMPLE"))
    with temporary_environ({"EXAMPLE": "temporary", "NEW_VAR": "added"}):
        print("Inside: EXAMPLE=", os.getenv("EXAMPLE"), "NEW_VAR=", os.getenv("NEW_VAR"))
    print("After: EXAMPLE=", os.getenv("EXAMPLE"), "NEW_VAR=", os.getenv("NEW_VAR"))

