'''\
inventory.py
-----------
A tiny inventory management example using dataclasses. Each Item stores a name,
quantity and an optional price. The Inventory class provides add, remove and list
operations while keeping the internal state consistent.
'''

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List


@dataclass(frozen=True)
class Item:
    """Immutable representation of a product in the inventory."""
    sku: str  # stock keeping unit, unique identifier
    name: str
    price: float = 0.0

    def __post_init__(self) -> None:
        if self.price < 0:
            raise ValueError('price cannot be negative')


@dataclass
class Inventory:
    """Collects Items together with their current stock levels."""
    _stock: Dict[str, int] = field(default_factory=dict)  # sku -> quantity
    _catalog: Dict[str, Item] = field(default_factory=dict)  # sku -> Item object

    def add(self, item: Item, qty: int = 1) -> None:
        """Add *qty* units of *item* to the inventory. New items are added to the catalog."""
        if qty <= 0:
            raise ValueError('quantity to add must be positive')
        self._catalog[item.sku] = item
        self._stock[item.sku] = self._stock.get(item.sku, 0) + qty

    def remove(self, sku: str, qty: int = 1) -> None:
        """Remove *qty* units of the product with *sku*. Raises if insufficient stock."""
        if qty <= 0:
            raise ValueError('quantity to remove must be positive')
        if sku not in self._stock:
            raise KeyError(f'Item {sku} not found in inventory')
        if self._stock[sku] < qty:
            raise ValueError('not enough stock to remove requested amount')
        self._stock[sku] -= qty
        if self._stock[sku] == 0:
            # keep catalog entry but zero stock is acceptable
            pass

    def list_items(self) -> List[Dict[str, object]]:
        """Return a list of dictionaries describing each stocked item."""
        result = []
        for sku, qty in self._stock.items():
            if qty == 0:
                continue
            item = self._catalog[sku]
            result.append({
                'sku': sku,
                'name': item.name,
                'price': item.price,
                'quantity': qty
            })
        return result

    def total_value(self) -> float:
        """Calculate total monetary value of all stocked items."""
        return sum(self._catalog[sku].price * qty for sku, qty in self._stock.items())


if __name__ == "__main__":
    inv = Inventory()
    inv.add(Item(sku='A100', name='Widget', price=2.5), qty=10)
    inv.add(Item(sku='B200', name='Gadget', price=5.0), qty=5)
    inv.remove('A100', qty=3)
    print('Current stock:', inv.list_items())
    print('Total value: $', inv.total_value())

