#!/usr/bin/env python3
"""Depth‑First Search on a weighted graph while tracking node depth.

The graph is represented as a dictionary mapping a node to a list of
``(neighbour, weight)`` pairs.  Edge weights are *not* used for traversal order;
they are stored only to illustrate that the structure can hold additional
information.

Running the module as a script prints each visited vertex together with its
depth (distance in edges from the start vertex).
"""
import sys
from typing import Dict, List, Tuple, Set

AdjWeighted = Dict[str, List[Tuple[str, float]]]

def dfs_depth(start: str, adj: AdjWeighted) -> Dict[str, int]:
    """Return a mapping from node to its depth in the DFS tree.

    Depth of the start node is defined as 0.  Nodes unreachable from ``start``
    are omitted from the result.
    """
    if start not in adj:
        return {}
    depth: Dict[str, int] = {}
    visited: Set[str] = set()
    stack: List[Tuple[str, int]] = [(start, 0)]  # (node, depth)
    while stack:
        node, d = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        depth[node] = d
        # Push neighbours; order is lexical on neighbour name.
        for nbr, _ in sorted(adj.get(node, []), key=lambda x: x[0], reverse=True):
            if nbr not in visited:
                stack.append((nbr, d + 1))
    return depth


def main() -> None:
    # Sample weighted adjacency list.
    graph: AdjWeighted = {
        'A': [('B', 2.5), ('C', 1.0)],
        'B': [('D', 0.5), ('E', 3.2)],
        'C': [('F', 4.1)],
        'D': [],
        'E': [('F', 1.7)],
        'F': []
    }
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python dfs_weighted_depth.py <start-node>\n")
        sys.exit(1)
    start = sys.argv[1]
    depths = dfs_depth(start, graph)
    for node, d in sorted(depths.items(), key=lambda x: x[1]):
        print(f"{node}: depth {d}")

if __name__ == "__main__":
    main()

