'''stability_decorator.py
Provides a @stable_test decorator that runs a supplied sorting function on a
crafted list of (key, tag) pairs and raises AssertionError if the sort is not
stable.
Example usage shows the decorator applied to a correct merge sort and to a
hand‑crafted unstable insertion sort.
''' 
from typing import Callable, List, Tuple, Any
import functools

Pair = Tuple[int, int]  # (key, tag) where tag records original order

def _make_test_data() -> List[Pair]:
    # Keys repeat to expose stability issues; tags are sequential identifiers
    return [(k, i) for i, k in enumerate([3, 1, 2, 3, 2, 1, 3])]

def _is_stable(sorted_lst: List[Pair]) -> bool:
    last_key = None
    last_tag = -1
    for key, tag in sorted_lst:
        if key == last_key and tag < last_tag:
            return False
        last_key, last_tag = key, tag
    return True

def stable_test(sort_func: Callable[[List[Pair]], List[Pair]]) -> Callable[[List[Pair]], List[Pair]]:
    """Decorator that checks stability of *sort_func*.
    The wrapped function is called with a predefined dataset; if the result is
    not stable an AssertionError is raised.
    """
    @functools.wraps(sort_func)
    def wrapper(data: List[Pair] = None) -> List[Pair]:
        test_data = _make_test_data() if data is None else data
        result = sort_func(list(test_data))  # work on a copy
        if not _is_stable(result):
            raise AssertionError(f"{sort_func.__name__} produced an unstable ordering")
        return result
    return wrapper

# Example of a stable merge sort
def merge_sort(lst: List[Pair]) -> List[Pair]:
    if len(lst) <= 1:
        return lst
    mid = len(lst) // 2
    left = merge_sort(lst[:mid])
    right = merge_sort(lst[mid:])
    merged: List[Pair] = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i][0] <= right[j][0]:
            merged.append(left[i]); i += 1
        else:
            merged.append(right[j]); j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged

@stable_test
def stable_merge(lst: List[Pair]) -> List[Pair]:
    return merge_sort(lst)

# Example of an intentionally unstable insertion sort
def unstable_insertion(lst: List[Pair]) -> List[Pair]:
    for i in range(1, len(lst)):
        key = lst[i]
        j = i - 1
        while j >= 0 and lst[j][0] > key[0]:
            lst[j + 1] = lst[j]
            j -= 1
        # Force a swap when equal to break stability
        if j >= 0 and lst[j][0] == key[0]:
            lst[j], key = key, lst[j]
        lst[j + 1] = key
    return lst

@stable_test
def unstable_sort(lst: List[Pair]) -> List[Pair]:
    return unstable_insertion(lst)

