'''fib_cli.py
A tiny command‑line tool that prints the n‑th Fibonacci number.
It uses functools.lru_cache for memoisation and demonstrates a simple CLI.
'''
import argparse
from functools import lru_cache, wraps

def cli_entry(func):
    """Wrap the target function so that it prints its result and returns it.
    This decorator is only for demonstration; it mimics a typical CLI handler.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        print(result)
        return result
    return wrapper

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """Return the n‑th Fibonacci number using recursion.
    The lru_cache ensures each value is computed once.
    """
    if n < 0:
        raise ValueError('n must be non‑negative')
    if n in (0, 1):
        return n
    return fib(n - 1) + fib(n - 2)

@cli_entry
def main():
    parser = argparse.ArgumentParser(description='Compute Fibonacci numbers')
    parser.add_argument('n', type=int, help='Index of the Fibonacci number')
    args = parser.parse_args()
    return fib(args.n)

if __name__ == '__main__':
    main()

