import time
from functools import wraps, lru_cache

def log_calls(func):
    """Decorator that logs the call signature and the returned value.
    It uses functools.wraps to preserve the original function's metadata.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        arg_list = ', '.join([repr(a) for a in args] +
                             [f"{k}={v!r}" for k, v in kwargs.items()])
        print(f"Calling {func.__name__}({arg_list})")
        result = func(*args, **kwargs)
        print(f"{func.__name__} returned {result!r}")
        return result
    return wrapper

@log_calls
@lru_cache(maxsize=None)
def slow_factorial(n: int) -> int:
    """Compute n! with an artificial delay to illustrate caching.
    The function sleeps for 0.1 s per multiplication.
    """
    if n < 0:
        raise ValueError('n must be non‑negative')
    if n in (0, 1):
        return 1
    time.sleep(0.1)  # simulate work
    return n * slow_factorial(n - 1)

if __name__ == '__main__':
    for i in range(5, 8):
        print(f"Factorial of {i}: {slow_factorial(i)}")
        # second call should hit cache instantly
        print(f"Repeated call: {slow_factorial(i)}")

'''memo_partial.py
Utility library exposing two decorators:
- @memoize wraps a function with lru_cache preserving its signature.
- partial_apply returns a new function with selected arguments pre‑filled.
Both utilities keep original metadata via functools.wraps.
'''
from functools import wraps, lru_cache, partial
from typing import Any, Callable

def memoize(maxsize: int = 128):
    """Decorator factory that applies lru_cache to the target function.
    The wrapper keeps the original function's name and docstring.
    """
    def decorator(func: Callable) -> Callable:
        cached = lru_cache(maxsize=maxsize)(func)
        @wraps(func)
        def wrapper(*args, **kwargs):
            return cached(*args, **kwargs)
        return wrapper
    return decorator

def partial_apply(func: Callable, /, *fixed_args: Any, **fixed_kwargs: Any) -> Callable:
    """Return a new function with *fixed_args* and *fixed_kwargs* bound.
    The resulting function accepts the remaining arguments in normal order.
    """
    base = partial(func, *fixed_args, **fixed_kwargs)
    @wraps(func)
    def wrapper(*args, **kwargs):
        return base(*args, **kwargs)
    return wrapper

# Example usage within the module (can be removed when imported)
@memoize(maxsize=64)
def fibonacci(n: int) -> int:
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

# Fixed‑base power function using partial_apply
def power(base: float, exponent: int) -> float:
    return base ** exponent

square = partial_apply(power, base=2)
cube = partial_apply(power, base=3)

if __name__ == '__main__':
    print('fib(10)=', fibonacci(10))
    print('square(5)=', square(5))
    print('cube(2)=', cube(2))

'''class_logger_cache.py
Shows how to wrap a method with @wraps for logging and cache a computed property.
The CachedCalculator class has an expensive _compute method that is logged,
and a result property that is memoised with lru_cache.
'''
import time
from functools import wraps, lru_cache

def log_method(method):
    @wraps(method)
    def wrapper(self, *args, **kwargs):
        print(f"Entering {method.__name__} with args={args}, kwargs={kwargs}")
        start = time.perf_counter()
        value = method(self, *args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"Exiting {method.__name__} (took {elapsed:.4f}s) -> {value}")
        return value
    return wrapper

class CachedCalculator:
    def __init__(self, factor: int):
        self.factor = factor

    @log_method
    def _compute(self, n: int) -> int:
        """Simulate a heavy calculation by sleeping then multiplying.
        The factor attribute scales the result.
        """
        time.sleep(0.2)  # simulate work
        return n * self.factor

    @property
    @lru_cache(maxsize=None)
    def result(self) -> int:
        """Cache the result of a fixed computation (e.g., _compute(5))."""
        return self._compute(5)

if __name__ == '__main__':
    calc = CachedCalculator(7)
    print('First access:', calc.result)   # triggers compute + log
    print('Second access:', calc.result)  # cached, no log

