# An iterator that walks through a sequence backwards.

class ReverseIterator:
    """Iterate over any sequence in reverse order.

    The constructor receives any object that implements __len__ and __getitem__.
    """

    def __init__(self, data):
        self.data = data
        self.index = len(data)  # start just past the last element

    def __iter__(self):
        return self

    def __next__(self):
        if self.index == 0:
            raise StopIteration
        self.index -= 1
        return self.data[self.index]

