# An iterator that yields lines from a file one by one, handling opening/closing safely.

class LazyFileReader:
    """Iterate over a file line‑by‑line without loading the whole file.

    The class implements the context‑manager protocol so you can use
    ``with LazyFileReader(path) as reader:``.
    """

    def __init__(self, path, encoding="utf-8"):
        self.path = path
        self.encoding = encoding
        self.file = None

    def __enter__(self):
        self.file = open(self.path, "r", encoding=self.encoding)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.file:
            self.file.close()
        # Propagate any exception
        return False

    def __iter__(self):
        if self.file is None:
            # Allow use without a with‑statement; open lazily.
            self.file = open(self.path, "r", encoding=self.encoding)
        return self

    def __next__(self):
        if self.file is None:
            raise RuntimeError("File not opened")
        line = self.file.readline()
        if line == "":
            raise StopIteration
        return line.rstrip("\n")

if __name__ == "__main__":
    # Example: print each line of this file itself.
    import os
    this_file = os.path.abspath(__file__)
    with LazyFileReader(this_file) as rdr:
        for ln in rdr:
            print(ln)

