# An iterator that produces an unbounded sequence of prime numbers.

class PrimeIterator:
    """Infinite iterator yielding prime numbers one after another.

    The algorithm checks each candidate by trial division up to its square root.
    """

    def __init__(self):
        self.current = 2
        self.primes = []  # cache of found primes for faster testing

    def __iter__(self):
        return self

    def __next__(self):
        while True:
            n = self.current
            is_prime = True
            limit = int(n ** 0.5) + 1
            for p in self.primes:
                if p > limit:
                    break
                if n % p == 0:
                    is_prime = False
                    break
            if is_prime:
                self.primes.append(n)
                self.current = n + 1
                return n
            self.current += 1

if __name__ == "__main__":
    import itertools
    print("First 15 primes:")
    for p in itertools.islice(PrimeIterator(), 15):
        print(p, end=" ")
    print()

