import functools
from typing import Callable, List, Any

def repeat(times: int = 2) -> Callable[[Callable[..., Any]], Callable[..., List[Any]]]:
    """Return a decorator that repeats the call *times* times.
    The wrapper returns a list containing the result of each invocation.
    """
    if times < 1:
        raise ValueError("times must be a positive integer")

    def decorator(func: Callable[..., Any]) -> Callable[..., List[Any]]:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> List[Any]:
            results = []
            for i in range(times):
                result = func(*args, **kwargs)
                results.append(result)
            return results
        return wrapper
    return decorator

