import functools
import logging

logging.basicConfig(level=logging.INFO, format='[%(levelname)s] %(message)s')

def log_calls(func: callable) -> callable:
    """Print a log message before and after *func* execution."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        logging.info(f"Calling {func.__name__} with args={args}, kwargs={kwargs}")
        result = func(*args, **kwargs)
        logging.info(f"{func.__name__} returned {result}")
        return result
    return wrapper

def non_negative(func: callable) -> callable:
    """Ensure all positional arguments are non‑negative integers.
    Raises ValueError if a violation is found.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        for i, value in enumerate(args):
            if not isinstance(value, int) or value < 0:
                raise ValueError(f"Argument {i} ({value}) must be a non‑negative integer")
        return func(*args, **kwargs)
    return wrapper

# Stacked usage ------------------------------------------------------------
@log_calls
@non_negative
def factorial(n: int) -> int:
    """Iterative factorial that works for non‑negative integers."""
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

