'''rate_limit.py
Implements a @rate_limit(calls=5, period=10) decorator that allows a function
to be invoked at most *calls* times within *period* seconds. If the limit is
exceeded, a RuntimeError is raised.
''' 
import functools
import time
from collections import deque

def rate_limit(calls: int, period: float):
    """Factory returning a decorator that limits calls per *period* seconds.
    ``calls`` – max number of allowed invocations within the sliding window.
    ``period`` – window length in seconds.
    """
    if calls < 1:
        raise ValueError("calls must be >= 1")
    if period <= 0:
        raise ValueError("period must be positive")

    def decorator(func: callable) -> callable:
        timestamps = deque()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            now = time.monotonic()
            # Discard timestamps older than the window
            while timestamps and now - timestamps[0] > period:
                timestamps.popleft()
            if len(timestamps) >= calls:
                raise RuntimeError(f"Rate limit exceeded: {calls} calls per {period}s")
            timestamps.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Demonstration ------------------------------------------------------------
@rate_limit(calls=3, period=5)
def ping(msg: str) -> str:
    """Return the message with a timestamp – used to show rate limiting."""
    return f"{time.time():.2f}: {msg}"

if __name__ == "__main__":
    for i in range(5):
        try:
            print(ping(f"attempt {i+1}"))
        except RuntimeError as e:
            print('Error:', e)
        time.sleep(1)

