'''trie_prefix_list.py
Builds a Trie from an input list and provides a function to collect all words
that start with a user‑supplied prefix. The file can be executed directly to
see a short demo.
''' 

from typing import List

class Node:
    __slots__ = ('children', 'is_word')
    def __init__(self):
        self.children = {}
        self.is_word = False

class Trie:
    def __init__(self, words: List[str] | None = None):
        self.root = Node()
        if words:
            for w in words:
                self.insert(w)

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = Node()
            node = node.children[ch]
        node.is_word = True

    def _collect(self, node: Node, prefix: str, out: List[str]) -> None:
        if node.is_word:
            out.append(prefix)
        for ch, child in node.children.items():
            self._collect(child, prefix + ch, out)

    def words_with_prefix(self, prefix: str) -> List[str]:
        """Return a list of all stored words that begin with *prefix*.
        If the prefix is not present, an empty list is returned.
        """
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return []
        result: List[str] = []
        self._collect(node, prefix, result)
        return result

# Demo when run directly
if __name__ == '__main__':
    sample = ['car', 'card', 'cart', 'cat', 'cater', 'dog', 'dot']
    trie = Trie(sample)
    for pref in ['ca', 'car', 'do', 'z']:
        print(f"Prefix '{pref}':", trie.words_with_prefix(pref))

'''autocomplete_trie.py
Load a word list from a text file (one word per line) into a trie and expose
an `autocomplete(prefix, limit=10)` function that returns up to *limit*
suggestions sorted alphabetically.
''' 

from pathlib import Path
from typing import List

class TrieNode:
    __slots__ = ('children', 'is_word')
    def __init__(self):
        self.children = {}
        self.is_word = False

class AutocompleteTrie:
    def __init__(self):
        self.root = TrieNode()

    def load(self, path: str | Path) -> None:
        """Read a file and insert each stripped line as a word.
        Empty lines are ignored.
        """
        with Path(path).open(encoding='utf-8') as f:
            for line in f:
                word = line.strip()
                if word:
                    self.insert(word)

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_word = True

    def _gather(self, node: TrieNode, prefix: str, out: List[str], limit: int) -> None:
        if len(out) >= limit:
            return
        if node.is_word:
            out.append(prefix)
        for ch in sorted(node.children):
            self._gather(node.children[ch], prefix + ch, out, limit)

    def autocomplete(self, prefix: str, limit: int = 10) -> List[str]:
        """Return up to *limit* words that start with *prefix*.
        The suggestions are alphabetical because child keys are traversed in
        sorted order.
        """
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return []
        results: List[str] = []
        self._gather(node, prefix, results, limit)
        return results

# Example usage when script is executed directly
if __name__ == '__main__':
    trie = AutocompleteTrie()
    # Assuming a small local word list named 'words.txt' exists.
    try:
        trie.load('words.txt')
    except FileNotFoundError:
        print('words.txt not found – using a tiny built‑in list for demo')
        for w in ['apple', 'application', 'apply', 'apt', 'banana', 'band', 'bandit']:
            trie.insert(w)
    print('Suggestions for "ap":', trie.autocomplete('ap'))
    print('Suggestions for "ban":', trie.autocomplete('ban', limit=5))

'''trie_with_delete.py
A Trie data structure that supports insertion, exact search, prefix check
and deletion of words. Deletion removes unnecessary nodes to keep the trie
compact.
''' 

from __future__ import annotations
from typing import Dict

class TrieNode:
    __slots__ = ('children', 'is_end')
    def __init__(self) -> None:
        self.children: Dict[str, TrieNode] = {}
        self.is_end: bool = False

class Trie:
    def __init__(self) -> None:
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self._follow(word)
        return bool(node) and node.is_end

    def starts_with(self, prefix: str) -> bool:
        return self._follow(prefix) is not None

    def delete(self, word: str) -> bool:
        """Delete *word* from the trie.
        Returns True if the word was present and removed, False otherwise.
        """
        def _delete(node: TrieNode, idx: int) -> bool:
            if idx == len(word):
                if not node.is_end:
                    return False  # word not present
                node.is_end = False
                return len(node.children) == 0  # prune if leaf
            ch = word[idx]
            child = node.children.get(ch)
            if child is None:
                return False
            should_prune = _delete(child, idx + 1)
            if should_prune:
                del node.children[ch]
                return not node.is_end and len(node.children) == 0
            return False
        return _delete(self.root, 0)

    def _follow(self, seq: str) -> TrieNode | None:
        node = self.root
        for ch in seq:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

# Simple test when executed directly
if __name__ == '__main__':
    t = Trie()
    for w in ['test', 'testing', 'team', 'toast']:
        t.insert(w)
    print('search test ->', t.search('test'))
    print('delete test ->', t.delete('test'))
    print('search test after delete ->', t.search('test'))
    print('search testing ->', t.search('testing'))
    print('delete toast ->', t.delete('toast'))
    print('starts_with te ->', t.starts_with('te'))

'''trie_visualizer.py
Utility that constructs a trie from a list of strings and provides a function
`to_dict()` that returns a nested dictionary representation where leaf nodes
contain the marker '*'. This aids debugging by printing the entire structure.
''' 

from typing import Dict, List, Any

class Node:
    __slots__ = ('children', 'is_word')
    def __init__(self):
        self.children: Dict[str, Node] = {}
        self.is_word: bool = False

class Trie:
    def __init__(self, words: List[str] | None = None):
        self.root = Node()
        if words:
            for w in words:
                self.insert(w)

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, Node())
        node.is_word = True

    def to_dict(self) -> Dict[str, Any]:
        """Convert the trie into a nested dict.
        Each character maps to its subtree; a special key '_' with value '*'
        marks the end of a word.
        """
        def helper(node: Node) -> Dict[str, Any]:
            d: Dict[str, Any] = {}
            if node.is_word:
                d['_'] = '*'
            for ch, child in node.children.items():
                d[ch] = helper(child)
            return d
        return helper(self.root)

if __name__ == '__main__':
    sample = ['cat', 'car', 'cart', 'dog']
    trie = Trie(sample)
    import json
    print(json.dumps(trie.to_dict(), indent=2))

'''radix_trie.py
A simple radix (compact prefix) tree implementation.
Each edge stores a string segment; this reduces the number of nodes
compared to a classic character‑by‑character trie.
The tree supports insert, exact search and prefix lookup returning all
matching keys.
''' 

from typing import Dict, List, Tuple

class RadixNode:
    __slots__ = ('label', 'children', 'is_word')
    def __init__(self, label: str = ''):
        self.label: str = label                # edge label from parent
        self.children: Dict[str, RadixNode] = {}
        self.is_word: bool = False

class RadixTrie:
    def __init__(self) -> None:
        self.root = RadixNode()

    def insert(self, word: str) -> None:
        node = self.root
        idx = 0
        while idx < len(word):
            # find child whose label shares a prefix with the remaining word
            first_char = word[idx]
            child = None
            for c, n in node.children.items():
                if c[0] == first_char:
                    child = n
                    break
            if child is None:
                # no matching edge – create a new leaf
                node.children[word[idx:]] = RadixNode(word[idx:])
                node.children[word[idx:]].is_word = True
                return
            label = child.label
            # compute longest common prefix between label and remaining word
            i = 0
            while i < len(label) and idx + i < len(word) and label[i] == word[idx + i]:
                i += 1
            if i == len(label):
                # whole edge matches, move deeper
                node = child
                idx += i
                continue
            # split the edge at the divergence point
            remaining_label = label[i:]
            new_child = RadixNode(remaining_label)
            new_child.children = child.children
            new_child.is_word = child.is_word
            # adjust current child
            child.label = label[:i]
            child.children = {remaining_label: new_child}
            child.is_word = child.is_word and i == len(word) - idx
            if i < len(word) - idx:
                # insert the rest of the word as a new leaf
                suffix = word[idx + i:]
                child.children[suffix] = RadixNode(suffix)
                child.children[suffix].is_word = True
            else:
                child.is_word = True
            return

    def _search_node(self, key: str) -> Tuple[RadixNode | None, int]:
        node = self.root
        idx = 0
        while idx < len(key):
            matched = False
            for child in node.children.values():
                label = child.label
                if key.startswith(label, idx):
                    idx += len(label)
                    node = child
                    matched = True
                    break
                if label.startswith(key[idx]):
                    # partial match – key diverges
                    return None, idx
            if not matched:
                return None, idx
        return node, idx

    def search(self, word: str) -> bool:
        node, pos = self._search_node(word)
        return bool(node) and node.is_word and pos == len(word)

    def _collect(self, node: RadixNode, prefix: str, out: List[str]) -> None:
        if node.is_word:
            out.append(prefix)
        for child in node.children.values():
            self._collect(child, prefix + child.label, out)

    def keys_with_prefix(self, prefix: str) -> List[str]:
        node, pos = self._search_node(prefix)
        if node is None:
            return []
        results: List[str] = []
        self._collect(node, prefix[:pos], results)
        return results

if __name__ == '__main__':
    rt = RadixTrie()
    for w in ['bear', 'bell', 'bid', 'bull', 'buy', 'sell', 'stock', 'stop']:
        rt.insert(w)
    print('search "bell" ->', rt.search('bell'))
    print('keys with prefix "bu" ->', rt.keys_with_prefix('bu'))

#!/usr/bin/env bash
# service_dispatcher.sh – Simple dispatcher for start/stop/status subcommands.
# Demonstrates portable function definitions and argument parsing.

# Global variable to simulate service state (saved in a temporary file).
STATE_FILE="${XDG_RUNTIME_DIR:-/tmp}/service_dispatcher.state"

init_state() {
    if [[ ! -f $STATE_FILE ]]; then
        echo "stopped" > "$STATE_FILE"
    fi
}

set_state() {
    printf "%s\n" "$1" > "$STATE_FILE"
}

get_state() {
    cat "$STATE_FILE"
}

start() {
    if [[ $(get_state) == "running" ]]; then
        echo "Service is already running."
    else
        set_state "running"
        echo "Service started."
    fi
}

stop() {
    if [[ $(get_state) == "stopped" ]]; then
        echo "Service is already stopped."
    else
        set_state "stopped"
        echo "Service stopped."
    fi
}

status() {
    echo "Service status: $(get_state)"
}

usage() {
    echo "Usage: $0 {start|stop|status}"
    exit 2
}

main() {
    init_state
    case $1 in
        start)   start   ;;
        stop)    stop    ;;
        status)  status  ;;
        *)       usage   ;;
    esac
}

main "$@"

