'''env_settings.py
A tiny, class‑based configuration holder that pulls values from the
environment on instantiation. Missing variables are replaced by the
provided defaults and type conversion is performed automatically.
''' 
import os
from dataclasses import dataclass, field
from typing import Any, Callable

def _convert(value: str, target: Callable[[str], Any]) -> Any:
    """Convert *value* using *target* callable, falling back to the original string on error."""
    try:
        return target(value)
    except Exception:
        return value

@dataclass(frozen=True)
class EnvSettings:
    """Configuration loaded from environment variables.
    Field names become the variable suffix; the optional ``env`` argument
    lets you specify a custom variable name.
    """
    host: str = field(default="localhost", metadata={"env": "HOST"})
    port: int = field(default=8000, metadata={"env": "PORT"})
    debug: bool = field(default=False, metadata={"env": "DEBUG"})
    timeout: float = field(default=5.0, metadata={"env": "TIMEOUT"})

    @classmethod
    def from_env(cls) -> "EnvSettings":
        """Create an instance using the current process environment.
        Types are inferred from the default values of the dataclass fields.
        """
        init_kwargs: dict[str, Any] = {}
        for f in cls.__dataclass_fields__.values():
            env_name = f.metadata.get("env", f.name.upper())
            raw = os.getenv(env_name)
            if raw is None:
                init_kwargs[f.name] = f.default
                continue
            # Choose a converter based on the type of the default
            if isinstance(f.default, bool):
                conv = lambda v: v.lower() in ("1", "true", "yes")
            elif isinstance(f.default, int):
                conv = int
            elif isinstance(f.default, float):
                conv = float
            else:
                conv = str
            init_kwargs[f.name] = _convert(raw, conv)
        return cls(**init_kwargs)

# Example usage when run directly
if __name__ == "__main__":
    settings = EnvSettings.from_env()
    print(settings)

# dot_product.py
# Provides a NumPy‑based dot‑product function and a tiny CLI for quick testing.

import sys
import numpy as np

def dot(v1: np.ndarray, v2: np.ndarray) -> float:
    """Return the scalar dot product of two 1‑D NumPy arrays.

    Raises:
        ValueError: if the inputs are not 1‑D or have different lengths.
    """
    if v1.ndim != 1 or v2.ndim != 1:
        raise ValueError('Both inputs must be 1‑D vectors')
    if v1.shape[0] != v2.shape[0]:
        raise ValueError('Vectors must be of the same length')
    return float(np.dot(v1, v2))

def parse_args(args: list[str]) -> tuple[np.ndarray, np.ndarray]:
    """Parse two comma‑separated lists from the command line into float arrays.
    Example usage: python dot_product.py "1,2,3" "4,5,6"
    """
    if len(args) != 2:
        raise SystemExit('Provide exactly two comma‑separated vectors')
    v1 = np.fromstring(args[0], sep=',', dtype=float)
    v2 = np.fromstring(args[1], sep=',', dtype=float)
    return v1, v2

def main() -> None:
    try:
        vec1, vec2 = parse_args(sys.argv[1:])
        result = dot(vec1, vec2)
        print(f'Dot product of {vec1} and {vec2} = {result}')
    except Exception as e:
        print('Error:', e)
        sys.exit(1)

if __name__ == '__main__':
    main()

'''env_loader.py
A lightweight helper to load key/value pairs from a .env file, overlay them onto os.environ,
and retrieve typed configuration values via get_config.
''' 

import os
from pathlib import Path
from typing import Any, Callable, Optional

# Simple parser: ignore comments and blank lines, split on the first '='
def _parse_dotenv(dotenv_path: Path) -> dict:
    env: dict = {}
    if not dotenv_path.is_file():
        return env
    for line in dotenv_path.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            continue
        key, value = line.split('=', 1)
        env[key.strip()] = value.strip().strip('"').strip("'")
    return env

def load_dotenv(dotenv_path: str = ".env", override: bool = False) -> None:
    """Load variables from *dotenv_path* into os.environ.

    If *override* is False (default) existing environment variables are left untouched.
    """
    path = Path(dotenv_path)
    new_vars = _parse_dotenv(path)
    for k, v in new_vars.items():
        if override or k not in os.environ:
            os.environ[k] = v

def get_config(
    key: str,
    default: Any = None,
    cast: Optional[Callable[[str], Any]] = None,
) -> Any:
    """Retrieve *key* from os.environ, optionally casting it.

    *default* is returned when the variable is missing.
    *cast* can be a function like int, float, or a custom parser.
    """
    raw = os.getenv(key, None)
    if raw is None:
        return default
    if cast is None:
        return raw
    try:
        return cast(raw)
    except Exception as exc:
        raise ValueError(f"Unable to cast environment variable {key!r}: {exc}")

# Example usage when run as a script
if __name__ == "__main__":
    load_dotenv()
    print("Loaded configuration:")
    for k in sorted(os.environ):
        if k.startswith('MYAPP_'):
            print(f"{k} = {os.environ[k]}")

"""validate_config.py
Checks that a predefined set of environment variables is present and meets simple validation rules.
If a requirement is not satisfied the script prints a clear error and exits with status 1.
"""

import os
import sys
from typing import Callable, Dict, List, Tuple

# Each entry: variable name -> (validation callable, error message)
REQUIRED_VARS: Dict[str, Tuple[Callable[[str], bool], str]] = {
    "DB_HOST": (lambda v: len(v) > 0, "must not be empty"),
    "DB_PORT": (lambda v: v.isdigit() and 0 < int(v) < 65536, "must be a valid TCP port"),
    "DB_USER": (lambda v: len(v) > 0, "must not be empty"),
    "DB_PASSWORD": (lambda v: len(v) >= 8, "must be at least 8 characters"),
    "SECRET_KEY": (lambda v: len(v) >= 32, "must be at least 32 characters for security"),
}


def _report_error(messages: List[str]) -> None:
    sys.stderr.write("Configuration validation failed:\n")
    for msg in messages:
        sys.stderr.write(f"  - {msg}\n")
    sys.stderr.write("Application will now exit.\n")
    sys.exit(1)


def validate() -> None:
    errors: List[str] = []
    for var, (check, err_msg) in REQUIRED_VARS.items():
        val = os.getenv(var)
        if val is None:
            errors.append(f"{var} is missing")
        elif not check(val):
            errors.append(f"{var} is invalid: {err_msg}")
    if errors:
        _report_error(errors)
    else:
        print("All required configuration variables are present and valid.")


if __name__ == "__main__":
    validate()

"""config_model.py
Defines a Config dataclass that pulls values from environment variables,
applies defaults, performs simple type conversion, and can serialize itself to JSON.
"""

import json
import os
from dataclasses import dataclass, asdict, field
from typing import Any, Callable, Dict

# Mapping of attribute name -> (env var name, converter, default)
_SCHEMA: Dict[str, tuple] = {
    "host": ("SERVICE_HOST", str, "127.0.0.1"),
    "port": ("SERVICE_PORT", int, 5000),
    "debug": ("SERVICE_DEBUG", lambda v: v.lower() in ("1", "true", "yes"), False),
    "timeout": ("SERVICE_TIMEOUT", float, 15.0),
}


def _resolve(env_name: str, converter: Callable[[str], Any], default: Any) -> Any:
    raw = os.getenv(env_name)
    if raw is None:
        return default
    try:
        return converter(raw)
    except Exception as exc:
        raise ValueError(f"Error converting {env_name!r}: {exc}")


@dataclass
class Config:
    host: str = field(init=False)
    port: int = field(init=False)
    debug: bool = field(init=False)
    timeout: float = field(init=False)

    def __post_init__(self) -> None:
        for attr, (env_name, conv, default) in _SCHEMA.items():
            setattr(self, attr, _resolve(env_name, conv, default))

    def to_json(self, *, indent: int = 2) -> str:
        """Return a JSON string representing the configuration.
        The dataclass fields are converted to a dictionary via asdict.
        """
        return json.dumps(asdict(self), indent=indent)

    @classmethod
    def from_json(cls, json_str: str) -> "Config":
        """Create a Config instance from a JSON representation.
        Values from the JSON are injected directly, bypassing os.environ.
        """
        data = json.loads(json_str)
        obj = cls.__new__(cls)  # bypass __init__
        for field_name in _SCHEMA:
            setattr(obj, field_name, data.get(field_name, _SCHEMA[field_name][2]))
        return obj


if __name__ == "__main__":
    cfg = Config()
    print("Current configuration:\n", cfg.to_json())

"""feature_flags.py
Utility that interprets environment variables as feature toggles.
Each flag follows the naming pattern FEATURE_<NAME> and is considered enabled
if its value evaluates to true (1, true, yes, on).
"""

import os
from typing import Dict, List

PREFIX = "FEATURE_"
TRUE_VALUES = {"1", "true", "yes", "on"}

def _is_enabled(value: str) -> bool:
    return value.strip().lower() in TRUE_VALUES


def discover_flags() -> Dict[str, bool]:
    """Scan os.environ for keys starting with PREFIX and return a mapping.
    The key in the returned dict is the feature name without the prefix.
    """
    flags: Dict[str, bool] = {}
    for key, val in os.environ.items():
        if key.startswith(PREFIX):
            feature = key[len(PREFIX):].lower()
            flags[feature] = _is_enabled(val)
    return flags


def enabled_features(flags: Dict[str, bool]) -> List[str]:
    return [name for name, enabled in flags.items() if enabled]


def main() -> None:
    flags = discover_flags()
    enabled = enabled_features(flags)
    if enabled:
        print("Enabled features:")
        for f in sorted(enabled):
            print(f" - {f}")
    else:
        print("No feature flags are enabled.")


if __name__ == "__main__":
    main()

"""json_config.py
Loads configuration from a JSON file whose path is supplied via the
ENV variable CONFIG_JSON_PATH. The JSON keys are merged onto os.environ,
overwriting any existing variables with the same name.
It also provides a get function that prefers the merged value.
"""

import json
import os
from pathlib import Path
from typing import Any, Dict

ENV_VAR = "CONFIG_JSON_PATH"

def _load_json(path: str) -> Dict[str, Any]:
    p = Path(path)
    if not p.is_file():
        raise FileNotFoundError(f"Configuration file not found: {path}")
    try:
        return json.loads(p.read_text())
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON in {path}: {exc}")

def merge_json_into_environ() -> None:
    """Load the JSON config and overlay its keys onto os.environ.

    Existing environment variables are replaced by the JSON counterpart.
    """
    json_path = os.getenv(ENV_VAR)
    if not json_path:
        raise RuntimeError(f"Environment variable {ENV_VAR} is not set")
    data = _load_json(json_path)
    for k, v in data.items():
        # Ensure values are strings because os.environ stores only strings
        os.environ[k] = str(v)


def get(key: str, default: Any = None) -> Any:
    """Retrieve *key* after the merge, returning *default* if missing.
    The value is always returned as a string because that's how os.environ stores it.
    """
    return os.getenv(key, default)


if __name__ == "__main__":
    try:
        merge_json_into_environ()
        print("Merged configuration values:")
        for k, v in sorted(os.environ.items()):
            print(f"{k}={v}")
    except Exception as e:
        print(f"Error: {e}")

# bubble_vs_builtin.py
# Benchmark bubble sort vs. list.sort() / sorted() on random integer data.
# The script reports timings and includes a short rationale for avoiding bubble sort.

import random, time
from typing import List

def bubble_sort(arr: List[int]) -> List[int]:
    """Return a sorted copy of *arr* using bubble sort (O(n²))."""
    result = arr[:]
    n = len(result)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if result[j] > result[j + 1]:
                result[j], result[j + 1] = result[j + 1], result[j]
                swapped = True
        if not swapped:
            break
    return result

def time_function(func, data):
    start = time.perf_counter()
    func(data)
    return time.perf_counter() - start

def main() -> None:
    sizes = [100, 500, 1000]
    for n in sizes:
        data = [random.randint(0, 10000) for _ in range(n)]
        t_bubble = time_function(bubble_sort, data)
        t_builtin = time_function(sorted, data)
        print(f"Size {n:4d}: bubble sort = {t_bubble:8.4f}s, built‑in sorted = {t_builtin:8.4f}s")
    print("\nConclusion: bubble sort grows quadratically and quickly becomes orders of magnitude slower than the highly optimized Timsort used by Python's built‑in sorting functions.  For any performance‑critical code, prefer `list.sort()` or `sorted()`.")

if __name__ == "__main__":
    main()

'''stack_demo.py
Simple Stack implementation using Python's built‑in list.
Provides push, pop, peek and an is_empty utility.
''' 

class Stack:
    """A last‑in‑first‑out (LIFO) stack.

    The underlying container is a Python list; appends and pops from the end
    are O(1). The class validates operations and raises IndexError on underflow.
    """
    def __init__(self):
        self._items = []

    def push(self, item):
        """Add *item* to the top of the stack."""
        self._items.append(item)

    def pop(self):
        """Remove and return the top item.

        Raises:
            IndexError: if the stack is empty.
        """
        if self.is_empty():
            raise IndexError('pop from empty stack')
        return self._items.pop()

    def peek(self):
        """Return the top item without removing it.

        Raises:
            IndexError: if the stack is empty.
        """
        if self.is_empty():
            raise IndexError('peek from empty stack')
        return self._items[-1]

    def is_empty(self):
        """Return True if the stack contains no items."""
        return len(self._items) == 0

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return f"Stack({self._items})"

# Demo when run as a script
if __name__ == '__main__':
    s = Stack()
    for i in range(5):
        s.push(i * 10)
        print(f"Pushed {i * 10}, stack now: {s}")
    print(f"Top element is {s.peek()}")
    while not s.is_empty():
        print(f"Popped {s.pop()}, stack now: {s}")

'''queue_impl.py
Queue implementation based on collections.deque.
Provides enqueue, dequeue, front and size operations.
''' 

from collections import deque

class Queue:
    """A first‑in‑first‑out (FIFO) queue.

    Using `deque` gives O(1) amortized time for both enqueue and dequeue.
    """
    def __init__(self):
        self._data = deque()

    def enqueue(self, item):
        """Add *item* to the rear of the queue."""
        self._data.append(item)

    def dequeue(self):
        """Remove and return the front item.

        Raises:
            IndexError: if the queue is empty.
        """
        if self.is_empty():
            raise IndexError('dequeue from empty queue')
        return self._data.popleft()

    def front(self):
        """Return the front item without removing it.

        Raises:
            IndexError: if the queue is empty.
        """
        if self.is_empty():
            raise IndexError('front from empty queue')
        return self._data[0]

    def is_empty(self):
        return len(self._data) == 0

    def size(self):
        return len(self._data)

    def __repr__(self):
        return f"Queue({list(self._data)})"

if __name__ == '__main__':
    q = Queue()
    for ch in 'abcde':
        q.enqueue(ch)
        print(f"Enqueued '{ch}', queue: {q}")
    print(f"Front element is '{q.front()}'")
    while not q.is_empty():
        print(f"Dequeued '{q.dequeue()}', queue: {q}")

