'''bounded_structs.py
Bounded Stack and Queue with a maximum size.
Both raise `OverflowError` when a push/enqueue would exceed capacity.
''' 

from collections import deque

class BoundedStack:
    """Stack with a fixed maximum capacity.

    Args:
        capacity (int): Maximum number of elements the stack can hold.
    """
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError('capacity must be positive')
        self._capacity = capacity
        self._items = []

    def push(self, item):
        if len(self._items) >= self._capacity:
            raise OverflowError('stack capacity exceeded')
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise IndexError('pop from empty stack')
        return self._items.pop()

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return f"BoundedStack(cap={self._capacity}, items={self._items})"

class BoundedQueue:
    """Queue with a fixed maximum capacity using `deque`.

    Args:
        capacity (int): Maximum number of elements allowed.
    """
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError('capacity must be positive')
        self._capacity = capacity
        self._data = deque()

    def enqueue(self, item):
        if len(self._data) >= self._capacity:
            raise OverflowError('queue capacity exceeded')
        self._data.append(item)

    def dequeue(self):
        if not self._data:
            raise IndexError('dequeue from empty queue')
        return self._data.popleft()

    def __len__(self):
        return len(self._data)

    def __repr__(self):
        return f"BoundedQueue(cap={self._capacity}, items={list(self._data)})"

if __name__ == '__main__':
    sb = BoundedStack(3)
    for v in (1, 2, 3):
        sb.push(v)
        print(sb)
    try:
        sb.push(4)
    except OverflowError as e:
        print('Error:', e)
    qb = BoundedQueue(2)
    qb.enqueue('a')
    qb.enqueue('b')
    print(qb)
    try:
        qb.enqueue('c')
    except OverflowError as e:
        print('Error:', e)

"""bst_basic.py
A minimal binary search tree implementation.
Provides Node class, BST class with insert, find, and inorder traversal.
"""

class Node:
    """A node in the binary search tree."""
    __slots__ = ('key', 'value', 'left', 'right')
    def __init__(self, key, value=None):
        self.key = key
        self.value = value if value is not None else key
        self.left = None
        self.right = None

class BST:
    """Binary Search Tree with insert, find and inorder methods."""
    def __init__(self):
        self.root = None

    def insert(self, key, value=None):
        """Insert a key (and optional value) into the tree.
        Duplicates are ignored.
        """
        def _insert(node, key, value):
            if node is None:
                return Node(key, value)
            if key < node.key:
                node.left = _insert(node.left, key, value)
            elif key > node.key:
                node.right = _insert(node.right, key, value)
            # if equal, do nothing (no duplicates)
            return node
        self.root = _insert(self.root, key, value)

    def find(self, key):
        """Return the value associated with *key* or None if not found."""
        node = self.root
        while node:
            if key == node.key:
                return node.value
            node = node.left if key < node.key else node.right
        return None

    def inorder(self):
        """Yield keys in sorted order using an explicit stack (no recursion)."""
        stack = []
        node = self.root
        while stack or node:
            while node:
                stack.append(node)
                node = node.left
            node = stack.pop()
            yield node.key
            node = node.right

if __name__ == "__main__":
    # Simple demo
    tree = BST()
    for k in [7, 3, 9, 1, 5, 8, 10]:
        tree.insert(k)
    print("Inorder traversal:", list(tree.inorder()))
    print("Find 5 ->", tree.find(5))
    print("Find 2 ->", tree.find(2))

'''bst_visualizer.py
Generate a Graphviz dot file and render a BST.
Requires the 'graphviz' package (pip install graphviz).
'''

from __future__ import annotations
from dataclasses import dataclass
from typing import Optional
import graphviz

@dataclass
class Node:
    key: int
    left: Optional['Node'] = None
    right: Optional['Node'] = None

class BST:
    def __init__(self):
        self.root: Optional[Node] = None

    def insert(self, key: int) -> None:
        def _insert(node: Optional[Node], key: int) -> Node:
            if node is None:
                return Node(key)
            if key < node.key:
                node.left = _insert(node.left, key)
            elif key > node.key:
                node.right = _insert(node.right, key)
            return node
        self.root = _insert(self.root, key)

    def _add_edges(self, dot: graphviz.Digraph, node: Node) -> None:
        if node.left:
            dot.edge(str(node.key), str(node.left.key))
            self._add_edges(dot, node.left)
        if node.right:
            dot.edge(str(node.key), str(node.right.key))
            self._add_edges(dot, node.right)

    def render(self, filename: str = 'bst') -> None:
        if self.root is None:
            raise ValueError('Tree is empty')
        dot = graphviz.Digraph(comment='Binary Search Tree')
        dot.node(str(self.root.key), str(self.root.key))
        self._add_edges(dot, self.root)
        dot.render(filename, format='png', cleanup=True)
        print(f'Rendered BST to {filename}.png')

if __name__ == '__main__':
    keys = [50, 30, 70, 20, 40, 60, 80]
    tree = BST()
    for k in keys:
        tree.insert(k)
    tree.render('my_bst')

"""avl_tree.py
An AVL (self‑balancing) binary search tree implementation.
Supports insert, delete, search and in‑order traversal.
"""

from __future__ import annotations
from typing import Optional, Any, Generator

class AVLNode:
    __slots__ = ('key', 'value', 'height', 'left', 'right')
    def __init__(self, key: Any, value: Any = None):
        self.key = key
        self.value = value if value is not None else key
        self.height = 1
        self.left: Optional[AVLNode] = None
        self.right: Optional[AVLNode] = None

def _height(node: Optional[AVLNode]) -> int:
    return node.height if node else 0

def _update_height(node: AVLNode) -> None:
    node.height = 1 + max(_height(node.left), _height(node.right))

def _balance_factor(node: AVLNode) -> int:
    return _height(node.left) - _height(node.right)

def _rotate_right(y: AVLNode) -> AVLNode:
    x = y.left
    T2 = x.right
    x.right = y
    y.left = T2
    _update_height(y)
    _update_height(x)
    return x

def _rotate_left(x: AVLNode) -> AVLNode:
    y = x.right
    T2 = y.left
    y.left = x
    x.right = T2
    _update_height(x)
    _update_height(y)
    return y

def _rebalance(node: AVLNode) -> AVLNode:
    _update_height(node)
    bf = _balance_factor(node)
    if bf > 1:
        if _balance_factor(node.left) < 0:
            node.left = _rotate_left(node.left)
        return _rotate_right(node)
    if bf < -1:
        if _balance_factor(node.right) > 0:
            node.right = _rotate_right(node.right)
        return _rotate_left(node)
    return node

class AVLTree:
    def __init__(self):
        self.root: Optional[AVLNode] = None

    def insert(self, key: Any, value: Any = None) -> None:
        def _insert(node: Optional[AVLNode], key: Any, value: Any) -> AVLNode:
            if not node:
                return AVLNode(key, value)
            if key < node.key:
                node.left = _insert(node.left, key, value)
            elif key > node.key:
                node.right = _insert(node.right, key, value)
            else:
                node.value = value if value is not None else node.value
                return node
            return _rebalance(node)
        self.root = _insert(self.root, key, value)

    def _min_node(self, node: AVLNode) -> AVLNode:
        while node.left:
            node = node.left
        return node

    def delete(self, key: Any) -> None:
        def _delete(node: Optional[AVLNode], key: Any) -> Optional[AVLNode]:
            if not node:
                return None
            if key < node.key:
                node.left = _delete(node.left, key)
            elif key > node.key:
                node.right = _delete(node.right, key)
            else:
                if not node.left:
                    return node.right
                if not node.right:
                    return node.left
                temp = self._min_node(node.right)
                node.key, node.value = temp.key, temp.value
                node.right = _delete(node.right, temp.key)
            return _rebalance(node) if node else None
        self.root = _delete(self.root, key)

    def find(self, key: Any) -> Optional[Any]:
        node = self.root
        while node:
            if key == node.key:
                return node.value
            node = node.left if key < node.key else node.right
        return None

    def inorder(self) -> Generator[Any, None, None]:
        stack = []
        node = self.root
        while stack or node:
            while node:
                stack.append(node)
                node = node.left
            node = stack.pop()
            yield node.key
            node = node.right

if __name__ == '__main__':
    avl = AVLTree()
    for k in [10, 20, 30, 40, 50, 25]:
        avl.insert(k)
    print('Inorder after inserts:', list(avl.inorder()))
    avl.delete(20)
    print('Inorder after deleting 20:', list(avl.inorder()))

"""bst_iterator.py
Utility module offering a BST iterator that can walk the tree in three orders.
The iterator works on any tree built from the Node class defined here.
"""

from __future__ import annotations
from typing import Optional, Generator, List

class Node:
    __slots__ = ('key', 'left', 'right')
    def __init__(self, key: int, left: Optional['Node'] = None, right: Optional['Node'] = None):
        self.key = key
        self.left = left
        self.right = right

class BSTIterator:
    """Iterates over a BST in preorder, inorder, or postorder.
    mode must be one of 'pre', 'in', 'post'.
    """
    def __init__(self, root: Optional[Node], mode: str = 'in'):
        if mode not in {'pre', 'in', 'post'}:
            raise ValueError("mode must be 'pre', 'in' or 'post'")
        self.root = root
        self.mode = mode

    def __iter__(self):
        if self.mode == 'pre':
            return self._preorder(self.root)
        if self.mode == 'in':
            return self._inorder(self.root)
        return self._postorder(self.root)

    def _preorder(self, node: Optional[Node]) -> Generator[int, None, None]:
        if node:
            yield node.key
            yield from self._preorder(node.left)
            yield from self._preorder(node.right)

    def _inorder(self, node: Optional[Node]) -> Generator[int, None, None]:
        if node:
            yield from self._inorder(node.left)
            yield node.key
            yield from self._inorder(node.right)

    def _postorder(self, node: Optional[Node]) -> Generator[int, None, None]:
        if node:
            yield from self._postorder(node.left)
            yield from self._postorder(node.right)
            yield node.key

# Helper to build a simple BST for demonstration
def build_sample() -> Node:
    #   4
    #  / \
    # 2   6
    #/ \ / \
    #1 3 5 7
    n1 = Node(1); n3 = Node(3); n5 = Node(5); n7 = Node(7)
    n2 = Node(2, n1, n3)
    n6 = Node(6, n5, n7)
    return Node(4, n2, n6)

if __name__ == '__main__':
    root = build_sample()
    for mode in ('pre', 'in', 'post'):
        print(f'{mode}order:', list(BSTIterator(root, mode)))

"""bst_height_from_file.py
Read integers (one per line) from a given file, build a binary search tree,
and output the height of the resulting tree.
"""

import sys
from typing import Optional, List

class Node:
    __slots__ = ('key', 'left', 'right')
    def __init__(self, key: int):
        self.key = key
        self.left: Optional[Node] = None
        self.right: Optional[Node] = None

class BST:
    def __init__(self):
        self.root: Optional[Node] = None

    def insert(self, key: int) -> None:
        def _ins(node: Optional[Node], key: int) -> Node:
            if node is None:
                return Node(key)
            if key < node.key:
                node.left = _ins(node.left, key)
            elif key > node.key:
                node.right = _ins(node.right, key)
            return node
        self.root = _ins(self.root, key)

    def height(self) -> int:
        def _h(node: Optional[Node]) -> int:
            if node is None:
                return -1  # height of empty subtree
            return 1 + max(_h(node.left), _h(node.right))
        return _h(self.root)

def read_numbers(path: str) -> List[int]:
    with open(path, 'r') as f:
        return [int(line.strip()) for line in f if line.strip()]

def main(argv: List[str] | None = None):
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        print('Usage: python bst_height_from_file.py <input_file>')
        return
    numbers = read_numbers(argv[0])
    tree = BST()
    for n in numbers:
        tree.insert(n)
    print('Number of values:', len(numbers))
    print('BST height:', tree.height())

if __name__ == '__main__':
    main()

"""bst_kth_smallest.py
Binary Search Tree with insert and a method kth_smallest(k).
The method runs in O(h + k) time by performing an inorder walk.
"""

from __future__ import annotations
from typing import Optional, List

class Node:
    __slots__ = ('key', 'left', 'right', 'size')
    def __init__(self, key: int):
        self.key = key
        self.left: Optional[Node] = None
        self.right: Optional[Node] = None
        self.size = 1  # number of nodes in subtree rooted here

def _update_size(node: Node) -> None:
    left_sz = node.left.size if node.left else 0
    right_sz = node.right.size if node.right else 0
    node.size = 1 + left_sz + right_sz

class BST:
    def __init__(self):
        self.root: Optional[Node] = None

    def insert(self, key: int) -> None:
        def _ins(node: Optional[Node], key: int) -> Node:
            if node is None:
                return Node(key)
            if key < node.key:
                node.left = _ins(node.left, key)
            elif key > node.key:
                node.right = _ins(node.right, key)
            # duplicates ignored
            _update_size(node)
            return node
        self.root = _ins(self.root, key)

    def kth_smallest(self, k: int) -> int:
        """Return the k‑th smallest key (1‑based). Raises IndexError if out of range."""
        if not self.root or k < 1 or k > self.root.size:
            raise IndexError('k is out of bounds')
        node = self.root
        while node:
            left_sz = node.left.size if node.left else 0
            if k == left_sz + 1:
                return node.key
            if k <= left_sz:
                node = node.left
            else:
                k -= left_sz + 1
                node = node.right
        raise IndexError('k is out of bounds')

if __name__ == '__main__':
    bst = BST()
    for v in [20, 8, 22, 4, 12, 10, 14]:
        bst.insert(v)
    print('Tree size:', bst.root.size if bst.root else 0)
    for i in range(1, bst.root.size + 1):
        print(f'{i}th smallest:', bst.kth_smallest(i))

"""config_loader.py
