    python config_loader.py -c settings.json -t 0.75
"""
import argparse
import json
import sys

def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description='Load JSON config with optional threshold override')
    parser.add_argument('-c', '--config', required=True, help='Path to JSON config file')
    parser.add_argument('-t', '--threshold', type=float, help='Override the "threshold" parameter')
    return parser.parse_args()

def load_config(path: str) -> dict:
    with open(path, 'r', encoding='utf-8') as fh:
        return json.load(fh)

def apply_override(cfg: dict, threshold: float | None) -> dict:
    if threshold is not None:
        cfg['threshold'] = threshold
    return cfg

