# Each octet must be 0-255; the pattern enumerates the possible ranges.
OCTET = r"(?:25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)"
IPV4_RE = re.compile(rf"\b{OCTET}\.{OCTET}\.{OCTET}\.{OCTET}\b")

def contains_ip(line: str) -> bool:
    """Return True if *line* has at least one syntactically valid IPv4 address."""
    return bool(IPV4_RE.search(line))

