'''simple_stack.py
Implementation of a minimal stack data structure using a Python list.
Provides push, pop, peek, is_empty and size operations.
'''

class Stack:
    """A LIFO stack implementation."""

    def __init__(self):
        self._items = []

    def push(self, item):
        """Add *item* to the top of the stack."""
        self._items.append(item)

    def pop(self):
        """Remove and return the top element. Raises IndexError if empty."""
        if self.is_empty():
            raise IndexError('pop from empty stack')
        return self._items.pop()

    def peek(self):
        """Return the top element without removing it. Raises IndexError if empty."""
        if self.is_empty():
            raise IndexError('peek from empty stack')
        return self._items[-1]

    def is_empty(self):
        """Return True if the stack has no elements."""
        return len(self._items) == 0

    def size(self):
        """Return the number of elements in the stack."""
        return len(self._items)

# Example usage (can be removed when importing)
