'''two_stack_queue.py
Implementation of a FIFO queue using two internal Stack objects.
enqueue pushes onto the input stack; dequeue transfers when needed.
'''

class Stack:
    def __init__(self):
        self._data = []
    def push(self, x):
        self._data.append(x)
    def pop(self):
        if not self._data:
            raise IndexError('pop from empty stack')
        return self._data.pop()
    def is_empty(self):
        return not self._data


class TwoStackQueue:
    """Queue built from two stacks with amortized O(1) operations."""

    def __init__(self):
        self._in = Stack()
        self._out = Stack()

    def enqueue(self, item):
        """Add *item* to the rear of the queue."""
        self._in.push(item)

    def _transfer(self):
        """Move all items from the input stack to the output stack."""
        while not self._in.is_empty():
            self._out.push(self._in.pop())

    def dequeue(self):
        """Remove and return the front element. Raises IndexError if empty."""
        if self._out.is_empty():
            self._transfer()
        if self._out.is_empty():
            raise IndexError('dequeue from empty queue')
        return self._out.pop()

    def front(self):
        """Return the front element without removing it. Raises IndexError if empty."""
        if self._out.is_empty():
            self._transfer()
        if self._out.is_empty():
            raise IndexError('front from empty queue')
        # Peek without popping – look at the last element of the internal list
        return self._out._data[-1]

    def is_empty(self):
        return self._in.is_empty() and self._out.is_empty()


if __name__ == '__main__':
    q = TwoStackQueue()
    for i in range(5):
        q.enqueue(i)
    print('front:', q.front())
    while not q.is_empty():
        print('dequeue:', q.dequeue())

