"""unbounded_knapsack.py
Recursive memoized solution for the unbounded knapsack problem.
Given unlimited copies of each item, find the maximum achievable value.
"""

from functools import lru_cache


def unbounded_knapsack(weights, values, capacity):
    """Return the maximum value achievable with unlimited item copies.
    weights, values – parallel lists
    capacity – integer knapsack capacity
    """
    @lru_cache(maxsize=None)
    def best(rem):
        if rem == 0:
            return 0
        max_val = 0
        for w, v in zip(weights, values):
            if w <= rem:
                candidate = v + best(rem - w)
                if candidate > max_val:
                    max_val = candidate
        return max_val
    return best(capacity)

if __name__ == "__main__":
    w = [1, 3, 4]
    v = [15, 20, 30]
    C = 10
    print("Maximum value:", unbounded_knapsack(w, v, C))

