'''memoize_safe.py
A simple memoization decorator that stores results in a dict.
The cache is attached to the wrapper function, not kept in a mutable default.
'''

import functools
from typing import Any, Callable, Dict, Tuple

def memoize(fn: Callable) -> Callable:
    """Cache results of *fn* based on its positional arguments.
    The cache dictionary lives on the wrapper object, so each decorated
    function gets its own isolated storage without using mutable defaults.
    """
    cache: Dict[Tuple[Any, ...], Any] = {}

    @functools.wraps(fn)
    def wrapper(*args):
        if args in cache:
            return cache[args]
        result = fn(*args)
        cache[args] = result
        return result
    wrapper.cache = cache  # expose for introspection
    return wrapper

@memoize
def fib(n: int) -> int:
    """Return the *n*th Fibonacci number using recursion.
    The memoization avoids exponential blow‑up.
    """
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

if __name__ == "__main__":
    for i in range(10):
        print(i, fib(i))
    print('Cache size:', len(fib.cache))

