'''stable_file_sort.py
Read a plain‑text file containing one integer per line, sort the numbers while preserving the original order of duplicate values, and write the result to 'sorted.txt'.
The script uses Python's stable sort and demonstrates handling of I/O errors.
'''

import sys
from pathlib import Path
from typing import List

def read_numbers(path: Path) -> List[int]:
    """Read integers line‑by‑line, ignoring empty lines and whitespace.

    Raises ValueError if a line cannot be parsed as an integer.
    """
    numbers: List[int] = []
    with path.open('r', encoding='utf-8') as f:
        for line_no, line in enumerate(f, 1):
            stripped = line.strip()
            if not stripped:
                continue
            try:
                numbers.append(int(stripped))
            except ValueError as e:
                raise ValueError(f'Line {line_no} is not a valid integer: {stripped}') from e
    return numbers

def write_numbers(path: Path, numbers: List[int]) -> None:
    """Write each integer on its own line.
    """
    with path.open('w', encoding='utf-8') as f:
        for num in numbers:
            f.write(f"{num}\n")

def stable_sort(numbers: List[int]) -> List[int]:
    """Return a new list sorted ascending, preserving duplicate order.
    """
    # The default sort is stable, so duplicates keep original relative positions.
    return sorted(numbers)

def main(input_file: str) -> None:
    src = Path(input_file)
    if not src.is_file():
        sys.exit(f'Error: {input_file} does not exist or is not a file.')
    try:
        data = read_numbers(src)
    except ValueError as exc:
        sys.exit(f'Parsing error: {exc}')
    sorted_data = stable_sort(data)
    out_path = src.parent / 'sorted.txt'
    write_numbers(out_path, sorted_data)
    print(f'Sorted {len(data)} numbers and wrote them to {out_path}')

if __name__ == '__main__':
    if len(sys.argv) != 2:
        sys.exit('Usage: python stable_file_sort.py <input_file>')
    main(sys.argv[1])

