"""class_memo.py

Implements a `method_memoize` descriptor that stores cached results on a
per‑instance basis.  The example class `PrimeChecker` uses it to memoize
whether a number is prime, avoiding repeated expensive checks.
"""

from typing import Callable, Any, Dict, Tuple

class method_memoize:
    """Descriptor that memoizes a method using the instance's `__dict__`.

    Each instance gets its own cache dictionary under the private attribute
    named ``_memo_{func.__name__}``.
    """

    def __init__(self, func: Callable):
        self.func = func
        self.cache_name = f"_memo_{func.__name__}"

    def __get__(self, obj, objtype=None) -> Callable:
        if obj is None:
            return self.func
        # Initialise the cache lazily.
        if not hasattr(obj, self.cache_name):
            setattr(obj, self.cache_name, {})
        cache: Dict[Tuple[Any, ...], Any] = getattr(obj, self.cache_name)

        def wrapper(*args, **kwargs):
            key = args + (frozenset(kwargs.items()),)
            if key in cache:
                return cache[key]
            result = self.func(obj, *args, **kwargs)
            cache[key] = result
            return result

        return wrapper

class PrimeChecker:
    """Check primality with per‑instance memoization.

    The `is_prime` method is expensive for large numbers, so caching the
    result saves time when the same number is queried repeatedly on the same
    instance.
    """

    @method_memoize
    def is_prime(self, n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

if __name__ == "__main__":
    checker = PrimeChecker()
    numbers = [101, 103, 101, 104, 103]
    for num in numbers:
        print(f"{num} is prime? {checker.is_prime(num)}")

'''common_words.py
Utility script that reports the ten most frequent words in a given text file.
Usage: python common_words.py <path_to_file>
''' 
import sys
import re
from collections import Counter

def load_text(path: str) -> str:
    """Read the entire file and return its content as a single string.
    """
    with open(path, encoding='utf-8') as f:
        return f.read()

def tokenize(text: str) -> list[str]:
    """Return a list of lower‑cased words, stripping punctuation.
    """
    # Use regex to keep only alphabetic characters and apostrophes inside words
    return re.findall(r"\b[a-zA-Z']+\b", text.lower())

def most_common(words: list[str], n: int = 10) -> list[tuple[str, int]]:
    """Wrap Counter.most_common for clarity.
    """
    counter = Counter(words)
    return counter.most_common(n)

def main(argv: list[str] = None) -> None:
    if argv is None:
        argv = sys.argv
    if len(argv) != 2:
        print('Usage: python common_words.py <path_to_file>')
        sys.exit(1)
    path = argv[1]
    text = load_text(path)
    words = tokenize(text)
    for word, freq in most_common(words):
        print(f"{word}: {freq}")

