'''doc_word_counter.py
Aggregate word counts per document using a defaultdict of Counter objects.
The module defines a helper function and runs a small demo when executed.
''' 
import re
from collections import defaultdict, Counter
from typing import List, Dict

def tokenize(text: str) -> List[str]:
    """Return a list of lower‑cased words extracted from *text*.
    """
    return re.findall(r"\b\w+\b", text.lower())

def build_index(docs: List[str]) -> Dict[int, Counter]:
    """Return a mapping from document index to a Counter of its words.
    """
    index: defaultdict[int, Counter] = defaultdict(Counter)
    for i, doc in enumerate(docs):
        index[i].update(tokenize(doc))
    return dict(index)

def demo() -> None:
    corpus = [
        "Python is great. Python is easy to learn.",
        "Java and C++ are also popular languages.",
        "Python, Java, and C++ can interoperate via APIs."
    ]
    result = build_index(corpus)
    for doc_id, counter in result.items():
        top = counter.most_common(3)
        print(f"Doc {doc_id} top words: {top}")

if __name__ == '__main__':
