'''fifo_queue.py
Implementation of a simple FIFO queue using collections.deque.
Exports Queue class with enqueue, dequeue, peek, and __len__.
A minimal test suite runs when the module is executed directly.
''' 
from collections import deque
from typing import Any, Iterable

class Queue:
    """FIFO queue backed by a deque.
    Supports typical queue operations in O(1) time.
    """
    def __init__(self, items: Iterable[Any] = ()) -> None:
        self._data = deque(items)

    def enqueue(self, item: Any) -> None:
        """Add *item* to the right end of the queue."""
        self._data.append(item)

    def dequeue(self) -> Any:
        """Remove and return the left‑most item.
        Raises IndexError if the queue is empty.
        """
        if not self._data:
            raise IndexError('dequeue from an empty queue')
        return self._data.popleft()

    def peek(self) -> Any:
        """Return the next item without removing it.
        Raises IndexError if the queue is empty.
        """
        if not self._data:
            raise IndexError('peek from an empty queue')
        return self._data[0]

    def __len__(self) -> int:
        return len(self._data)

    def __repr__(self) -> str:
        return f"Queue({list(self._data)!r})"

def _run_tests() -> None:
    q = Queue([1, 2])
    assert len(q) == 2, 'length after init'
    q.enqueue(3)
    assert q.peek() == 1, 'peek after enqueue'
    assert q.dequeue() == 1, 'first dequeue'
    assert q.dequeue() == 2, 'second dequeue'
    assert len(q) == 1, 'length after two dequeues'
    try:
        empty = Queue()
        empty.dequeue()
    except IndexError:
        pass
    else:
        raise AssertionError('dequeue should raise on empty')
    print('All FIFO queue tests passed.')

if __name__ == '__main__':
    _run_tests()

'''extract_emails.py
Extracts email addresses from a given input file using regular expressions.
Usage: python extract_emails.py input.txt > emails.txt
''' 
import re
import sys

def load_text(path):
    """Read the entire contents of *path* and return it as a string."""
    with open(path, 'r', encoding='utf-8') as f:
        return f.read()

def find_emails(text):
    """Return a list of unique email addresses found in *text*.
    The pattern follows the conventional ``username@domain.tld`` format.
    """
    email_pattern = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
    return sorted(set(email_pattern.findall(text)))

