'''extract_timestamps.py
Parse a log file and output all timestamps matching the pattern YYYY‑MM‑DD HH:MM:SS.
Usage: python extract_timestamps.py server.log > timestamps.txt
''' 
import re
import sys

TIMESTAMP_RE = re.compile(r"\b(\d{4})-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])\s([01]\d|2[0-3]):([0-5]\d):([0-5]\d)\b")

def extract(file_path):
    """Yield each timestamp string found in *file_path* line by line."""
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            for match in TIMESTAMP_RE.finditer(line):
                yield match.group(0)

def main():
    if len(sys.argv) != 2:
        sys.stderr.write('Usage: python extract_timestamps.py <log_file>\n')
        sys.exit(1)
    for ts in extract(sys.argv[1]):
        print(ts)

if __name__ == '__main__':
    main()

'''Linear probing hash table implementation.

Provides a HashTable class supporting insert, get, and delete operations.
Uses a simple modulo hash function and linear probing for collision resolution.
''' 

class _DeletedEntry:
    """Singleton marker for a deleted slot in the hash table."""
    pass

_DELETED = _DeletedEntry()

class HashTable:
    def __init__(self, capacity=11, load_factor=0.5):
        self._size = 0
        self._capacity = capacity
        self._load_factor = load_factor
        self._buckets = [None] * self._capacity

    def _hash(self, key):
        return hash(key) % self._capacity

    def _resize(self):
        old_buckets = self._buckets
        self._capacity = self._capacity * 2 + 1
        self._buckets = [None] * self._capacity
        self._size = 0
        for entry in old_buckets:
            if entry is not None and entry is not _DELETED:
                self.insert(entry[0], entry[1])

    def _probe(self, key):
        index = self._hash(key)
        start = index
        while True:
            slot = self._buckets[index]
            if slot is None or slot is _DELETED or slot[0] == key:
                return index
            index = (index + 1) % self._capacity
            if index == start:
                raise RuntimeError('HashTable is full')

    def insert(self, key, value):
        if self._size + 1 > self._capacity * self._load_factor:
            self._resize()
        index = self._probe(key)
        if self._buckets[index] is None or self._buckets[index] is _DELETED:
            self._size += 1
        self._buckets[index] = (key, value)

    def get(self, key, default=None):
        index = self._hash(key)
        start = index
        while True:
            slot = self._buckets[index]
            if slot is None:
                return default
            if slot is not _DELETED and slot[0] == key:
                return slot[1]
            index = (index + 1) % self._capacity
            if index == start:
                return default

    def delete(self, key):
        index = self._hash(key)
        start = index
        while True:
            slot = self._buckets[index]
            if slot is None:
                raise KeyError(key)
            if slot is not _DELETED and slot[0] == key:
                self._buckets[index] = _DELETED
                self._size -= 1
                return
            index = (index + 1) % self._capacity
            if index == start:
                raise KeyError(key)

    def __len__(self):
        return self._size

    def __repr__(self):
        items = [(k, v) for k, v in self._buckets if k is not None and k is not _DELETED]
        return f'HashTable({items})'

if __name__ == '__main__':
    ht = HashTable()
    ht.insert('apple', 3)
    ht.insert('banana', 5)
    print('apple ->', ht.get('apple'))
    ht.delete('apple')
    print('apple after delete ->', ht.get('apple', 'missing'))

'''Separate chaining hash table implementation.

Each bucket holds a Python list of (key, value) pairs, providing O(1) average access.
The file defines a HashTable class with insert, get, delete, and items methods.
''' 

class HashTable:
    def __init__(self, capacity=13, load_factor=0.75):
        self._capacity = capacity
        self._load_factor = load_factor
        self._buckets = [[] for _ in range(self._capacity)]
        self._size = 0

    def _hash(self, key):
        return hash(key) % self._capacity

    def _resize(self):
        old = self._buckets
        self._capacity = self._capacity * 2 + 1
        self._buckets = [[] for _ in range(self._capacity)]
        self._size = 0
        for bucket in old:
            for k, v in bucket:
                self.insert(k, v)

    def insert(self, key, value):
        if self._size + 1 > self._capacity * self._load_factor:
            self._resize()
        idx = self._hash(key)
        bucket = self._buckets[idx]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return
        bucket.append((key, value))
        self._size += 1

    def get(self, key, default=None):
        idx = self._hash(key)
        for k, v in self._buckets[idx]:
            if k == key:
                return v
        return default

    def delete(self, key):
        idx = self._hash(key)
        bucket = self._buckets[idx]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                del bucket[i]
                self._size -= 1
                return
        raise KeyError(key)

    def items(self):
        for bucket in self._buckets:
            for k, v in bucket:
                yield k, v

    def __len__(self):
        return self._size

    def __repr__(self):
        items = list(self.items())
        return f'HashTable({items})'

if __name__ == '__main__':
    ht = HashTable()
    for i in range(20):
        ht.insert(f'key{i}', i * 2)
    print('size:', len(ht))
    print('key7 ->', ht.get('key7'))
    ht.delete('key7')
    print('after delete, key7 ->', ht.get('key7', 'not found'))

'''Quadratic probing hash table with key iterator.

The HashTable class stores (key, value) pairs in a list, resolves collisions
using quadratic probing (i^2), and implements __iter__ to yield stored keys.
''' 

class HashTable:
    _DELETED = object()

    def __init__(self, capacity=11, load_factor=0.6):
        self._capacity = capacity
        self._load_factor = load_factor
        self._buckets = [None] * self._capacity
        self._size = 0

    def _hash(self, key):
        return hash(key) % self._capacity

    def _probe(self, key):
        idx = self._hash(key)
        i = 0
        while True:
            slot = self._buckets[idx]
            if slot is None or slot is self._DELETED or slot[0] == key:
                return idx
            i += 1
            idx = (self._hash(key) + i * i) % self._capacity
            if i > self._capacity:
                raise RuntimeError('Table full')

    def _resize(self):
        old = self._buckets
        self._capacity = self._capacity * 2 + 1
        self._buckets = [None] * self._capacity
        self._size = 0
        for entry in old:
            if entry and entry is not self._DELETED:
                self.insert(entry[0], entry[1])

    def insert(self, key, value):
        if self._size + 1 > self._capacity * self._load_factor:
            self._resize()
        idx = self._probe(key)
        if self._buckets[idx] is None or self._buckets[idx] is self._DELETED:
            self._size += 1
        self._buckets[idx] = (key, value)

    def get(self, key, default=None):
        idx = self._hash(key)
        i = 0
        while True:
            slot = self._buckets[idx]
            if slot is None:
                return default
            if slot is not self._DELETED and slot[0] == key:
                return slot[1]
            i += 1
            idx = (self._hash(key) + i * i) % self._capacity
            if i > self._capacity:
                return default

    def delete(self, key):
        idx = self._hash(key)
        i = 0
        while True:
            slot = self._buckets[idx]
            if slot is None:
                raise KeyError(key)
            if slot is not self._DELETED and slot[0] == key:
                self._buckets[idx] = self._DELETED
                self._size -= 1
                return
            i += 1
            idx = (self._hash(key) + i * i) % self._capacity
            if i > self._capacity:
                raise KeyError(key)

    def __len__(self):
        return self._size

    def __iter__(self):
        for slot in self._buckets:
            if slot and slot is not self._DELETED:
                yield slot[0]

    def __repr__(self):
        items = [(k, v) for k, v in ((s[0], s[1]) for s in self._buckets if s and s is not self._DELETED)]
        return f'HashTable({items})'

if __name__ == '__main__':
    ht = HashTable()
    for ch in 'abcde':
        ht.insert(ch, ord(ch))
    print('Keys:', list(ht))
    print('Value of c:', ht.get('c'))
    ht.delete('c')
    print('After delete, keys:', list(ht))

'''Generic hash map with basic operations and self‑contained unit tests.

Uses separate chaining with Python lists for buckets, works with any hashable key.
The TestHashMap class at the bottom validates insert, get, delete, and collision handling.
''' 

import unittest

class HashMap:
    def __init__(self, capacity=8):
        self._capacity = capacity
        self._buckets = [[] for _ in range(self._capacity)]
        self._size = 0

    def _index(self, key):
        return hash(key) % self._capacity

    def _find_bucket(self, key):
        idx = self._index(key)
        bucket = self._buckets[idx]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                return bucket, i
        return bucket, None

    def set(self, key, value):
        bucket, pos = self._find_bucket(key)
        if pos is not None:
            bucket[pos] = (key, value)
        else:
            bucket.append((key, value))
            self._size += 1
        if self._size > self._capacity * 0.75:
            self._rehash()

    def get(self, key, default=None):
        bucket, pos = self._find_bucket(key)
        if pos is not None:
            return bucket[pos][1]
        return default

    def delete(self, key):
        bucket, pos = self._find_bucket(key)
        if pos is None:
            raise KeyError(key)
        del bucket[pos]
        self._size -= 1

    def _rehash(self):
        old = self._buckets
        self._capacity = self._capacity * 2
        self._buckets = [[] for _ in range(self._capacity)]
        self._size = 0
        for bucket in old:
            for k, v in bucket:
                self.set(k, v)

    def __len__(self):
        return self._size

    def __contains__(self, key):
        _, pos = self._find_bucket(key)
        return pos is not None

    def __repr__(self):
        items = [(k, v) for bucket in self._buckets for k, v in bucket]
        return f'HashMap({items})'

class TestHashMap(unittest.TestCase):
    def setUp(self):
        self.map = HashMap()
        self.map.set('a', 1)
        self.map.set('b', 2)
        self.map.set(3, 'three')

    def test_get(self):
        self.assertEqual(self.map.get('a'), 1)
        self.assertEqual(self.map.get(3), 'three')
        self.assertIsNone(self.map.get('missing'))

    def test_update(self):
        self.map.set('a', 10)
        self.assertEqual(self.map.get('a'), 10)

    def test_delete(self):
        self.map.delete('b')
        self.assertNotIn('b', self.map)
        with self.assertRaises(KeyError):
            self.map.delete('b')

    def test_collision(self):
        # Force a collision by using custom keys with same hash modulo capacity
        class BadKey:
            def __init__(self, h):
                self._h = h
            def __hash__(self):
                return self._h
            def __eq__(self, other):
                return isinstance(other, BadKey) and self._h == other._h
        k1 = BadKey(5)
        k2 = BadKey(5)
        self.map.set(k1, 'first')
        self.map.set(k2, 'second')
        self.assertEqual(self.map.get(k1), 'first')
        self.assertEqual(self.map.get(k2), 'second')

if __name__ == '__main__':
    unittest.main(argv=['first-arg-is-ignored'], exit=False)

'''Hash table storing custom objects with a user‑defined hash function.

Person objects are hashed by (last_name, first_name) tuple. The table uses open
addressing with linear probing. Demonstrates insertion, lookup, and deletion.
''' 

class Person:
    def __init__(self, first, last, age):
        self.first = first
        self.last = last
        self.age = age
    def __repr__(self):
        return f'Person({self.first!r}, {self.last!r}, {self.age})'

def person_hash(person):
    """Hash function that combines last and first name.
    Returns an int suitable for modulo with table capacity.
    """
    return hash((person.last.lower(), person.first.lower()))

class ObjectHashTable:
    _DELETED = object()
    def __init__(self, capacity=13, load_factor=0.6):
        self._capacity = capacity
        self._load = load_factor
        self._size = 0
        self._buckets = [None] * self._capacity
    def _probe(self, key_hash, key_obj):
        idx = key_hash % self._capacity
        i = 0
        while True:
            slot = self._buckets[idx]
            if slot is None or slot is self._DELETED or slot[0] == key_obj:
                return idx
            i += 1
            idx = (key_hash + i) % self._capacity
    def _resize(self):
        old = self._buckets
        self._capacity = self._capacity * 2 + 1
        self._buckets = [None] * self._capacity
        self._size = 0
        for entry in old:
            if entry and entry is not self._DELETED:
                self.insert(entry[0], entry[1])
    def insert(self, key_obj, value):
        if self._size + 1 > self._capacity * self._load:
            self._resize()
        h = person_hash(key_obj)
        idx = self._probe(h, key_obj)
        if self._buckets[idx] is None or self._buckets[idx] is self._DELETED:
            self._size += 1
        self._buckets[idx] = (key_obj, value)
    def get(self, key_obj, default=None):
        h = person_hash(key_obj)
        idx = h % self._capacity
        i = 0
        while True:
            slot = self._buckets[idx]
            if slot is None:
                return default
            if slot is not self._DELETED and slot[0] == key_obj:
                return slot[1]
            i += 1
            idx = (h + i) % self._capacity
    def delete(self, key_obj):
        h = person_hash(key_obj)
        idx = h % self._capacity
        i = 0
        while True:
            slot = self._buckets[idx]
            if slot is None:
                raise KeyError(key_obj)
            if slot is not self._DELETED and slot[0] == key_obj:
                self._buckets[idx] = self._DELETED
                self._size -= 1
                return
            i += 1
            idx = (h + i) % self._capacity
    def __repr__(self):
        items = [(k, v) for k, v in ((s[0], s[1]) for s in self._buckets if s and s is not self._DELETED)]
        return f'ObjectHashTable({items})'

if __name__ == '__main__':
    ht = ObjectHashTable()
    p1 = Person('John', 'Doe', 30)
    p2 = Person('Jane', 'Doe', 25)
    ht.insert(p1, 'Engineer')
    ht.insert(p2, 'Designer')
    print('Lookup John Doe ->', ht.get(Person('John', 'Doe', 0)))
    ht.delete(p1)
    print('After deletion, table ->', ht)

