# id_printer.py
# Shows how the GIL influences CPU‑bound work across threads vs processes.
# Each worker calculates a small prime‑checking loop and then prints its identifier.

import time
import threading
import multiprocessing as mp

def cpu_job(limit: int) -> int:
    """Return the count of prime numbers up to `limit` (inefficient on purpose)."""
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True
    return sum(1 for i in range(limit) if is_prime(i))

def thread_worker(name: str, limit: int):
    count = cpu_job(limit)
    print(f"[Thread {name}] primes ≤{limit}: {count}")

def process_worker(name: str, limit: int, out):
    count = cpu_job(limit)
    out.put((name, count))

def run_threads():
    threads = []
    for i in range(3):
        t = threading.Thread(target=thread_worker, args=(f'T{i+1}', 20000))
        threads.append(t)
        t.start()
    for t in threads:
        t.join()

def run_processes():
    out = mp.Queue()
    procs = []
    for i in range(3):
        p = mp.Process(target=process_worker, args=(f'P{i+1}', 20000, out))
        procs.append(p)
        p.start()
    for p in procs:
        p.join()
    while not out.empty():
        name, count = out.get()
        print(f"[Process {name}] primes ≤20000: {count}")

if __name__ == '__main__':
    start = time.time()
    print('--- Threaded run ---')
    run_threads()
    print('Threads elapsed:', time.time() - start, 'seconds')
    start = time.time()
    print('\n--- Process run ---')
    run_processes()
    print('Processes elapsed:', time.time() - start, 'seconds')

