class DNode:
    """Node for a doubly linked list storing a value and links to neighbors."""
    __slots__ = ('value', 'prev', 'next')

    def __init__(self, value, prev=None, next=None):
        self.value = value
        self.prev = prev
        self.next = next

    def __repr__(self):
        return f'DNode({self.value!r})'


class DoublyLinkedList:
    """A mutable doubly linked list supporting O(1) push/pop at both ends."""

    def __init__(self):
        self.head = None
        self.tail = None
        self._size = 0

    def __len__(self):
        return self._size

    def is_empty(self):
        return self._size == 0

    def push_head(self, value):
        """Insert a new node at the front of the list."""
        node = DNode(value, None, self.head)
        if self.head:
            self.head.prev = node
        else:
            self.tail = node
        self.head = node
        self._size += 1

    def push_tail(self, value):
        """Insert a new node at the back of the list."""
        node = DNode(value, self.tail, None)
        if self.tail:
            self.tail.next = node
        else:
            self.head = node
        self.tail = node
        self._size += 1

    def pop_head(self):
        """Remove and return the value at the front; raise IndexError if empty."""
        if not self.head:
            raise IndexError('pop from empty list')
        value = self.head.value
        self.head = self.head.next
        if self.head:
            self.head.prev = None
        else:
            self.tail = None
        self._size -= 1
        return value

    def pop_tail(self):
        """Remove and return the value at the back; raise IndexError if empty."""
        if not self.tail:
            raise IndexError('pop from empty list')
        value = self.tail.value
        self.tail = self.tail.prev
        if self.tail:
            self.tail.next = None
        else:
            self.head = None
        self._size -= 1
        return value

    def reverse(self):
        """Reverse the list in place by swapping next and prev links for each node."""
        current = self.head
        while current:
            current.prev, current.next = current.next, current.prev
            current = current.prev  # after swap, former next is now prev
        self.head, self.tail = self.tail, self.head

    def to_list(self):
        """Return a Python list of values from head to tail."""
        result = []
        node = self.head
        while node:
            result.append(node.value)
            node = node.next
        return result

    def __repr__(self):
        return f'DoublyLinkedList({self.to_list()})'

if __name__ == '__main__':
    dl = DoublyLinkedList()
    for i in range(5):
        dl.push_tail(i)
    print('Original:', dl)
    dl.reverse()
    print('Reversed:', dl)
    print('Pop head:', dl.pop_head())
    print('After pop:', dl)

'''sorted_linked_list.py
Implementation of a singly linked list that maintains ascending order on insertion.
Includes a method to retrieve the k‑th smallest element (1‑based index).
'''

class SortedNode:
    __slots__ = ('value', 'next')

    def __init__(self, value, next=None):
        self.value = value
        self.next = next

    def __repr__(self):
        return f'SortedNode({self.value!r})'


class SortedLinkedList:
    """A list that stays sorted; duplicate values are allowed."""

    def __init__(self):
        self.head = None
        self._size = 0

    def __len__(self):
        return self._size

    def insert(self, value):
        """Insert *value* while preserving ascending order."""
        new_node = SortedNode(value)
        if self.head is None or value < self.head.value:
            new_node.next = self.head
            self.head = new_node
        else:
            prev = self.head
            while prev.next and prev.next.value <= value:
                prev = prev.next
            new_node.next = prev.next
            prev.next = new_node
        self._size += 1

    def kth_smallest(self, k):
        """Return the k‑th smallest element (1‑based). Raise IndexError if out of range."""
        if k < 1 or k > self._size:
            raise IndexError('k is out of bounds')
        current = self.head
        for _ in range(k - 1):
            current = current.next
        return current.value

    def to_list(self):
        result = []
        node = self.head
        while node:
            result.append(node.value)
            node = node.next
        return result

    def __repr__(self):
        return f'SortedLinkedList({self.to_list()})'

if __name__ == '__main__':
    sl = SortedLinkedList()
    for num in [7, 3, 5, 2, 9, 5]:
        sl.insert(num)
    print('Sorted list:', sl)
    print('3rd smallest element:', sl.kth_smallest(3))

'''node_pool_linked_list.py
A tiny object‑pool for linked‑list nodes to reduce allocation overhead.
The pool recycles Node instances; the LinkedList class obtains nodes via allocate_node.
'''

class PooledNode:
    __slots__ = ('value', 'next', '_in_use')

    def __init__(self, value=None, next=None):
        self.value = value
        self.next = next
        self._in_use = False

    def reset(self):
        self.value = None
        self.next = None
        self._in_use = False

    def __repr__(self):
        status = 'used' if self._in_use else 'free'
        return f'PooledNode({self.value!r}, {status})'


class NodePool:
    """Simple fixed‑size pool of PooledNode objects."""

    def __init__(self, capacity=100):
        self._free = [PooledNode() for _ in range(capacity)]

    def allocate_node(self, value, next=None):
        if not self._free:
            raise RuntimeError('Node pool exhausted')
        node = self._free.pop()
        node.value = value
        node.next = next
        node._in_use = True
        return node

    def free_node(self, node):
        node.reset()
        self._free.append(node)

    def available(self):
        return len(self._free)


class PooledLinkedList:
    """Linked list that obtains its nodes from a NodePool."""

    def __init__(self, pool: NodePool):
        self.pool = pool
        self.head = None
        self._size = 0

    def insert_head(self, value):
        node = self.pool.allocate_node(value, self.head)
        self.head = node
        self._size += 1

    def delete_head(self):
        if self.head is None:
            raise IndexError('delete from empty list')
        old = self.head
        self.head = old.next
        self.pool.free_node(old)
        self._size -= 1
        return old.value

    def to_list(self):
        result = []
        cur = self.head
        while cur:
            result.append(cur.value)
            cur = cur.next
        return result

    def __len__(self):
        return self._size

    def __repr__(self):
        return f'PooledLinkedList({self.to_list()})'

if __name__ == '__main__':
    pool = NodePool(capacity=10)
    lst = PooledLinkedList(pool)
    for i in range(5):
        lst.insert_head(i)
    print('List after inserts:', lst)
    print('Pool available nodes:', pool.available())
    lst.delete_head()
    print('List after one delete:', lst)
    print('Pool available nodes:', pool.available())

'''iterative_search_file.py

Read a sorted integer list from ``data.txt`` (one integer per line) and
prompt the user for a number to locate.  The script uses an iterative binary
search and prints the index or a not‑found message.
'''

def load_numbers(path):
    with open(path, "r") as f:
        return [int(line.strip()) for line in f if line.strip()]

def iterative_binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

if __name__ == "__main__":
    numbers = load_numbers("data.txt")
    try:
        value = int(input("Enter integer to search: "))
    except ValueError:
        print("Please provide a valid integer.")
        raise SystemExit
    idx = iterative_binary_search(numbers, value)
    if idx != -1:
        print(f"Found {value} at index {idx}.")
    else:
        print(f"{value} not present in the list.")

'''binary_search_visual.py

Console visualiser for binary search.  At each iteration the current
search interval is printed with brackets around the middle element.
Run the script and follow the prompts.
'''

def visual_binary_search(arr, target):
    left, right = 0, len(arr) - 1
    step = 0
    while left <= right:
        step += 1
        mid = (left + right) // 2
        # Build a visual line
        line = []
        for i, val in enumerate(arr):
            if i < left or i > right:
                line.append('   ')
            elif i == mid:
                line.append(f'[{val:2}]')
            else:
                line.append(f' {val:2} ')
        print(f"Step {step}: {' '.join(line)}")
        if arr[mid] == target:
            print(f"Found {target} at index {mid}\n")
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    print(f"{target} not found after {step} steps.\n")
    return -1

if __name__ == "__main__":
    data = list(range(0, 32, 2))  # [0,2,4,...,30]
    while True:
        try:
            val = int(input('Enter an even number between 0 and 30 (or blank to quit): '))
        except ValueError:
            break
        visual_binary_search(data, val)

'''binary_search_benchmark.py

Creates a sorted list of one million integers and measures the average
runtime of recursive and iterative binary search for 10 000 random
queries.  Results are printed in milliseconds.
'''
import random, time

def recursive_search(arr, target, left=0, right=None):
    if right is None:
        right = len(arr) - 1
    if left > right:
        return -1
    mid = (left + right) // 2
    if arr[mid] == target:
        return mid
    if arr[mid] < target:
        return recursive_search(arr, target, mid + 1, right)
    return recursive_search(arr, target, left, mid - 1)

def iterative_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

if __name__ == "__main__":
    size = 1_000_000
    data = list(range(size))
    queries = [random.randint(0, size - 1) for _ in range(10_000)]

    def bench(func):
        start = time.perf_counter()
        for q in queries:
            func(data, q)
        return (time.perf_counter() - start) * 1_000  # ms

    rec_time = bench(recursive_search)
    itr_time = bench(iterative_search)
    print(f"Recursive search total time: {rec_time:.2f} ms")
    print(f"Iterative search total time: {itr_time:.2f} ms")

'''nonempty_str.py
Descriptor that enforces a non‑empty string on any attribute it manages.
A sample ``Person`` class demonstrates its use.
'''

class NonEmptyString:
    """Descriptor enforcing a non‑empty ``str`` value.

    The descriptor stores the value in the instance's ``__dict__`` using a
    unique private name that is derived from the attribute name during ``__set_name__``.
    """

    def __set_name__(self, owner, name):
        self.private_name = f"_{owner.__name__}{name}"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self  # access through class returns the descriptor itself
        return getattr(obj, self.private_name, "")

    def __set__(self, obj, value):
        if not isinstance(value, str):
            raise TypeError(f"{self.private_name} must be a string")
        if not value:
            raise ValueError(f"{self.private_name} cannot be empty")
        setattr(obj, self.private_name, value)

    def __delete__(self, obj):
        raise AttributeError("Can't delete attribute")

class Person:
    """Simple data container using the ``NonEmptyString`` descriptor for name.

    The ``age`` attribute is a plain integer for contrast.
    """

    name = NonEmptyString()  # descriptor applied

    def __init__(self, name: str, age: int):
        self.name = name  # triggers descriptor validation
        self.age = age

    def __repr__(self) -> str:
        return f"Person(name={self.name!r}, age={self.age})"

if __name__ == "__main__":
    p = Person("Alice", 30)
    print(p)                     # Person(name='Alice', age=30)
    try:
        p.name = ""            # Should raise ValueError
    except Exception as e:
        print("Error:", e)

'''access_counter.py
Descriptor that records read accesses for an attribute.
A ``Counter`` class demonstrates usage on a ``value`` field.
'''

class AccessCounter:
    """Descriptor that increments a counter each time the attribute is read.

    The counter is stored on the *instance* under a name derived from the attribute
    (``_accesses_<attr>``).  Writes do not affect the counter.
    """

    def __set_name__(self, owner, name):
        self.attr_name = name
        self.counter_name = f"_accesses_{name}"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        # Increment the counter each time the attribute is accessed
        current = getattr(obj, self.counter_name, 0) + 1
        setattr(obj, self.counter_name, current)
        return obj.__dict__[self.attr_name]

    def __set__(self, obj, value):
        obj.__dict__[self.attr_name] = value

    def accesses(self, obj):
        """Return how many times the attribute has been read for *obj*."""
        return getattr(obj, self.counter_name, 0)

class Counter:
    """Simple container whose ``value`` attribute tracks read accesses.

    ``value`` is stored normally, but every ``counter.value`` read increments
    an internal counter accessible via ``counter.reads()``.
    """

    value = AccessCounter()

    def __init__(self, start: int = 0):
        self.value = start

    def reads(self) -> int:
        return self.__class__.value.accesses(self)

    def __repr__(self) -> str:
        return f"Counter(value={self.value}, reads={self.reads()})"

if __name__ == "__main__":
    c = Counter(10)
    print(c)               # Counter(value=10, reads=1) – first access in __repr__
    _ = c.value            # second read
    _ = c.value            # third read
    print("Read count:", c.reads())  # Should be 3

'''lazy_property.py
Implementation of a ``lazy_property`` decorator that caches the result of a method.
The ``Expensive`` class uses it to compute a heavy value only once.
'''

class LazyProperty:
    """Descriptor implementing a read‑only, lazily evaluated property.

    The first time the attribute is accessed, the wrapped function is called and
    its result stored in the instance's ``__dict__`` under the same name.  Subsequent
    accesses return the cached value without recomputation.
    """

    def __init__(self, func):
        self.func = func
        self.name = func.__name__

    def __set_name__(self, owner, name):
        # Ensure the descriptor uses the original attribute name for caching
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        if self.name not in obj.__dict__:
            # Compute and cache the value on first access
            obj.__dict__[self.name] = self.func(obj)
        return obj.__dict__[self.name]

    def __set__(self, obj, value):
        raise AttributeError(f"Can't set attribute '{self.name}' – it is lazy and read‑only")

def lazy_property(func):
    """Decorator returning a ``LazyProperty`` instance.

    Usage::

        @lazy_property
        def data(self):
            ...
    """
    return LazyProperty(func)

class Expensive:
    """Sample class with a lazily computed ``result`` attribute.

    The ``result`` simulates a costly operation by sleeping for a short time.
    """

    def __init__(self, base: int):
        self.base = base

    @lazy_property
    def result(self) -> int:
        import time
        time.sleep(0.1)          # simulate work
        return self.base ** 2

    def __repr__(self) -> str:
        return f"Expensive(base={self.base}, result={self.result})"

if __name__ == "__main__":
    e = Expensive(7)
    print("First access, compute:", e.result)   # triggers computation
    print("Second access, cached:", e.result)   # uses cached value

'''bounded_number.py
Descriptor ``BoundedNumber`` validates that a value lies between ``min_value`` and ``max_value``.
The ``Sensor`` class shows two independent bounded attributes.
'''

class BoundedNumber:
    """Descriptor enforcing a numeric range.

    Parameters are given when the descriptor is instantiated: ``min_value`` and
    ``max_value``.  The descriptor stores the actual value in the instance's
    ``__dict__`` using a mangled private name.
    """

    def __init__(self, min_value: float, max_value: float):
        if min_value > max_value:
            raise ValueError("min_value cannot be greater than max_value")
        self.min = min_value
        self.max = max_value

    def __set_name__(self, owner, name):
        self.public_name = name
        self.private_name = f"_{owner.__name__}{name}"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return getattr(obj, self.private_name, None)

    def __set__(self, obj, value):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{self.public_name} must be a number")
        if not (self.min <= value <= self.max):
            raise ValueError(f"{self.public_name} must be between {self.min} and {self.max}")
        setattr(obj, self.private_name, float(value))

    def __delete__(self, obj):
        raise AttributeError(f"Can't delete attribute '{self.public_name}'")

class Sensor:
    """Example class with temperature and pressure bounded attributes."""

    temperature = BoundedNumber(min_value=-50.0, max_value=150.0)
    pressure = BoundedNumber(min_value=0.0, max_value=500.0)

    def __init__(self, temperature: float, pressure: float):
        self.temperature = temperature  # validated by descriptor
        self.pressure = pressure

    def __repr__(self) -> str:
        return f"Sensor(temperature={self.temperature}, pressure={self.pressure})"

if __name__ == "__main__":
    s = Sensor(20, 101.3)
    print(s)
    try:
        s.temperature = 200  # exceeds max, should raise
    except Exception as e:
        print("Error:", e)

'''logging_descriptor.py
A ``LoggedAttribute`` descriptor that prints a log line on every access.
The ``Config`` class uses it for several configuration options.
'''

class LoggedAttribute:
    """Descriptor that logs get, set, and delete actions.

    The log is printed to stdout; in a real system you might use the ``logging``
    module instead.  The actual value is stored under a mangled name derived from
    the owning class and attribute name.
    """

    def __init__(self, default=None):
        self.default = default

    def __set_name__(self, owner, name):
        self.name = name
        self.private_name = f"_{owner.__name__}{name}"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        value = getattr(obj, self.private_name, self.default)
        print(f"[GET] {obj.__class__.__name__}.{self.name} -> {value!r}")
        return value

    def __set__(self, obj, value):
        print(f"[SET] {obj.__class__.__name__}.{self.name} = {value!r}")
        setattr(obj, self.private_name, value)

    def __delete__(self, obj):
        print(f"[DEL] {obj.__class__.__name__}.{self.name}")
        if hasattr(obj, self.private_name):
            delattr(obj, self.private_name)
        else:
            raise AttributeError(f"{self.name} not set")

class Config:
    """Example configuration class using ``LoggedAttribute`` for its fields."""

    host = LoggedAttribute(default="localhost")
    port = LoggedAttribute(default=8080)

    def __init__(self, host=None, port=None):
        if host is not None:
            self.host = host
        if port is not None:
            self.port = port

    def __repr__(self) -> str:
        return f"Config(host={self.host!r}, port={self.port!r})"

if __name__ == "__main__":
    cfg = Config()
    print(cfg)               # triggers GET logs for both attributes
    cfg.host = "example.com"
    cfg.port = 443
    del cfg.host
    try:
        print(cfg.host)       # will use default after deletion
    except Exception as e:
        print("Error:", e)

