'''prime_iterator.py
Iterator that yields prime numbers one by one.
It stops after producing a user‑specified count of primes.
'''

class PrimeIterator:
    """Yield the first `count` prime numbers.

    Parameters
    ----------
    count : int
        How many prime numbers to generate. Must be positive.
    """

    def __init__(self, count: int):
        if count <= 0:
            raise ValueError('count must be positive')
        self._remaining = count
        self._current = 2  # first prime

    def __iter__(self):
        return self

    def __next__(self) -> int:
        if self._remaining == 0:
            raise StopIteration
        # Find next prime starting from self._current
        while not self._is_prime(self._current):
            self._current += 1
        prime = self._current
        self._current += 1
        self._remaining -= 1
        return prime

    @staticmethod
    def _is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

# Demo when executed directly
if __name__ == '__main__':
    pi = PrimeIterator(15)
    print('First 15 primes:')
    for p in pi:
        print(p, end=' ')
    print()

'''flatten_iterator.py
Provides a LazyFlatten iterator that walks through a nested list structure (a list of lists)
and yields each inner element one by one without building an intermediate list.
'''

from typing import List, Any, Iterator

class LazyFlatten(Iterator[Any]):
    """Iterate over a two‑dimensional list, flattening it lazily.

    Parameters
    ----------
    data : List[List[Any]]
        The nested list to flatten.
    """

    def __init__(self, data: List[List[Any]]):
        self._outer = iter(data)          # iterator over the outer list
        self._inner = iter([])            # placeholder for inner iterator

    def __iter__(self) -> 'LazyFlatten':
        return self

    def __next__(self) -> Any:
        while True:
            try:
                return next(self._inner)
            except StopIteration:
                # Current inner exhausted, move to next outer list
                self._inner = iter(next(self._outer))

# Demo usage
if __name__ == '__main__':
    nested = [[1, 2], [], [3, 4, 5], [6]]
    print('Flattened sequence:')
    for item in LazyFlatten(nested):
        print(item, end=' ')
    print()

''' bfs_visualize.py
    Build a BFS tree from a directed graph (adjacency list) and export it
    as a Graphviz DOT file.  The script can be piped to `dot -Tpng` to see
    the picture.
''' 
import sys
from collections import deque, defaultdict

def load_adjlist(path):
    """Parse a file where each line is `node: neighbor1 neighbor2 ...`.
    Returns a dict mapping node strings to a list of neighbor strings.
    """
    adj = defaultdict(list)
    with open(path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            node, rest = line.split(':', 1)
            neighbours = rest.split()
            adj[node.strip()] = [n.strip() for n in neighbours]
    return dict(adj)

def bfs_tree(adj, start):
    """Return a dict *parent* where parent[child] = its BFS predecessor.
    The start node has parent None.  Nodes unreachable from *start* are omitted.
    """
    parent = {start: None}
    q = deque([start])
    while q:
        u = q.popleft()
        for v in adj.get(u, []):
            if v not in parent:
                parent[v] = u
                q.append(v)
    return parent

def to_dot(parent):
    """Convert the BFS parent map into a DOT representation string.
    The root node is drawn without an incoming edge.
    """
    lines = ['digraph BFS_Tree {', '    node [shape=circle];']
    for child, par in parent.items():
        if par is None:
            lines.append(f'    "{child}";')
        else:
            lines.append(f'    "{par}" -> "{child}";')
    lines.append('}')
    return '\n'.join(lines)

def main():
    if len(sys.argv) != 3:
        print('Usage: python bfs_visualize.py <adjlist_file> <start_node>')
        sys.exit(1)
    adj_file, start = sys.argv[1], sys.argv[2]
    adj = load_adjlist(adj_file)
    if start not in adj:
        print(f'Start node "{start}" not found in graph')
        sys.exit(1)
    parent = bfs_tree(adj, start)
    dot = to_dot(parent)
    print(dot)

if __name__ == '__main__':
    main()

