#
# Parses a '--range' argument formatted as 'start:end' and prints each integer
# from start to end inclusive. Demonstrates custom type conversion in argparse.

import argparse
import sys

def range_type(value: str):
    """Validate and convert a 'start:end' string into a tuple of ints.
    Raises argparse.ArgumentTypeError on malformed input.
    """
    parts = value.split(":")
    if len(parts) != 2:
        raise argparse.ArgumentTypeError("range must be in 'start:end' format")
    try:
        start = int(parts[0])
        end = int(parts[1])
    except ValueError:
        raise argparse.ArgumentTypeError("start and end must be integers")
    if start > end:
        raise argparse.ArgumentTypeError("start must not be greater than end")
    return start, end

def build_parser():
    parser = argparse.ArgumentParser(description="Print numbers in a given inclusive range.")
    parser.add_argument(
        "-r",
        "--range",
        type=range_type,
        required=True,
        help="Range in the form start:end, e.g., 5:10"
    )
    return parser

def main(argv=None):
    parser = build_parser()
    args = parser.parse_args(argv)
    start, end = args.range
    for i in range(start, end + 1):
        print(i)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        sys.exit(0)

"""subsequence_check.py

Utility that determines if *candidate* appears as a subsequence of *target*.
Usage: python subsequence_check.py <target> <candidate>
"""
import sys

def is_subsequence(target: str, candidate: str) -> bool:
    """Return True if *candidate* is a subsequence of *target*.

    The function walks through *target* once, advancing the index in *candidate*
    whenever the current characters match.
    """
    if not candidate:
        return True
    cand_idx = 0
    for ch in target:
        if ch == candidate[cand_idx]:
            cand_idx += 1
            if cand_idx == len(candidate):
                return True
    return False

def main(argv: list[str] | None = None) -> None:
    if argv is None:
        argv = sys.argv[1:]
    if len(argv) != 2:
        print("Usage: python subsequence_check.py <target> <candidate>")
        sys.exit(1)
    target, candidate = argv
    result = is_subsequence(target, candidate)
    print(f"'{candidate}' is{' ' if result else ' NOT '}a subsequence of '{target}'.")

if __name__ == "__main__":
    main()

import sys
from collections import deque

def parse_weighted_adjlist(path):
    """Parse a file where each line is ``src dest weight``.
    The function returns a dict mapping each source vertex to a list of
    destination vertices, discarding the weight token.
    """
    graph = {}
    with open(path, "r") as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) != 3:
                continue
            src, dst, _ = parts
            graph.setdefault(src, []).append(dst)
            # Ensure destination appears as a key (even if it has no outgoing edges)
            graph.setdefault(dst, [])
    return graph

def bfs_order(graph, start):
    visited = {start}
    q = deque([start])
    order = []
    while q:
        v = q.popleft()
        order.append(v)
        for nb in graph.get(v, []):
            if nb not in visited:
                visited.add(nb)
                q.append(nb)
    return order

def main():
    if len(sys.argv) != 2:
        print("Usage: python bfs_ignore_weights.py <adjlist_file>")
        sys.exit(1)
    g = parse_weighted_adjlist(sys.argv[1])
    if "0" not in g:
        print("Vertex '0' not present in graph.")
        sys.exit(1)
    print("BFS order:", " ".join(bfs_order(g, "0")))

if __name__ == "__main__":
    main()

"""fib_memo.py
A simple demonstration of memoization using a decorator to compute Fibonacci numbers.
The memoize decorator caches results in a dictionary keyed by the function's arguments.
Run the script to see the time taken for the 35th Fibonacci number with and without caching.
"""
import time
from functools import wraps

def memoize(func):
    """Cache results of *func* in a dict keyed by positional arguments.
    Only works for hashable arguments.
    """
    cache = {}
    @wraps(func)
    def wrapper(*args):
        if args in cache:
            return cache[args]
        result = func(*args)
        cache[args] = result
        return result
    return wrapper

@memoize
def fib(n):
    """Return the nth Fibonacci number using plain recursion.
    Thanks to @memoize this runs in linear time.
    """
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

def fib_no_cache(n):
    """Plain recursive Fibonacci without memoization (exponential)."""
    if n < 2:
        return n
    return fib_no_cache(n - 1) + fib_no_cache(n - 2)

if __name__ == "__main__":
    N = 35
    start = time.time()
    print(f"fib({N}) with cache = {fib(N)}")
    print(f"Time with cache: {time.time() - start:.6f}s")

    start = time.time()
    print(f"fib({N}) without cache = {fib_no_cache(N)}")
    print(f"Time without cache: {time.time() - start:.6f}s")

# ackermann_memo.py
# Demonstrates memoization of the extremely deep recursive Ackermann function.
# The function is memoized with an explicit dictionary to avoid redundant calls.

import sys
sys.setrecursionlimit(10000)

_cache = {}

def ack(m: int, n: int) -> int:
    """Return Ackermann's function A(m, n).
    Results are cached in the global `_cache` dict keyed by (m, n).
    """
    if (m, n) in _cache:
        return _cache[(m, n)]
    if m == 0:
        result = n + 1
    elif n == 0:
        result = ack(m - 1, 1)
    else:
        result = ack(m - 1, ack(m, n - 1))
    _cache[(m, n)] = result
    return result

if __name__ == "__main__":
    samples = [(0, 0), (1, 2), (2, 2), (3, 3)]
    for m, n in samples:
        try:
            print(f"Ackermann({m}, {n}) = {ack(m, n)}")
        except RecursionError:
            print(f"Ackermann({m}, {n}) caused a recursion depth error")

