import json
import sys
import heapq
from typing import Dict, List, Tuple, Any

def load_json_graph(path: str) -> Dict[Any, List[Tuple[Any, float]]]:
    """Load a graph from *path*.
    JSON structure must be:
    {
        "nodes": ["A", "B", ...],
        "edges": [
            {"src": "A", "dst": "B", "weight": 2.5},
            ...
        ]
    }
    Returns an adjacency dict mapping each node to a list of (neighbor, weight).
    """
    with open(path, "r") as f:
        data = json.load(f)
    graph: Dict[Any, List[Tuple[Any, float]]] = {n: [] for n in data["nodes"]}
    for e in data["edges"]:
        src, dst, w = e["src"], e["dst"], float(e["weight"])
        graph[src].append((dst, w))
    return graph

def dijkstra(graph: Dict[Any, List[Tuple[Any, float]]], source: Any) -> Tuple[Dict[Any, float], Dict[Any, Any]]:
    dist = {v: float('inf') for v in graph}
    prev = {v: None for v in graph}
    dist[source] = 0.0
    heap = [(0.0, source)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))
    return dist, prev

def reconstruct(prev: Dict[Any, Any], target: Any) -> List[Any]:
    path = []
    cur = target
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()
    return path

def cli():
    if len(sys.argv) != 4:
        print(f"Usage: {sys.argv[0]} <json_file> <source> <target>")
        sys.exit(1)
    json_file, src, tgt = sys.argv[1], sys.argv[2], sys.argv[3]
    graph = load_json_graph(json_file)
    if src not in graph or tgt not in graph:
        print("Source or target node not found in the graph.")
        sys.exit(1)
    dist, prev = dijkstra(graph, src)
    if dist[tgt] == float('inf'):
        print(f"No path from {src} to {tgt}.")
    else:
        path = reconstruct(prev, tgt)
        print(f"Shortest distance: {dist[tgt]:.2f}")
        print("Path: " + " -> ".join(map(str, path)))

if __name__ == "__main__":
    cli()

'''bst_basic.py
A simple implementation of a binary search tree (BST).
Provides insert, search, and inorder traversal, and a small demo.
'''

class BSTNode:
    """Node of a binary search tree.
    Attributes:
        key:   The value stored in the node.
        left:  Left child (BSTNode or None).
        right: Right child (BSTNode or None).
    """
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

    def insert(self, key):
        """Insert *key* into the subtree rooted at this node.
        Duplicates are ignored.
        """
        if key < self.key:
            if self.left:
                self.left.insert(key)
            else:
                self.left = BSTNode(key)
        elif key > self.key:
            if self.right:
                self.right.insert(key)
            else:
                self.right = BSTNode(key)
        # if key == self.key we do nothing (no duplicates)

    def search(self, key):
        """Return True if *key* exists in the subtree, else False."""
        if key == self.key:
            return True
        if key < self.key:
            return self.left.search(key) if self.left else False
        return self.right.search(key) if self.right else False

    def inorder(self):
        """Yield the keys of the subtree in sorted (inorder) order."""
        if self.left:
            yield from self.left.inorder()
        yield self.key
        if self.right:
            yield from self.right.inorder()


def demo():
    # Build a BST with some numbers
    values = [7, 3, 9, 1, 5, 8, 10]
    root = BSTNode(values[0])
    for v in values[1:]:
        root.insert(v)

    print('Inorder traversal:', list(root.inorder()))
    for q in [5, 2, 10, 11]:
        print(f'Search {q}:', root.search(q))

if __name__ == '__main__':
    demo()

'''avl_tree.py
AVL (Adelson-Velsky and Landis) balanced binary search tree implementation.
Provides insert, search, and a method to verify the AVL property.
'''

class AVLNode:
    """Node of an AVL tree.
    Stores a key, left/right children, and the node's height.
    """
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.height = 1

    def _update_height(self):
        left_h = self.left.height if self.left else 0
        right_h = self.right.height if self.right else 0
        self.height = max(left_h, right_h) + 1

    def _balance_factor(self):
        left_h = self.left.height if self.left else 0
        right_h = self.right.height if self.right else 0
        return left_h - right_h

    def _rotate_right(self):
        new_root = self.left
        self.left = new_root.right
        new_root.right = self
        self._update_height()
        new_root._update_height()
        return new_root

    def _rotate_left(self):
        new_root = self.right
        self.right = new_root.left
        new_root.left = self
        self._update_height()
        new_root._update_height()
        return new_root

    def insert(self, key):
        if key < self.key:
            if self.left:
                self.left = self.left.insert(key)
            else:
                self.left = AVLNode(key)
        elif key > self.key:
            if self.right:
                self.right = self.right.insert(key)
            else:
                self.right = AVLNode(key)
        # duplicate keys are ignored

        self._update_height()
        balance = self._balance_factor()

        # Left heavy
        if balance > 1:
            if key < self.left.key:
                return self._rotate_right()
            else:
                self.left = self.left._rotate_left()
                return self._rotate_right()
        # Right heavy
        if balance < -1:
            if key > self.right.key:
                return self._rotate_left()
            else:
                self.right = self.right._rotate_right()
                return self._rotate_left()
        return self

    def search(self, key):
        if key == self.key:
            return True
        if key < self.key:
            return self.left.search(key) if self.left else False
        return self.right.search(key) if self.right else False

    def is_balanced(self):
        """Return True if the subtree satisfies AVL balance constraints."""
        left_bal = self.left.is_balanced() if self.left else True
        right_bal = self.right.is_balanced() if self.right else True
        bf = self._balance_factor()
        return left_bal and right_bal and -1 <= bf <= 1


def demo():
    root = AVLNode(30)
    for v in [20, 40, 10, 25, 35, 50, 5, 15, 27]:
        root = root.insert(v)
    print('Search 27 ->', root.search(27))
    print('Search 99 ->', root.search(99))
    print('Tree balanced?', root.is_balanced())

if __name__ == '__main__':
    demo()

'''bst_file_io.py
Read integers from input.txt, build a BST, write sorted numbers to output.txt.
''' 

class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

    def insert(self, key):
        if key < self.key:
            if self.left:
                self.left.insert(key)
            else:
                self.left = Node(key)
        elif key > self.key:
            if self.right:
                self.right.insert(key)
            else:
                self.right = Node(key)
        # duplicates ignored

    def inorder(self):
        if self.left:
            for k in self.left.inorder():
                yield k
        yield self.key
        if self.right:
            for k in self.right.inorder():
                yield k

def build_bst(values):
    if not values:
        return None
    root = Node(values[0])
    for v in values[1:]:
        root.insert(v)
    return root

def read_numbers(path):
    with open(path, 'r') as f:
        return [int(x) for x in f.read().split()]

def write_numbers(path, numbers):
    with open(path, 'w') as f:
        f.write(' '.join(str(x) for x in numbers))

def main(input_file='input.txt', output_file='output.txt'):
    nums = read_numbers(input_file)
    tree = build_bst(nums)
    sorted_nums = list(tree.inorder()) if tree else []
    write_numbers(output_file, sorted_nums)
    print(f'Wrote {len(sorted_nums)} sorted numbers to {output_file}')

if __name__ == '__main__':
    main()

'''bst_visualize.py
Create a BST and produce a Graphviz DOT representation for visualization.
Requires the `graphviz` package (pip install graphviz).
'''

class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

    def insert(self, key):
        if key < self.key:
            if self.left:
                self.left.insert(key)
            else:
                self.left = Node(key)
        elif key > self.key:
            if self.right:
                self.right.insert(key)
            else:
                self.right = Node(key)
        # ignore duplicates

def _dot_node(node, lines, idx_counter):
    node_id = f'node{next(idx_counter)}'
    lines.append(f'    {node_id} [label="{node.key}"];')
    if node.left:
        left_id = _dot_node(node.left, lines, idx_counter)
        lines.append(f'    {node_id} -> {left_id};')
    if node.right:
        right_id = _dot_node(node.right, lines, idx_counter)
        lines.append(f'    {node_id} -> {right_id};')
    return node_id

def bst_to_dot(root):
    """Return a DOT language string representing *root* BST.
    The graph is directed and uses simple circles for nodes.
    """
    lines = ['digraph BST {', '    node [shape=circle];']
    if root:
        from itertools import count
        _dot_node(root, lines, count())
    lines.append('}')
    return '\n'.join(lines)

def demo():
    values = [50, 30, 70, 20, 40, 60, 80]
    root = Node(values[0])
    for v in values[1:]:
        root.insert(v)
    dot = bst_to_dot(root)
    print(dot)
