if __name__ == '__main__':
    demo()

'''bst_levelorder.py
Provides BSTNode with insert/search and a LevelOrderIterator that yields keys
in breadth‑first order.
''' 

from collections import deque

class BSTNode:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

    def insert(self, key):
        if key < self.key:
            if self.left:
                self.left.insert(key)
            else:
                self.left = BSTNode(key)
        elif key > self.key:
            if self.right:
                self.right.insert(key)
            else:
                self.right = BSTNode(key)
        # duplicates ignored

    def search(self, key):
        if key == self.key:
            return True
        if key < self.key:
            return self.left.search(key) if self.left else False
        return self.right.search(key) if self.right else False

class LevelOrderIterator:
    """Iterator that yields BST keys level by level.
    Usage: for value in LevelOrderIterator(root): ...
    """
    def __init__(self, root):
        self.queue = deque()
        if root:
            self.queue.append(root)

    def __iter__(self):
        return self

    def __next__(self):
        if not self.queue:
            raise StopIteration
        node = self.queue.popleft()
        if node.left:
            self.queue.append(node.left)
        if node.right:
            self.queue.append(node.right)
        return node.key

def demo():
    values = [15, 6, 23, 4, 7, 71, 5]
    root = BSTNode(values[0])
    for v in values[1:]:
        root.insert(v)
    print('Level order traversal:', list(LevelOrderIterator(root)))

if __name__ == '__main__':
    demo()

'''persistent_bst.py
Functional (immutable) binary search tree.
Each insert returns a new root while sharing unchanged sub‑trees.
''' 

class PNode:
    __slots__ = ('key', 'left', 'right')
    def __init__(self, key, left=None, right=None):
        self.key = key
        self.left = left
        self.right = right

    def insert(self, key):
        """Return a new tree with *key* inserted, leaving the current tree unchanged."""
        if key < self.key:
            new_left = self.left.insert(key) if self.left else PNode(key)
            return PNode(self.key, new_left, self.right)
        if key > self.key:
            new_right = self.right.insert(key) if self.right else PNode(key)
            return PNode(self.key, self.left, new_right)
        # key == self.key → return self (no duplicate)
        return self

    def search(self, key):
        if key == self.key:
            return True
        if key < self.key:
            return self.left.search(key) if self.left else False
        return self.right.search(key) if self.right else False

    def inorder(self):
        if self.left:
            yield from self.left.inorder()
        yield self.key
        if self.right:
            yield from self.right.inorder()

def empty_tree():
    return None

def insert(root, key):
    if root is None:
        return PNode(key)
    return root.insert(key)

def demo():
    t1 = insert(empty_tree(), 10)
    t2 = insert(t1, 5)
    t3 = insert(t2, 15)
    t4 = insert(t3, 12)
    print('t1 inorder:', list(t1.inorder()))
    print('t4 inorder:', list(t4.inorder()))
    print('t2 contains 15?', t2.search(15))
    print('t4 contains 12?', t4.search(12))

if __name__ == '__main__':
    demo()

'''trie_with_enumeration.py
A Trie that can enumerate all words that share a prefix.
'''

from typing import List

class Node:
    def __init__(self):
        self.children = {}
        self.is_word = False


class Trie:
    def __init__(self, words: List[str] = None):
        self.root = Node()
        if words:
            for w in words:
                self.insert(w)

    def insert(self, word: str) -> None:
        cur = self.root
        for ch in word:
            cur = cur.children.setdefault(ch, Node())
        cur.is_word = True

    def _collect(self, node: Node, prefix: str, out: List[str]) -> None:
        if node.is_word:
            out.append(prefix)
        for ch, child in node.children.items():
            self._collect(child, prefix + ch, out)

    def words_with_prefix(self, prefix: str) -> List[str]:
        """Return all words that start with *prefix*.
        If the prefix is not present, an empty list is returned.
        """
        cur = self.root
        for ch in prefix:
            if ch not in cur.children:
                return []
            cur = cur.children[ch]
        result: List[str] = []
        self._collect(cur, prefix, result)
        return result


if __name__ == '__main__':
    sample = ['cat', 'car', 'cart', 'dog', 'dove', 'door']
    trie = Trie(sample)
    print(trie.words_with_prefix('ca'))   # ['cat', 'car', 'cart']
    print(trie.words_with_prefix('do'))   # ['dog', 'dove', 'door']
    print(trie.words_with_prefix('z'))    # []

'''ci_trie_delete.py
Case‑insensitive Trie implementation with insert, search, starts_with and delete.
'''

from __future__ import annotations
from typing import Dict

class CINode:
    def __init__(self):
        self.children: Dict[str, CINode] = {}
        self.is_end: bool = False


class CaseInsensitiveTrie:
    def __init__(self):
        self.root = CINode()

    def _norm(self, s: str) -> str:
        """Normalize a string to lower‑case for case‑insensitive handling."""
        return s.lower()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in self._norm(word):
            node = node.children.setdefault(ch, CINode())
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self._find(self._norm(word))
        return bool(node) and node.is_end

    def starts_with(self, prefix: str) -> bool:
        return self._find(self._norm(prefix)) is not None

    def delete(self, word: str) -> bool:
        """Delete *word* from the trie.
        Returns True if the word existed and was removed, False otherwise.
        """
        def _delete(node: CINode, w: str, depth: int) -> bool:
            if depth == len(w):
                if not node.is_end:
                    return False  # word not present
                node.is_end = False
                return len(node.children) == 0  # prune if leaf
            ch = w[depth]
            child = node.children.get(ch)
            if child is None:
                return False  # word not present
            should_prune = _delete(child, w, depth + 1)
            if should_prune:
                del node.children[ch]
                return not node.is_end and len(node.children) == 0
            return False

        normalized = self._norm(word)
        return _delete(self.root, normalized, 0)

    def _find(self, key: str) -> CINode | None:
        node = self.root
        for ch in key:
            node = node.children.get(ch)
            if node is None:
                return None
        return node


if __name__ == '__main__':
    trie = CaseInsensitiveTrie()
    for w in ['Apple', 'app', 'Application']:
        trie.insert(w)
    print(trie.search('APP'))          # True
    print(trie.search('appl'))          # False
    print(trie.starts_with('appl'))     # True (Application)
    print(trie.delete('APP'))           # True (deletes 'app')
    print(trie.search('app'))           # False
    print(trie.delete('banana'))        # False

'''trie_autocomplete.py
Trie that stores word frequencies and provides k‑most‑frequent completions for a prefix.
'''

from typing import Dict, List, Tuple
import heapq

class AutoNode:
    def __init__(self):
        self.children: Dict[str, AutoNode] = {}
        self.freq: int = 0               # 0 means not a complete word


class AutocompleteTrie:
    def __init__(self):
        self.root = AutoNode()

    def insert(self, word: str, weight: int = 1) -> None:
        """Insert *word* with a given *weight* (frequency)."""
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, AutoNode())
        node.freq += weight

    def _collect(self, node: AutoNode, prefix: str, heap: List[Tuple[int, str]], k: int) -> None:
        if node.freq > 0:
            # Use negative frequency because heapq is a min‑heap
            heapq.heappush(heap, (-node.freq, prefix))
            if len(heap) > k:
                heapq.heappop(heap)
        for ch, child in node.children.items():
            self._collect(child, prefix + ch, heap, k)

    def top_k(self, prefix: str, k: int = 5) -> List[Tuple[str, int]]:
        """Return up to *k* words starting with *prefix*, ordered by descending frequency.
        Each element is a (word, frequency) tuple.
        """
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        heap: List[Tuple[int, str]] = []
        self._collect(node, prefix, heap, k)
        # Convert back to positive freq and sort descending
        results = [ (w, -f) for f, w in heap ]
        results.sort(key=lambda x: -x[1])
        return results


if __name__ == '__main__':
    trie = AutocompleteTrie()
    data = [ ('cat', 10), ('car', 7), ('cart', 3), ('dog', 5), ('dot', 2), ('dove', 4) ]
    for w, freq in data:
        trie.insert(w, freq)
    print(trie.top_k('ca', k=3))   # [('cat', 10), ('car', 7), ('cart', 3)]
    print(trie.top_k('do', k=2))   # [('dog', 5), ('dove', 4)]

'''radix_trie.py
A simple compressed (radix) trie implementation.
Each edge stores a string label rather than a single character.
'''

from typing import Dict, List

class RadixNode:
    def __init__(self, label: str = ''):
        self.label: str = label               # edge label from parent to this node
        self.children: Dict[str, RadixNode] = {}
        self.is_word: bool = False


class RadixTrie:
    def __init__(self):
        self.root = RadixNode()

    def insert(self, word: str) -> None:
        node = self.root
        i = 0
        while i < len(word):
            # Look for a child whose label shares a prefix with the remaining suffix
            for child_label, child in node.children.items():
                common = self._common_prefix(word[i:], child_label)
                if common:
                    if common == child_label:
                        # Edge fully matches, move deeper
                        i += len(common)
                        node = child
                        break
                    else:
                        # Split the edge
                        remaining = child_label[len(common):]
                        split_node = RadixNode(remaining)
                        split_node.children = child.children
                        split_node.is_word = child.is_word
                        # Re‑wire original child
                        child.label = common
                        child.children = {remaining[0]: split_node}
                        child.is_word = False
                        if i + len(common) == len(word):
                            child.is_word = True
                        else:
                            new_leaf = RadixNode(word[i+len(common):])
                            new_leaf.is_word = True
                            child.children[word[i+len(common)]] = new_leaf
                        return
            else:
                # No matching child, create leaf
                leaf = RadixNode(word[i:])
                leaf.is_word = True
                node.children[word[i]] = leaf
                return

    def _common_prefix(self, a: str, b: str) -> str:
        i = 0
        while i < min(len(a), len(b)) and a[i] == b[i]:
            i += 1
        return a[:i]

    def _collect(self, node: RadixNode, prefix: str, out: List[str]) -> None:
        if node.is_word:
            out.append(prefix)
        for child in node.children.values():
            self._collect(child, prefix + child.label, out)

    def all_words(self) -> List[str]:
        result: List[str] = []
        self._collect(self.root, '', result)
        return result


if __name__ == '__main__':
    rt = RadixTrie()
    for w in ['bear', 'bell', 'bid', 'bull', 'buy', 'sell', 'stock', 'stop']:
        rt.insert(w)
    print(sorted(rt.all_words()))

'''trie_visualizer.py
Generate Graphviz DOT representation of a Trie built from command‑line words.
Run: python trie_visualizer.py word1 word2 ... > trie.dot
Then: dot -Tpng trie.dot -o trie.png
'''

import sys
from typing import Dict, List

class VizNode:
    def __init__(self, id_: int):
        self.id = id_
        self.children: Dict[str, 'VizNode'] = {}
        self.is_end: bool = False


class TrieViz:
    def __init__(self):
        self.root = VizNode(0)
        self._next_id = 1
        self.lines: List[str] = []

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = VizNode(self._next_id)
                self._next_id += 1
            node = node.children[ch]
        node.is_end = True

    def _node_label(self, node: VizNode) -> str:
        return f'Node{node.id}'

    def _escape(self, s: str) -> str:
        return s.replace('"', '\"')

    def _dfs(self, node: VizNode, parent_label: str | None = None, edge_char: str | None = None) -> None:
        label = self._node_label(node)
        shape = 'doublecircle' if node.is_end else 'circle'
        self.lines.append(f'    {label} [shape={shape}];')
        if parent_label is not None:
            self.lines.append(f'    {parent_label} -> {label} [label="{self._escape(edge_char)}"];')
        for ch, child in node.children.items():
            self._dfs(child, label, ch)

    def to_dot(self) -> str:
        self.lines.append('digraph Trie {')
        self.lines.append('    node [fontname="Helvetica"];')
        self._dfs(self.root)
        self.lines.append('}')
        return '
'.join(self.lines)


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: python trie_visualizer.py word1 word2 ...', file=sys.stderr)
        sys.exit(1)
    words = sys.argv[1:]
    viz = TrieViz()
    for w in words:
        viz.insert(w)
    print(viz.to_dot())

"""mixed_sort.py

Shows how to sort a heterogeneous list containing integers and strings.
Numbers are placed before strings, and within each group the natural order
is applied (numeric ascending, string alphabetical).
"""

from typing import List, Any


def mixed_key(item: Any) -> tuple:
    """Return a tuple that orders numbers before strings.

    The first element is 0 for ints (so they sort earlier) and 1 for other
    types. The second element is the item itself, allowing normal ordering
    within each type category.
    """
    if isinstance(item, int):
        return (0, item)
    return (1, str(item))


def sort_mixed(values: List[Any]) -> List[Any]:
    """Return a new list sorted by the custom mixed_key."""
    return sorted(values, key=mixed_key)


if __name__ == "__main__":
    data = [5, "apple", 3, "banana", 12, "cherry", 1]
    print("Original:", data)
    print("Sorted:", sort_mixed(data))

'''dict_key_walker.py
Recursively walks arbitrarily nested dictionaries and prints each key path.
The recursion stops when a leaf value is not a dict (the base case).
'''

from typing import Any, List

def walk_keys(data: Any, path: List[str] = None) -> None:
    """Recursively print all key paths in a nested dictionary.

    Args:
        data: The current object; expected to be a dict or a leaf value.
        path: Accumulated list of keys leading to the current object.
    """
    if path is None:
        path = []
    # Base case: data is not a dict – nothing more to traverse.
    if not isinstance(data, dict):
        print('.'.join(path) + ' -> ' + repr(data))
        return
    # Recursive case: iterate over items and descend.
    if not data:
        # Empty dict – still a base case, just print the path.
        print('.'.join(path) + ' -> {}')
        return
    for key, value in data.items():
        walk_keys(value, path + [str(key)])

def main() -> None:
    """Demonstrates walk_keys on a sample nested structure."""
    sample = {
        'user': {
            'id': 42,
            'profile': {
                'name': 'Alice',
                'tags': []
            }
        },
        'settings': {
            'theme': 'dark',
            'notifications': {
                'email': True,
                'sms': False
            }
        }
    }
    walk_keys(sample)

if __name__ == '__main__':
    main()

'''fib_memo.py
Recursive Fibonacci with explicit base cases and memoization via a dictionary.
The base cases are F(0)=0 and F(1)=1. Subsequent values are cached to avoid exponential blow‑up.
'''

from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """Return the nth Fibonacci number using recursion with memoization.

    Base cases:
        n == 0 -> 0
        n == 1 -> 1
    Raises:
        ValueError if n is negative.
    """
    if n < 0:
        raise ValueError('Fibonacci is undefined for negative integers')
    if n == 0:
        return 0
    if n == 1:
        return 1
    return fib(n - 1) + fib(n - 2)

def main() -> None:
    import sys
    if len(sys.argv) != 2:
        print('Usage: python fib_memo.py <non‑negative integer>')
        sys.exit(1)
    try:
        num = int(sys.argv[1])
    except ValueError:
        print('Please provide an integer.')
        sys.exit(1)
    print(f'Fibonacci({num}) = {fib(num)}')

if __name__ == '__main__':
    main()

import sys
from collections import defaultdict, deque

def read_graph(path):
    """Read a DAG from *path*.
    The file must contain one edge per line as ``src dst`` separated by whitespace.
    Returns a dict mapping each node to a list of its outgoing neighbours.
    """
    graph = defaultdict(list)
    nodes = set()
    with open(path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            src, dst = line.split()
            graph[src].append(dst)
            nodes.update([src, dst])
    # Ensure all nodes appear in the dict even if they have no outgoing edges
    for n in nodes:
        graph.setdefault(n, [])
    return graph

def kahn_topological_sort(graph):
    """Return a list with a topological ordering using Kahn's algorithm.
    Raises ``ValueError`` if the graph contains a cycle.
    """
    # Compute in‑degree for each node
    indegree = {u: 0 for u in graph}
    for u in graph:
        for v in graph[u]:
            indegree[v] += 1
    # Queue of nodes with zero in‑degree
    queue = deque([u for u, d in indegree.items() if d == 0])
    order = []
    while queue:
        u = queue.popleft()
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
    if len(order) != len(graph):
        raise ValueError('Graph has at least one cycle')
    return order

def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        print('Usage: python toposort_file.py <path-to-graph>')
        return
    path = argv[0]
    try:
        g = read_graph(path)
        order = kahn_topological_sort(g)
        print('Topological order:', ' '.join(order))
    except Exception as e:
        print('Error:', e)

if __name__ == '__main__':
    main()

from collections import defaultdict, deque

def toposort(g):
    """Return a list with a topological ordering of *g* (dict of iterables).
    Raises ``ValueError`` if a cycle exists.
    """
    indeg = defaultdict(int)
    for u in g:
        indeg.setdefault(u, 0)
        for v in g[u]:
            indeg[v] += 1
    q = deque([n for n, d in indeg.items() if d == 0])
    order = []
    while q:
        n = q.popleft()
        order.append(n)
        for v in g.get(n, []):
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    if len(order) != len(indeg):
        raise ValueError('graph contains a cycle')
    return order

