"""Simple DAG container with built‑in topological sorting.

The class stores edges internally as an adjacency‑list dict.  The public
method ``add_edge`` validates that both vertices are hashable.  ``sort``
uses Kahn's algorithm and raises ``CycleError`` when the graph is not a DAG.
"""

from __future__ import annotations
from collections import defaultdict, deque
from typing import Dict, Iterable, List, Hashable

class CycleError(RuntimeError):
    """Exception raised when ``sort`` detects a directed cycle."""

class DAG:
    def __init__(self) -> None:
        self._adj: Dict[Hashable, List[Hashable]] = defaultdict(list)
        self._nodes: set[Hashable] = set()

    def add_edge(self, src: Hashable, dst: Hashable) -> None:
        """Add a directed edge *src → dst* to the graph.
        Duplicate edges are ignored.  Both vertices are stored even if they
        have no outgoing edges.
        """
        if dst not in self._adj[src]:
            self._adj[src].append(dst)
        self._nodes.update([src, dst])
        self._adj.setdefault(dst, [])

    def add_node(self, node: Hashable) -> None:
        """Ensure *node* exists in the graph without adding edges."""
        self._nodes.add(node)
        self._adj.setdefault(node, [])

    def sort(self) -> List[Hashable]:
        """Return a topological ordering of the DAG.
        Raises ``CycleError`` if the internal structure contains a cycle.
        """
        indegree: Dict[Hashable, int] = {n: 0 for n in self._nodes}
        for u in self._adj:
            for v in self._adj[u]:
                indegree[v] += 1
        q = deque([n for n, d in indegree.items() if d == 0])
        order: List[Hashable] = []
        while q:
            n = q.popleft()
            order.append(n)
            for v in self._adj[n]:
                indegree[v] -= 1
                if indegree[v] == 0:
                    q.append(v)
        if len(order) != len(self._nodes):
            raise CycleError('A cycle was found in the graph')
        return order

    def __repr__(self) -> str:
        return f'DAG(nodes={list(self._nodes)!r}, edges={dict(self._adj)!r})'

# Demo when executed directly
if __name__ == '__main__':
    dag = DAG()
    for e in [('a', 'b'), ('a', 'c'), ('b', 'd'), ('c', 'd')]:
        dag.add_edge(*e)
    print('Graph:', dag)
    print('Topological order:', dag.sort())

import json
import sys
from collections import deque
from typing import Dict, List

def load_dependencies(path: str) -> Dict[str, List[str]]:
    """Load a JSON file where keys are task IDs and values are lists of prerequisite IDs.
    Example file::
        {
            "build": ["compile", "test"],
            "compile": ["fetch"],
            "test": ["compile"],
            "fetch": []
        }
    """
    with open(path, 'r') as f:
        data = json.load(f)
    # Ensure every task appears as a key even if it only occurs as a prerequisite
    all_tasks = set(data.keys())
    for prereqs in data.values():
        all_tasks.update(prereqs)
    for t in all_tasks:
        data.setdefault(t, [])
    return data

def kahn_schedule(dep_graph: Dict[str, List[str]]) -> List[str]:
    """Return a feasible execution order using Kahn's algorithm.
    Raises ``ValueError`` when circular dependencies exist.
    """
    indegree = {t: 0 for t in dep_graph}
    for t, prereqs in dep_graph.items():
        for p in prereqs:
            indegree[t] += 1  # edge p -> t
    # Build reverse adjacency (prereq -> dependants) for fast updates
    rev_adj: Dict[str, List[str]] = {t: [] for t in dep_graph}
    for t, prereqs in dep_graph.items():
        for p in prereqs:
            rev_adj[p].append(t)
    q = deque([t for t, d in indegree.items() if d == 0])
    order = []
    while q:
        cur = q.popleft()
        order.append(cur)
        for nxt in rev_adj[cur]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                q.append(nxt)
    if len(order) != len(dep_graph):
        raise ValueError('Circular dependency detected')
    return order

def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        print('Usage: python schedule_from_json.py <path-to-json>')
        return
    path = argv[0]
    try:
        deps = load_dependencies(path)
        schedule = kahn_schedule(deps)
        print('Execution order:')
        for i, task in enumerate(schedule, 1):
            print(f'{i}. {task}')
    except Exception as e:
        print('Error:', e)

if __name__ == '__main__':
    main()

'''fib_memo.py

Compute the n‑th Fibonacci number using a top‑down dynamic programming approach
with memoization. The script can be run directly from the command line:

    python fib_memo.py 10

and will print the result.
'''
import sys
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """Return the n‑th Fibonacci number.

    The function uses Python's built‑in LRU cache to store previously
    computed values, turning the exponential recursion into linear time.
    """
    if n < 0:
        raise ValueError("n must be non‑negative")
    if n in (0, 1):
        return n
    return fib(n - 1) + fib(n - 2)

def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python fib_memo.py <non‑negative integer>")
        sys.exit(1)
    try:
        n = int(sys.argv[1])
    except ValueError:
        print("Argument must be an integer.")
        sys.exit(1)
    print(f"Fibonacci({n}) = {fib(n)}")

if __name__ == "__main__":
    main()

'''fib_methods.py

Provides three ways to compute Fibonacci numbers:

* fib_iter(n) – bottom‑up iteration (O(n) time, O(1) space)
* fib_matrix(n) – fast exponentiation of the 2×2 Fibonacci matrix (O(log n) time)
* fib_fast_doubling(n) – the fast‑doubling formula (O(log n) time)

The functions are pure and can be imported by other scripts.
'''
from __future__ import annotations

def fib_iter(n: int) -> int:
    """Iterative DP: compute Fibonacci numbers in linear time.

    Parameters
    ----------
    n: non‑negative integer
    Returns
    -------
    int – the n‑th Fibonacci number
    """
    if n < 0:
        raise ValueError("n must be non‑negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def _matrix_mult(A: tuple[tuple[int, int], tuple[int, int]],
                  B: tuple[tuple[int, int], tuple[int, int]]) -> tuple[tuple[int, int], tuple[int, int]]:
    return (
        (A[0][0] * B[0][0] + A[0][1] * B[1][0],
         A[0][0] * B[0][1] + A[0][1] * B[1][1]),
        (A[1][0] * B[0][0] + A[1][1] * B[1][0],
         A[1][0] * B[0][1] + A[1][1] * B[1][1])
    )

def _matrix_pow(M: tuple[tuple[int, int], tuple[int, int]], n: int) -> tuple[tuple[int, int], tuple[int, int]]:
    result = ((1, 0), (0, 1))  # identity matrix
    while n:
        if n & 1:
            result = _matrix_mult(result, M)
        M = _matrix_mult(M, M)
        n >>= 1
    return result

def fib_matrix(n: int) -> int:
    """Compute Fibonacci using matrix exponentiation (O(log n))."""
    if n < 0:
        raise ValueError("n must be non‑negative")
    if n == 0:
        return 0
    F = ((1, 1), (1, 0))
    M = _matrix_pow(F, n - 1)
    return M[0][0]

def fib_fast_doubling(n: int) -> int:
    """Fast‑doubling algorithm; returns F(n).

    The recursion works on the binary representation of n and runs in O(log n).
    """
    if n < 0:
        raise ValueError("n must be non‑negative")
    def _fib(k: int) -> tuple[int, int]:
        if k == 0:
            return (0, 1)
        a, b = _fib(k >> 1)
        c = a * ((b << 1) - a)
        d = a * a + b * b
        if k & 1:
            return (d, c + d)
        else:
            return (c, d)
    return _fib(n)[0]

