"""pair_collection.py

Shows a container class (PairCollection) whose __iter__ method returns an
instance of a dedicated iterator class (PairIterator). The iterator walks
through a list of (x, y) tuples and yields their Euclidean distance.
"""

import math

class PairIterator:
    """Iterator that computes the distance for each (x, y) pair.

    It expects the parent collection to supply a ._pairs attribute – a list
    of two‑element tuples.
    """

    def __init__(self, pairs):
        self._pairs = pairs
        self._index = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self._index >= len(self._pairs):
            raise StopIteration
        x, y = self._pairs[self._index]
        self._index += 1
        return math.hypot(x, y)

class PairCollection:
    """Stores a list of (x, y) coordinates and provides an iterable view.

    The __iter__ method creates a fresh PairIterator each time, ensuring
    independent traversals.
    """

    def __init__(self, pairs):
        self._pairs = list(pairs)

    def __iter__(self):
        return PairIterator(self._pairs)

# Simple demo when executed directly
if __name__ == "__main__":
    points = [(3, 4), (5, 12), (8, 15)]
    collection = PairCollection(points)
    print("Distances from origin:")
    for d in collection:
        print(f"{d:.2f}")
    # Second pass demonstrates iterator independence
    print("Second pass:")
    for d in collection:
        print(f"{d:.2f}")

"""gen_vs_iter.py

Comparison of two ways to make an object iterable:
1) a plain generator function (square_numbers_gen)
2) a class (SquareNumbers) whose __iter__ returns that generator.
Both produce the squares of numbers from 0 up to a limit.
"""

def square_numbers_gen(limit):
    """Yield squares from 0^2 up to (limit‑1)^2.
    """
    for i in range(limit):
        yield i * i

class SquareNumbers:
    """Container that stores a limit and uses the generator for iteration.

    The __iter__ method simply returns the generator created with the
    stored limit, so the class itself does not need to implement __next__.
    """

    def __init__(self, limit):
        if limit < 0:
            raise ValueError("limit must be non‑negative")
        self.limit = limit

    def __iter__(self):
        return square_numbers_gen(self.limit)

# Demonstration when run as a script
if __name__ == "__main__":
    print("Using generator directly:")
    for n in square_numbers_gen(6):
        print(n, end=" ")
    print("\nUsing SquareNumbers class:")
    for n in SquareNumbers(6):
        print(n, end=" ")
    print()

'''minheap_demo.py
Simple demonstration of a min‑heap using Python's built‑in heapq.
Provides three public helpers: push(item), pop_min() and peek().
'''import heapq

class MinHeap:
    """Wrapper around a list to expose a clean min‑heap API.

    The internal list ``_data`` is kept as a heap via ``heapq``.
    """
    def __init__(self, iterable=None):
        self._data = []
        if iterable:
            for item in iterable:
                heapq.heappush(self._data, item)

    def push(self, item):
        """Insert *item* into the heap.
        """
        heapq.heappush(self._data, item)

    def pop_min(self):
        """Remove and return the smallest element.
        Raises IndexError if the heap is empty.
        """
        if not self._data:
            raise IndexError('pop from empty heap')
        return heapq.heappop(self._data)

    def peek(self):
        """Return the smallest element without removing it.
        Returns None if the heap is empty.
        """
        return self._data[0] if self._data else None

    def __len__(self):
        return len(self._data)

    def __repr__(self):
        return f"MinHeap({self._data})"

# Example usage when run as a script
if __name__ == '__main__':
    heap = MinHeap([5, 1, 3])
    print('initial heap:', heap)
    heap.push(2)
    print('after push(2):', heap)
    print('peek ->', heap.peek())
    while len(heap):
        print('pop ->', heap.pop_min())

'''dijkstra_heap.py
Implementation of Dijkstra's shortest‑path algorithm for a directed
weighted graph using a binary min‑heap (heapq) as the priority queue.
The graph is represented as an adjacency‑list dictionary:
    {node: [(neighbor, weight), ...], ...}
'''import heapq
from typing import Dict, List, Tuple, Any

def dijkstra(graph: Dict[Any, List[Tuple[Any, float]]], source: Any) -> Dict[Any, float]:
    """Return the shortest‑path distances from *source* to all reachable nodes.

    ``graph`` maps a node to a list of ``(neighbor, weight)`` pairs.
    Edge weights must be non‑negative.
    """
    dist: Dict[Any, float] = {source: 0.0}
    visited: set = set()
    heap: List[Tuple[float, Any]] = [(0.0, source)]
    while heap:
        cur_dist, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        for v, w in graph.get(u, []):
            if w < 0:
                raise ValueError('negative edge weight not allowed')
            new_dist = cur_dist + w
            if v not in dist or new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(heap, (new_dist, v))
    return dist

if __name__ == '__main__':
    sample_graph = {
        'A': [('B', 1), ('C', 4)],
        'B': [('C', 2), ('D', 5)],
        'C': [('D', 1)],
        'D': []
    }
    source_node = 'A'
    distances = dijkstra(sample_graph, source_node)
    print('Shortest distances from', source_node)
    for node, d in distances.items():
        print(f'  {node}: {d}')

'''mergeable_minheap.py
A thin wrapper around a list that supports classic heap operations
and a ``merge`` method that combines another ``MinHeap`` instance in
O(n+m) time by concatenating the underlying lists and calling heapify.
'''import heapq

class MinHeap:
    """Encapsulates a binary min‑heap and allows merging with another heap.
    """
    def __init__(self, iterable=None):
        self._data = []
        if iterable:
            self._data = list(iterable)
            heapq.heapify(self._data)

    def push(self, item):
        heapq.heappush(self._data, item)

    def pop(self):
        if not self._data:
            raise IndexError('pop from empty heap')
        return heapq.heappop(self._data)

    def merge(self, other):
        """Merge *other* (another ``MinHeap``) into ``self``.
        The operation runs in linear time relative to the total size.
        """
        if not isinstance(other, MinHeap):
            raise TypeError('can only merge with another MinHeap')
        # Extend and re‑heapify; this is O(n+m)
        self._data.extend(other._data)
        heapq.heapify(self._data)
        # Empty the other heap to avoid accidental reuse
        other._data.clear()

    def __len__(self):
        return len(self._data)

    def __repr__(self):
        return f"MinHeap({self._data})"

if __name__ == '__main__':
    h1 = MinHeap([4, 1, 7])
    h2 = MinHeap([5, 2, 6])
    print('Before merge:', h1, h2)
    h1.merge(h2)
    print('After merge:', h1, 'other empty?', len(h2) == 0)
    while len(h1):
        print('pop ->', h1.pop())

