'''sort_selector.py
A tiny command‑line tool offering quicksort and mergesort.
Usage: python sort_selector.py quick|merge 3 1 4 2
The numbers after the algorithm name are sorted and printed.
''' 

import sys
from typing import List

# ---------- Quicksort ----------
def quicksort(arr: List[int]) -> List[int]:
    if len(arr) <= 1:
        return arr[:]
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + middle + quicksort(right)

# ---------- Mergesort ----------
def mergesort(arr: List[int]) -> List[int]:
    if len(arr) <= 1:
        return arr[:]
    mid = len(arr) // 2
    left = mergesort(arr[:mid])
    right = mergesort(arr[mid:])
    return _merge(left, right)

def _merge(left: List[int], right: List[int]) -> List[int]:
    merged: List[int] = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i]); i += 1
        else:
            merged.append(right[j]); j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged

def _parse_numbers(tokens: List[str]) -> List[int]:
    try:
        return [int(tok) for tok in tokens]
    except ValueError as e:
        sys.exit(f"Invalid number: {e}")

if __name__ == "__main__":
    if len(sys.argv) < 3:
        sys.exit('Usage: python sort_selector.py quick|merge num1 num2 ...')
    algo, *num_tokens = sys.argv[1:]
    numbers = _parse_numbers(num_tokens)
    if algo == 'quick':
        result = quicksort(numbers)
    elif algo == 'merge':
        result = mergesort(numbers)
    else:
        sys.exit('Algorithm must be "quick" or "merge"')
    print('Sorted:', ' '.join(map(str, result)))

