'''decorator_wrap.py
Defines a decorator that catches all exceptions and re‑raises them as WrappedError.
''' 
from functools import wraps

class WrappedError(Exception):
    """Exception raised by the catch_and_wrap decorator.
    The original exception is stored in *original*.
    """
    def __init__(self, original: Exception):
        self.original = original
        super().__init__(f'Wrapped {type(original).__name__}: {original}')

def catch_and_wrap(func):
    """Decorator that catches any exception from *func* and raises WrappedError.
    Preserves function metadata via @wraps.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as exc:
            raise WrappedError(exc) from exc
    return wrapper

# Example usage
@catch_and_wrap
def divide(a, b):
    return a / b

if __name__ == '__main__':
    try:
        print(divide(5, 0))
    except WrappedError as we:
        print('Caught WrappedError:', we)
        print('Original exception type:', type(we.original))

