'''merge_sort_with_tests.py
A reusable merge_sort implementation together with a small unittest suite.
The module can be imported or run directly to execute the tests.
''' 

from typing import List, Any
import unittest

def merge_sort(seq: List[Any]) -> List[Any]:
    """Return a new list containing the elements of *seq* in sorted order.
    The algorithm is a classic top‑down merge sort with O(n log n) time and O(n) extra space.
    """
    if len(seq) <= 1:
        return list(seq)  # make a shallow copy
    mid = len(seq) // 2
    left = merge_sort(seq[:mid])
    right = merge_sort(seq[mid:])
    return _merge(left, right)

def _merge(left: List[Any], right: List[Any]) -> List[Any]:
    merged: List[Any] = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged

# ---------------------------------------------------------------------------
# Unit tests
# ---------------------------------------------------------------------------
class TestMergeSort(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_sort([]), [])

    def test_single_element(self):
        self.assertEqual(merge_sort([5]), [5])

    def test_integers(self):
        data = [5, 2, 9, 1, 5, 6]
        self.assertEqual(merge_sort(data), sorted(data))

    def test_strings(self):
        data = ["pear", "apple", "orange"]
        self.assertEqual(merge_sort(data), sorted(data))

    def test_custom_objects(self):
        class Box:
            def __init__(self, weight):
                self.weight = weight
            def __le__(self, other):
                return self.weight <= other.weight
            def __repr__(self):
                return f"Box({self.weight})"
        boxes = [Box(3), Box(1), Box(2)]
        sorted_boxes = merge_sort(boxes)
        self.assertEqual([b.weight for b in sorted_boxes], [1, 2, 3])

if __name__ == "__main__":
    unittest.main()

# bitmap_vs_list.py
"""Compare a list of bools with a bitarray implementation.

The script creates a container representing N flags, randomly sets about
10% of them, and then measures:
* memory usage (sys.getsizeof + per‑element overhead)
* time to query 100 000 random indices.

The bitarray is implemented manually using Python's int as a bit store.
"""
import sys, random, time, argparse

class BitMap:
    """Simple bitmap using a single Python int.
    Supports set, get and length operations.
    """
    def __init__(self, size):
        self.size = size
        self._bits = 0

    def set(self, idx):
        if 0 <= idx < self.size:
            self._bits |= 1 << idx
        else:
            raise IndexError('index out of range')

    def get(self, idx):
        if 0 <= idx < self.size:
            return (self._bits >> idx) & 1 == 1
        raise IndexError('index out of range')

    def memory(self):
        # size of the int plus object overhead
        return sys.getsizeof(self._bits) + sys.getsizeof(self)

def build_bool_list(size, density=0.1):
    lst = [False] * size
    for i in range(size):
        if random.random() < density:
            lst[i] = True
    return lst

def build_bitmap(size, density=0.1):
    bm = BitMap(size)
    for i in range(size):
        if random.random() < density:
            bm.set(i)
    return bm

def time_queries(container, queries, getter):
    start = time.perf_counter()
    for q in queries:
        _ = getter(container, q)
    return time.perf_counter() - start

def list_get(container, idx):
    return container[idx]

def bitmap_get(container, idx):
    return container.get(idx)

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('n', nargs='?', type=int, default=1_000_000,
                        help='number of flags')
    args = parser.parse_args()

    bool_list = build_bool_list(args.n)
    bitmap = build_bitmap(args.n)
    queries = [random.randint(0, args.n - 1) for _ in range(100_000)]

    list_time = time_queries(bool_list, queries, list_get)
    bitmap_time = time_queries(bitmap, queries, bitmap_get)

    print(f"Number of flags: {args.n:,}")
    print(f"List memory   : {sys.getsizeof(bool_list):,} bytes (objects not counted)"
          f"\nBitmap memory : {bitmap.memory():,} bytes")
    print(f"List query time   : {list_time:.6f}s")
    print(f"Bitmap query time : {bitmap_time:.6f}s")

if __name__ == "__main__":
    main()

# shelve_cache_demo.py
"""Cache expensive computation results using an in‑memory dict or a shelve DB.

The demo defines ``expensive(x)`` which sleeps for 0.001 s and returns x².
Two wrappers are provided:
* MemCache – stores results in a normal dictionary (fast, uses RAM).
* ShelveCache – stores results in a persistent shelve file (slower, uses disk).
The script runs the same set of inputs through both caches and prints
timings and approximate disk size.
"""
import time, argparse, shelve, os, math

def expensive(x):
    """Simulated costly computation.
    The sleep creates a deterministic delay; the function then returns x².
    """
    time.sleep(0.001)
    return x * x

class MemCache:
    def __init__(self):
        self._store = {}
    def get(self, key):
        if key not in self._store:
            self._store[key] = expensive(key)
        return self._store[key]
    def size(self):
        return len(self._store)

class ShelveCache:
    def __init__(self, filename="cache.db"):
        self.filename = filename
        self._db = shelve.open(filename, writeback=False)
    def get(self, key):
        if str(key) not in self._db:
            self._db[str(key)] = expensive(key)
        return self._db[str(key)]
    def close(self):
        self._db.close()
    def size(self):
        return os.path.getsize(self.filename) if os.path.exists(self.filename) else 0

def benchmark(cache, inputs):
    start = time.perf_counter()
    for i in inputs:
        _ = cache.get(i)
    return time.perf_counter() - start

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('n', nargs='?', type=int, default=2000,
                        help='number of distinct inputs to cache')
    args = parser.parse_args()

    inputs = list(range(args.n))

    mem = MemCache()
    mem_time = benchmark(mem, inputs)

    shelve_cache = ShelveCache()
    shelve_time = benchmark(shelve_cache, inputs)
    shelve_cache.close()

    print(f"Inputs cached: {args.n}")
    print(f"In‑memory dict time : {mem_time:.4f}s, entries: {mem.size()}")
    print(f"Shelve DB time      : {shelve_time:.4f}s, file size: {shelve_cache.size():,} bytes")

if __name__ == "__main__":
    main()

