'''chained_hash_table.py
Implementation of a simple hash table using separate chaining.
Provides insertion, lookup, deletion and a basic display function.
''' 

class _Node:
    __slots__ = ('key', 'value', 'next')
    def __init__(self, key, value, nxt=None):
        self.key = key
        self.value = value
        self.next = nxt

class HashTable:
    """Hash table with fixed bucket count using linked‑list chaining."""
    def __init__(self, bucket_count=11):
        self._buckets = [None] * bucket_count
        self._size = 0
        self._bucket_count = bucket_count

    def _hash(self, key):
        return hash(key) % self._bucket_count

    def insert(self, key, value):
        idx = self._hash(key)
        head = self._buckets[idx]
        cur = head
        while cur:
            if cur.key == key:
                cur.value = value
                return
            cur = cur.next
        new_node = _Node(key, value, head)
        self._buckets[idx] = new_node
        self._size += 1

    def get(self, key, default=None):
        idx = self._hash(key)
        cur = self._buckets[idx]
        while cur:
            if cur.key == key:
                return cur.value
            cur = cur.next
        return default

    def delete(self, key):
        idx = self._hash(key)
        cur = self._buckets[idx]
        prev = None
        while cur:
            if cur.key == key:
                if prev:
                    prev.next = cur.next
                else:
                    self._buckets[idx] = cur.next
                self._size -= 1
                return True
            prev, cur = cur, cur.next
        return False

    def __len__(self):
        return self._size

    def display(self):
        for i, node in enumerate(self._buckets):
            chain = []
            while node:
                chain.append(f"{node.key}:{node.value}")
                node = node.next
