'''linear_probe_hash.py
Open addressing hash table using linear probing.
Supports insert, search, delete and automatic resizing.
''' 

_DELETED = object()

class LinearProbeHash:
    """Hash table with linear probing and automatic resize when load > 0.7."""
    def __init__(self, capacity=8):
        self._table = [None] * capacity
        self._size = 0
        self._capacity = capacity

    def _hash(self, key, i):
        return (hash(key) + i) % self._capacity

    def _probe(self, key):
        for i in range(self._capacity):
            idx = self._hash(key, i)
            slot = self._table[idx]
            if slot is None or slot is _DELETED or slot[0] == key:
                return idx, i
        raise RuntimeError('Hash table is full')

    def _should_resize(self):
        return self._size / self._capacity > 0.7

    def _resize(self):
        old = self._table
        self._capacity *= 2
        self._table = [None] * self._capacity
        self._size = 0
        for entry in old:
            if entry and entry is not _DELETED:
                self.insert(*entry)

    def insert(self, key, value):
        if self._should_resize():
            self._resize()
        idx, _ = self._probe(key)
        if self._table[idx] is None or self._table[idx] is _DELETED:
            self._size += 1
        self._table[idx] = (key, value)

    def search(self, key, default=None):
        for i in range(self._capacity):
            idx = self._hash(key, i)
            slot = self._table[idx]
            if slot is None:
                return default
            if slot is not _DELETED and slot[0] == key:
                return slot[1]
        return default

    def delete(self, key):
        for i in range(self._capacity):
            idx = self._hash(key, i)
            slot = self._table[idx]
            if slot is None:
                return False
            if slot is not _DELETED and slot[0] == key:
                self._table[idx] = _DELETED
                self._size -= 1
                return True
        return False

    def __len__(self):
        return self._size

    def __repr__(self):
        items = [f"{k}:{v}" for k, v in self._table if k is not None and k is not _DELETED]
        return f"LinearProbeHash({{{', '.join(items)}}})"

# Simple test suite
if __name__ == '__main__':
    h = LinearProbeHash()
    for i in range(15):
        h.insert(f'key{i}', i * 10)
    print('Table after inserts:', h)
    print('Search key7 ->', h.search('key7'))
    h.delete('key7')
    print('After deleting key7:', h)
    print('Search missing key7 ->', h.search('key7', 'not found'))

'''word_counter.py
Counts word occurrences in a text file using a custom open‑addressing hash table.
The table stores (word, count) pairs and resolves collisions by linear probing.
''' 

_DELETED = object()

class WordHashTable:
    def __init__(self, capacity=1024):
        self._table = [None] * capacity
        self._capacity = capacity
        self._size = 0

    def _hash(self, key, i):
        return (hash(key) + i) % self._capacity

    def _find_slot(self, key):
        for i in range(self._capacity):
            idx = self._hash(key, i)
            slot = self._table[idx]
            if slot is None or slot is _DELETED or slot[0] == key:
                return idx
        raise RuntimeError('Table full')

    def increment(self, word):
        idx = self._find_slot(word)
        slot = self._table[idx]
        if slot is None or slot is _DELETED:
            self._table[idx] = (word, 1)
            self._size += 1
        else:
            self._table[idx] = (word, slot[1] + 1)

    def items(self):
        for entry in self._table:
            if entry and entry is not _DELETED:
                yield entry

def count_words(file_path):
    ht = WordHashTable()
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            for w in line.split():
                clean = w.strip().lower().strip('.,!?:;"()')
                if clean:
                    ht.increment(clean)
