'''generic_hash.py
A generic hash table using open addressing with quadratic probing.
Includes insert, get, delete and a load_factor method.
''' 

_DELETED = object()

class GenericHashTable:
    def __init__(self, initial_capacity=16):
        self._capacity = initial_capacity
        self._table = [None] * self._capacity
        self._size = 0

    def _probe(self, key):
        h = hash(key)
        for i in range(self._capacity):
            idx = (h + i * i) % self._capacity  # quadratic probing
            slot = self._table[idx]
            if slot is None or slot is _DELETED or slot[0] == key:
                return idx
        raise RuntimeError('Table full')

    def insert(self, key, value):
        idx = self._probe(key)
        if self._table[idx] is None or self._table[idx] is _DELETED:
            self._size += 1
        self._table[idx] = (key, value)

    def get(self, key, default=None):
        idx = self._probe(key)
        slot = self._table[idx]
        if slot is None or slot is _DELETED:
            return default
        return slot[1]

    def delete(self, key):
        idx = self._probe(key)
        if self._table[idx] is None or self._table[idx] is _DELETED:
            return False
        self._table[idx] = _DELETED
        self._size -= 1
        return True

    def load_factor(self):
        return self._size / self._capacity

    def __repr__(self):
        pairs = [f"{k}:{v}" for k, v in self._table if k is not None and k is not _DELETED]
        return f"GenericHashTable({{{', '.join(pairs)}}})"

if __name__ == '__main__':
    ht = GenericHashTable()
    for i in range(10):
        ht.insert(f'key{i}', i * i)
    print('Current load factor:', ht.load_factor())
    print(ht)

