import itertools
import sys

def powerset(s: set) -> list[set]:
    """Return a list containing all subsets of *s* (the powerset).

    The subsets are generated in order of increasing size.
    """
    lst = list(s)
    result: list[set] = []
    for r in range(len(lst) + 1):
        for combo in itertools.combinations(lst, r):
            result.append(set(combo))
    return result

