'''gen_wrapper.py
Demonstrates wrapping a generator in a class that provides __iter__ and __next__.
The class delegates iteration to an internal generator.
'''

from typing import Generator, Iterable

def fibonacci(limit: int) -> Generator[int, None, None]:
    """Yield Fibonacci numbers up to *limit* (exclusive)."""
    a, b = 0, 1
    while a < limit:
        yield a
        a, b = b, a + b

class FibIter:
    """Iterator class that uses the fibonacci generator internally.

    The class conforms to the iterator protocol, making it usable in for‑loops
    and other contexts that expect an object with __iter__ and __next__.
    """

    def __init__(self, limit: int):
        self._limit = limit
        self._gen = fibonacci(limit)

    def __iter__(self) -> Iterable[int]:
        # Returning self makes the object an iterator.
        return self

    def __next__(self) -> int:
        # Delegates to the underlying generator.
        return next(self._gen)

# Simple demonstration when run as a script
if __name__ == "__main__":
    for n in FibIter(50):
        print(n)

'''prime_mixin.py
Reusable SequenceIteratorMixin that implements the iterator protocol for any subclass
holding a sequence in self._items. An example subclass PrimeUpTo uses the mixin to
produce prime numbers up to a given maximum.
'''

from typing import List, Iterable

class SequenceIteratorMixin:
    """Mixin that turns a container with a *_items* list into an iterator.

    Subclasses must populate ``self._items`` before iteration begins.
    The mixin provides ``__iter__`` and ``__next__`` so the subclass does not
    need to implement the protocol itself.
    """

    def __iter__(self) -> Iterable:
        self._index = 0
        return self

    def __next__(self):
        if self._index >= len(self._items):
            raise StopIteration
        value = self._items[self._index]
        self._index += 1
        return value

class PrimeUpTo(SequenceIteratorMixin):
    """Iterates over all prime numbers less than or equal to *max_value*.

    The prime list is built once during initialization; iteration is then
    handled by the mixin.
    """

    def __init__(self, max_value: int):
        if max_value < 2:
            self._items: List[int] = []
            return
        self._items = self._sieve(max_value)

    @staticmethod
    def _sieve(limit: int) -> List[int]:
        """Return a list of primes up to *limit* using the Sieve of Eratosthenes."""
        sieve = [True] * (limit + 1)
        sieve[0:2] = [False, False]
        for p in range(2, int(limit ** 0.5) + 1):
            if sieve[p]:
                for multiple in range(p * p, limit + 1, p):
                    sieve[multiple] = False
        return [i for i, prime in enumerate(sieve) if prime]

# Demo when executed directly
if __name__ == "__main__":
    for prime in PrimeUpTo(30):
        print(prime)

'''copy_benchmark.py
Benchmark shallow vs. deep copy for a list containing many dictionaries.
Run the script to see timing results printed to the console.
'''
import copy, time, random, string

def random_dict():
    """Return a dictionary with random string keys and integer values."""
    return {''.join(random.choices(string.ascii_lowercase, k=5)): random.randint(0, 1000)
            for _ in range(10)}

def build_data(size: int):
    """Create a list of *size* dictionaries, each containing a nested list.
    The nested list includes another dict to make the structure moderately deep.
    """
    return [{"id": i, "data": random_dict(), "extra": [random_dict() for _ in range(3)]}
            for i in range(size)]

def time_copy(func, obj, repeats=5):
    """Measure average time (seconds) to execute *func(obj)* over *repeats* runs."""
    total = 0.0
    for _ in range(repeats):
        start = time.perf_counter()
        func(obj)
        total += time.perf_counter() - start
    return total / repeats

def main():
    data = build_data(200_000)  # about a few hundred MB depending on system
    print('Data built – size:', len(data))

    shallow_time = time_copy(lambda x: copy.copy(x), data)
    deep_time = time_copy(lambda x: copy.deepcopy(x), data)

    print(f'Shallow copy average time: {shallow_time:.4f} seconds')
    print(f'Deep copy   average time: {deep_time:.4f} seconds')

if __name__ == '__main__':
    main()

