'''nqueens_one_solution.py
Simple backtracking solver for the N‑Queens problem.
It prints the first found solution as a list of column indices,
where index i corresponds to the row and the value is the column.
''' 
import sys

def solve_n_queens(n: int):
    """Return a list representing one valid placement of N queens.
    The list length is n; the i‑th element is the column (0‑based) of the queen
    placed in row i. If no solution exists, return None.
    """
    board = [-1] * n  # board[row] = col
    def is_safe(row: int, col: int) -> bool:
        for r in range(row):
            c = board[r]
            if c == col or abs(c - col) == row - r:
                return False
        return True
    def backtrack(row: int) -> bool:
        if row == n:
            return True
        for col in range(n):
            if is_safe(row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False
    return board if backtrack(0) else None

if __name__ == "__main__":
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 8
    solution = solve_n_queens(n)
    if solution:
        print(f"One solution for {n}-Queens: {solution}")
    else:
        print(f"No solution exists for {n} queens.")

'''nqueens_visualizer.py
Backtracking solver for N‑Queens that prints the board after every placement
and removal, making the algorithm's progress visible.
''' 
import time

def print_board(board):
    n = len(board)
    for r in range(n):
        line = ''
        for c in range(n):
            line += 'Q' if board[r] == c else '.'
        print(line)
    print('\n')

def visualize_n_queens(n: int, delay: float = 0.5):
    board = [-1] * n
    def safe(row, col):
        for r in range(row):
            c = board[r]
            if c == col or abs(c - col) == row - r:
                return False
        return True
    def backtrack(row):
        if row == n:
            print('Solution found:')
            print_board(board)
            return True
        for col in range(n):
            if safe(row, col):
                board[row] = col
                print(f'Place queen at ({row}, {col})')
                print_board(board)
                time.sleep(delay)
                if backtrack(row + 1):
                    return True
                print(f'Remove queen from ({row}, {col})')
                board[row] = -1
                print_board(board)
                time.sleep(delay)
        return False
    backtrack(0)

if __name__ == '__main__':
    visualize_n_queens(4, 0.3)

'''nqueens_generator.py
Provides n_queens_generator(n) which yields each solution lazily.
A solution is yielded as a tuple of column positions for rows 0..n-1.
''' 
from typing import Generator, Tuple, List

def n_queens_generator(n: int) -> Generator[Tuple[int, ...], None, None]:
    board: List[int] = [-1] * n
    def safe(row: int, col: int) -> bool:
        for r in range(row):
            c = board[r]
            if c == col or abs(c - col) == row - r:
                return False
        return True
    def backtrack(row: int):
        if row == n:
            yield tuple(board)
            return
        for col in range(n):
            if safe(row, col):
                board[row] = col
                yield from backtrack(row + 1)
                board[row] = -1
    return backtrack(0)

# Example usage
if __name__ == '__main__':
    for idx, sol in enumerate(n_queens_generator(5), 1):
        print(f"Solution {idx}: {sol}")

'''retry_decorator.py
Implements a @retry(attempts, delay=0) decorator.
The decorator re‑executes the wrapped function up to *attempts* times
if it raises an exception, waiting *delay* seconds between tries.
''' 
import time
import functools


def retry(attempts: int, delay: float = 0.0):
    """Return a decorator that retries the wrapped function.

    *attempts* – maximum number of executions (original call counts as the first).
    *delay* – seconds to wait between attempts; defaults to no pause.
    """
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exc = None
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:  # pylint: disable=broad-except
                    last_exc = exc
                    if attempt < attempts:
                        if delay:
                            time.sleep(delay)
                    else:
                        raise
        return wrapper
    return decorator


# Example usage ----------------------------------------------------------
@retry(attempts=3, delay=1)
def unstable_divide(a, b):
    """Divide *a* by *b* but randomly raise ZeroDivisionError for demo purposes."""
    import random
    if random.random() < 0.5:
        raise ZeroDivisionError("simulated division by zero")
    return a / b


if __name__ == "__main__":
    try:
        print("Result:", unstable_divide(10, 2))
    except ZeroDivisionError as e:
        print("All attempts failed:", e)

'''validate_signature.py
A decorator that validates arguments against simple type hints.
It inspects the wrapped function's signature and raises TypeError when a value
doesn't match the annotated type. The decorator keeps the original signature
visible to introspection tools.
''' 
import functools
import inspect
from typing import get_origin, get_args


def validate_types(func):
    """Decorator that checks arguments against *func*'s type annotations.

    Only basic built‑in types and Union are supported; missing annotations are ignored.
    """
    sig = inspect.signature(func)

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()
        for name, value in bound.arguments.items():
            if name in func.__annotations__:
                expected = func.__annotations__[name]
                # Resolve Union[...] if present
                if get_origin(expected) is Union:
                    allowed = get_args(expected)
                    if not isinstance(value, allowed):
                        raise TypeError(f"Argument '{name}' must be one of {allowed}, got {type(value)}")
                else:
                    if not isinstance(value, expected):
                        raise TypeError(f"Argument '{name}' must be {expected}, got {type(value)}")
        return func(*args, **kwargs)
    return wrapper


# Example usage ----------------------------------------------------------
@validate_types
def greet(name: str, times: int = 1) -> str:
    """Return a greeting repeated *times*.
    """
    return "Hello, " + name + "! " * times


if __name__ == "__main__":
    print(greet("Alice", times=2))
    try:
        greet("Bob", times="three")
    except TypeError as e:
        print("Validation error:", e)

'''command_registry.py
Implements a @command(name) decorator that stores the wrapped function
in a global COMMANDS dict under the provided name. The script also
includes a simple command‑line dispatcher.
