import sys
from typing import Callable, Dict

# Global registry mapping command names to callables
COMMANDS: Dict[str, Callable[[list], None]] = {}


def command(name: str):
    """Decorator that registers *func* under *name* in COMMANDS.

    The wrapped function must accept a list of strings (the arguments after the command).
    """
    def decorator(func: Callable[[list], None]):
        COMMANDS[name] = func
        return func
    return decorator


@command('hello')
def say_hello(args: list):
