    if not argv:
        print('Available commands:', ', '.join(sorted(COMMANDS)))
        return
    cmd, *cmd_args = argv
    func = COMMANDS.get(cmd)
    if func is None:
        print(f'Unknown command: {cmd}')
        print('Available commands:', ', '.join(sorted(COMMANDS)))
        return
    func(cmd_args)


