A simple @count_calls decorator that maintains a per‑function call counter.
The counter is stored as an attribute `call_count` on the wrapper, making it
accessible from outside the function.
''' 
import functools


def count_calls(func):
    """Decorator that increments and prints a call counter each time *func* runs.

    The wrapper gets an attribute `call_count` that starts at 0.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.call_count += 1
        print(f"{func.__name__} called {wrapper.call_count} time(s)")
        return func(*args, **kwargs)
    wrapper.call_count = 0
    return wrapper


