'''copy_default_decorator.py
Provides @copy_defaults which deep‑copies mutable default arguments before the wrapped
function executes, eliminating accidental shared state.
''' 
import copy
import inspect
from functools import wraps

def copy_defaults(func):
    """Decorator that deep‑copies mutable default arguments.
    For each parameter that has a default value and is mutable (list, dict, set,
    or any object where copy.deepcopy works), a fresh copy is supplied on every call.
    """
    sig = inspect.signature(func)
    mutable_defaults = {
        name: default
        for name, param in sig.parameters.items()
        if param.default is not param.empty and isinstance(param.default, (list, dict, set))
    }

    @wraps(func)
    def wrapper(*args, **kwargs):
        bound = sig.bind_partial(*args, **kwargs)
        for name, default in mutable_defaults.items():
            if name not in bound.arguments:
                bound.arguments[name] = copy.deepcopy(default)
        return func(*bound.args, **bound.kwargs)
    return wrapper

@copy_defaults
def accumulate(item, log=[]):
    """Append *item* to *log* and return the log.
    Without the decorator this would share *log* across calls.
    """
    log.append(item)
    return log

@copy_defaults
def merge_mapping(key, value, mapping={'a': 1}):
    """Add *key*: *value* to *mapping* and return it.
    The decorator ensures a fresh copy of the default dict each call.
    """
    mapping[key] = value
    return mapping

if __name__ == "__main__":
    print('accumulate calls:')
    print(accumulate(1))  # [1]
    print(accumulate(2))  # [2]
    print('merge_mapping calls:')
    print(merge_mapping('b', 2))  # {'a': 1, 'b': 2}
    print(merge_mapping('c', 3))  # {'a': 1, 'c': 3}

