import os
import sys
from collections import Counter, defaultdict

def collect_sizes(root_path):
    """Walk *root_path* and return a list of (size, full_path) tuples for regular files."""
    sizes = []
    for dirpath, _, filenames in os.walk(root_path):
        for name in filenames:
            full = os.path.join(dirpath, name)
            try:
                if os.path.islink(full) or not os.path.isfile(full):
                    continue
                size = os.path.getsize(full)
                sizes.append((size, full))
            except OSError:
                # Skip files we cannot access
                continue
    return sizes

def group_by_size(size_path_list):
    """Return a dict mapping size to a list of file paths that have that size.

    Only sizes that occur more than once are kept.
    """
    counter = Counter(size for size, _ in size_path_list)
    dup_sizes = {size for size, cnt in counter.items() if cnt > 1}
    groups = defaultdict(list)
    for size, path in size_path_list:
        if size in dup_sizes:
            groups[size].append(path)
    return groups

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <directory>")
        sys.exit(1)
    root = sys.argv[1]
    size_paths = collect_sizes(root)
    dup_groups = group_by_size(size_paths)
    if not dup_groups:
        print("No duplicate file sizes found.")
        return
    for size in sorted(dup_groups):
        print(f"Size {size} bytes:")
        for path in dup_groups[size]:
            print(f"  {path}")
        print()

if __name__ == "__main__":
    main()

from collections import deque

class TaskScheduler:
    """A FIFO scheduler that holds at most *capacity* tasks.

    When the queue is full, adding a new task automatically discards the
    oldest one (the leftmost element).
    """
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._queue = deque(maxlen=capacity)

    def add_task(self, task: str) -> None:
        """Append *task* to the scheduler, discarding the oldest if needed."""
        self._queue.append(task)

    def next_task(self) -> str:
        """Pop and return the next task (FIFO order). Raises IndexError if empty."""
        return self._queue.popleft()

    def __len__(self) -> int:
        return len(self._queue)

    def __repr__(self) -> str:
        return f"TaskScheduler(capacity={self._queue.maxlen}, tasks={list(self._queue)})"

def demo():
    scheduler = TaskScheduler(capacity=3)
    for i in range(5):
        scheduler.add_task(f"task-{i}")
        print(scheduler)
    print("--- processing tasks ---")
    while len(scheduler):
        print("Running", scheduler.next_task())

if __name__ == "__main__":
    demo()

