import pathlib
import sys
import hashlib
from collections import defaultdict

CHUNK_SIZE = 65536

def file_hash(path: pathlib.Path) -> str:
    """Return a SHA256 hex digest for *path* reading it in chunks."""
    hasher = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(CHUNK_SIZE), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def find_duplicates(root: pathlib.Path) -> dict[str, list[pathlib.Path]]:
    """Return a mapping from hash to list of files that share that hash.

    Only groups with two or more entries are kept.
    """
    size_dict: defaultdict[int, list[pathlib.Path]] = defaultdict(list)
    for p in root.rglob('*'):
        if p.is_file():
            size_dict[p.stat().st_size].append(p)
    duplicates: dict[str, list[pathlib.Path]] = {}
    for size, files in size_dict.items():
        if len(files) < 2:
            continue
        hash_map: dict[str, list[pathlib.Path]] = defaultdict(list)
        for f in files:
            h = file_hash(f)
            hash_map[h].append(f)
        for h, group in hash_map.items():
            if len(group) > 1:
                duplicates[h] = group
    return duplicates

def write_report(dup_map: dict[str, list[pathlib.Path]], report_path: pathlib.Path) -> None:
    """Write a human‑readable report of duplicates to *report_path*."""
    with report_path.open('w', encoding='utf-8') as fh:
        for h, files in dup_map.items():
            fh.write(f'Hash: {h}\n')
            for f in files:
                fh.write(f'  {f.resolve()}\n')
            fh.write('\n')

if __name__ == '__main__':
    target = pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else pathlib.Path.cwd()
    if not target.is_dir():
        sys.exit('Target must be a directory')
    dupes = find_duplicates(target)
    if not dupes:
        print('No duplicate files found.')
        sys.exit()
    report_file = pathlib.Path('duplicate_report.txt')
    write_report(dupes, report_file)
    print(f'Report written to {report_file.resolve()}')

