def factorial(n):
    """Return n! (n factorial) using recursion.

    Parameters
    ----------
    n : int
        Non‑negative integer.
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non‑negative")
    if n == 0:
        return 1
    return n * factorial(n - 1)

