'''retry_decorator.py
Provides a @retry decorator that can be configured with max_attempts and delay.
''' 
import functools
import time
import random


def retry(max_attempts: int = 3, delay: float = 0.5, caught_exceptions: tuple = (Exception,)):
    """Return a decorator that retries the wrapped function.

    Parameters
    ----------
    max_attempts: maximum number of attempts (including the first call).
    delay: seconds to wait between attempts.
    caught_exceptions: tuple of exception classes that trigger a retry.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while True:
                try:
                    return func(*args, **kwargs)
                except caught_exceptions as exc:
                    attempts += 1
                    if attempts >= max_attempts:
                        raise
                    print(f'Retrying {func.__name__} (attempt {attempts}/{max_attempts}) after {delay}s because: {exc}')
                    time.sleep(delay)
        return wrapper
    return decorator


@retry(max_attempts=5, delay=1)
def flaky_operation():
    """Simulate an operation that fails randomly.
    """
    if random.random() < 0.7:
        raise ValueError('Random failure')
    return 'Success!'


def main():
    try:
        result = flaky_operation()
        print('Result:', result)
    except Exception as e:
        print('Operation failed after retries:', e)


if __name__ == '__main__':
    main()

