import functools
import inspect


def preserve_signature(decorator):
    """Helper that makes *decorator* copy the wrapped function's signature.
    It returns a new decorator that applies ``functools.update_wrapper`` with
    ``wrapped.__signature__``.
    """
    @functools.wraps(decorator)
    def wrapper(func):
        @functools.wraps(func)
        def inner(*args, **kwargs):
            return decorator(func)(*args, **kwargs)
        # Attach the original signature so tools like inspect.signature see it
        inner.__signature__ = inspect.signature(func)
        return inner
    return wrapper


@preserve_signature
def times_two(func):
    """Simple decorator that multiplies a numeric return value by 2."""
    @functools.wraps(func)
    def inner(*a, **kw):
        return func(*a, **kw) * 2
    return inner


@times_two
def add(a: int, b: int) -> int:
    """Return the sum of *a* and *b*.
    The decorator will double the result.
    """
    return a + b


def main():
    print('add(3,4) =', add(3, 4))
    sig = inspect.signature(add)
    print('Signature of add after decoration:', sig)
    print('Parameter names:', list(sig.parameters))


if __name__ == '__main__':
    main()

'''command_registry.py
Implements a @command decorator that registers a callable in a global COMMANDS dict.
The script can be invoked with a command name to run the associated function.
''' 
import sys
from typing import Callable, Dict

# Global registry mapping command names to callables
COMMANDS: Dict[str, Callable[[list], None]] = {}


def command(name: str):
    """Decorator that registers *func* under *name* in the COMMANDS dict.
    The wrapped function must accept a list of string arguments.
    """
    def decorator(func: Callable[[list], None]):
        COMMANDS[name] = func
        return func
    return decorator


@command('greet')
def cmd_greet(argv: list):
    """Print a greeting. Usage: greet <name>"""
    if not argv:
        print('Usage: greet <name>')
        return
    print(f'Hello, {argv[0]}!')


@command('add')
def cmd_add(argv: list):
    """Add integer arguments. Usage: add <int1> <int2> ..."""
    try:
        numbers = [int(x) for x in argv]
    except ValueError:
        print('All arguments must be integers')
        return
    print('Sum =', sum(numbers))


def usage():
    print('Available commands:')
    for name in sorted(COMMANDS):
        print('  ', name)
    print('Usage: python command_registry.py <command> [args...]')


def main():
    if len(sys.argv) < 2:
        usage()
        return
    cmd_name, *args = sys.argv[1:]
    cmd = COMMANDS.get(cmd_name)
    if cmd is None:
        print(f'Unknown command: {cmd_name}\n')
        usage()
        return
    cmd(args)


if __name__ == '__main__':
    main()

