'''list_stack.py
A minimal stack implementation using Python's built‑in list.
Provides push, pop, peek and size methods with error handling.
'''

class ListStack:
    """Stack backed by a Python list (LIFO)."""

    def __init__(self) -> None:
        self._data: list = []

    def push(self, item) -> None:
        """Add *item* on top of the stack."""
        self._data.append(item)

    def pop(self):
        """Remove and return the top element. Raises IndexError if empty."""
        if not self._data:
            raise IndexError('pop from empty stack')
        return self._data.pop()

    def peek(self):
        """Return the top element without removing it. Returns None when empty."""
        return self._data[-1] if self._data else None

    def size(self) -> int:
        """Current number of elements in the stack."""
        return len(self._data)

    def is_empty(self) -> bool:
        """True if the stack has no elements."""
        return not self._data

if __name__ == '__main__':
    s = ListStack()
    for i in range(3):
        s.push(i)
        print(f'pushed {i}, size={s.size()}, peek={s.peek()}')
    while not s.is_empty():
        print('popped', s.pop())

'''deque_queue.py
A FIFO queue built on collections.deque.
Supports enqueue, dequeue, front, size and emptiness checks.
'''

from collections import deque
from typing import Any

class DequeQueue:
    """Queue using deque for O(1) enqueue and dequeue."""

    def __init__(self) -> None:
        self._queue: deque = deque()

    def enqueue(self, item: Any) -> None:
        """Add *item* to the rear of the queue."""
        self._queue.append(item)

    def dequeue(self) -> Any:
        """Remove and return the front element; raises IndexError if empty."""
        if not self._queue:
            raise IndexError('dequeue from empty queue')
        return self._queue.popleft()

    def front(self) -> Any:
        """Return the element at the front without removing it; None if empty."""
        return self._queue[0] if self._queue else None

    def size(self) -> int:
        """Number of items currently stored."""
        return len(self._queue)

    def is_empty(self) -> bool:
        return not self._queue

if __name__ == '__main__':
    q = DequeQueue()
    for ch in 'ABC':
        q.enqueue(ch)
        print(f'enqueued {ch}, size={q.size()}, front={q.front()}')
    while not q.is_empty():
        print('dequeued', q.dequeue())

'''linked_structs.py
Linked‑list based Stack and Queue.
Both structures share a simple Node class and expose typical methods.
'''

from __future__ import annotations
from typing import Any, Optional

class Node:
    __slots__ = ('value', 'next')
    def __init__(self, value: Any, nxt: Optional['Node'] = None) -> None:
        self.value = value
        self.next = nxt

class LinkedStack:
    """LIFO stack where push adds to the head of the list."""
    def __init__(self) -> None:
        self._head: Optional[Node] = None
        self._count = 0

    def push(self, item: Any) -> None:
        self._head = Node(item, self._head)
        self._count += 1

    def pop(self) -> Any:
        if not self._head:
            raise IndexError('pop from empty stack')
        node = self._head
        self._head = node.next
        self._count -= 1
        return node.value

    def peek(self) -> Any:
        return self._head.value if self._head else None

    def size(self) -> int:
        return self._count

    def is_empty(self) -> bool:
        return self._head is None

class LinkedQueue:
    """FIFO queue where enqueue adds to tail and dequeue removes from head."""
    def __init__(self) -> None:
        self._head: Optional[Node] = None
        self._tail: Optional[Node] = None
        self._count = 0

    def enqueue(self, item: Any) -> None:
        new_node = Node(item)
        if self._tail:
            self._tail.next = new_node
        self._tail = new_node
        if not self._head:
            self._head = new_node
        self._count += 1

    def dequeue(self) -> Any:
        if not self._head:
            raise IndexError('dequeue from empty queue')
        node = self._head
        self._head = node.next
        if self._head is None:
            self._tail = None
        self._count -= 1
        return node.value

    def front(self) -> Any:
        return self._head.value if self._head else None

    def size(self) -> int:
        return self._count

    def is_empty(self) -> bool:
        return self._head is None

if __name__ == '__main__':
    s = LinkedStack()
    for n in range(1, 4):
        s.push(n)
        print('stack push', n, 'size', s.size())
    while not s.is_empty():
        print('stack pop', s.pop())
    q = LinkedQueue()
    for ch in 'xyz':
        q.enqueue(ch)
        print('queue enqueue', ch, 'size', q.size())
    while not q.is_empty():
        print('queue dequeue', q.dequeue())

'''heap_priority_queue.py
A thin wrapper around heapq to provide a min‑priority queue.
Supports push(item, priority), pop(), peek() and size.
'''

import heapq
from typing import Any, List, Tuple

class PriorityQueue:
    """Min‑heap based priority queue where lower numbers mean higher priority."""

    def __init__(self) -> None:
        self._heap: List[Tuple[int, int, Any]] = []
        self._counter = 0  # tie‑breaker for equal priorities

    def push(self, item: Any, priority: int) -> None:
        """Insert *item* with given *priority* (lower = earlier)."""
        heapq.heappush(self._heap, (priority, self._counter, item))
        self._counter += 1

    def pop(self) -> Any:
        """Remove and return the highest‑priority item; raises IndexError if empty."""
        if not self._heap:
            raise IndexError('pop from empty priority queue')
        _, _, item = heapq.heappop(self._heap)
        return item

    def peek(self) -> Any:
        """Return the highest‑priority item without removing it; None if empty."""
        return self._heap[0][2] if self._heap else None

    def size(self) -> int:
        return len(self._heap)

    def is_empty(self) -> bool:
        return not self._heap

if __name__ == '__main__':
    pq = PriorityQueue()
    tasks = [('write report', 2), ('fix bug', 1), ('email team', 3)]
    for t, p in tasks:
        pq.push(t, p)
        print(f'push {t!r} priority={p}, size={pq.size()}, peek={pq.peek()!r}')
    while not pq.is_empty():
        print('pop', pq.pop())

'''generic_structs_benchmark.py
Generic Stack and Queue with type hints.
At the bottom a tiny benchmark using time.perf_counter.
'''

from __future__ import annotations
from typing import Generic, TypeVar, List
import time

T = TypeVar('T')

class Stack(Generic[T]):
    """LIFO container using a Python list."""
    def __init__(self) -> None:
        self._items: List[T] = []

    def push(self, item: T) -> None:
        self._items.append(item)

    def pop(self) -> T:
        if not self._items:
            raise IndexError('pop from empty stack')
        return self._items.pop()

    def size(self) -> int:
        return len(self._items)

class Queue(Generic[T]):
    """FIFO container using two lists for amortized O(1) ops."""
    def __init__(self) -> None:
        self._in: List[T] = []   # enqueue side
        self._out: List[T] = []  # dequeue side

    def enqueue(self, item: T) -> None:
        self._in.append(item)

    def _transfer(self) -> None:
        if not self._out:
            self._out = self._in[::-1]
            self._in.clear()

    def dequeue(self) -> T:
        self._transfer()
        if not self._out:
            raise IndexError('dequeue from empty queue')
        return self._out.pop()

    def size(self) -> int:
        return len(self._in) + len(self._out)

def _benchmark() -> None:
    N = 100_000
    s = Stack[int]()
    start = time.perf_counter()
    for i in range(N):
        s.push(i)
    for _ in range(N):
        s.pop()
    stack_time = time.perf_counter() - start

    q = Queue[int]()
    start = time.perf_counter()
    for i in range(N):
        q.enqueue(i)
    for _ in range(N):
        q.dequeue()
    queue_time = time.perf_counter() - start

    print(f'Stack push/pop {N} ops: {stack_time:.4f}s')
    print(f'Queue enqueue/dequeue {N} ops: {queue_time:.4f}s')

if __name__ == '__main__':
    _benchmark()

