'''txt_finder.py
Recursively walk a directory tree and list all *.txt* files.
The recursion stops when a directory contains no sub‑directories – the base case.
'''

import os
from typing import List

def find_txt_files(root: str) -> List[str]:
    """Return a list of absolute paths to *.txt* files under *root*.

    Base case: if *root* has no entries (empty directory), the function
    returns an empty list. Otherwise it iterates over entries, recurses into
    sub‑directories, and collects matching files.
    """
    if not os.path.isdir(root):
        raise NotADirectoryError(f'{root} is not a directory')

    entries = os.listdir(root)
    if not entries:
        return []  # Base case – empty directory

    txt_paths: List[str] = []
    for entry in entries:
        path = os.path.join(root, entry)
        if os.path.isdir(path):
            txt_paths.extend(find_txt_files(path))  # Recurse into sub‑dir
        elif path.lower().endswith('.txt'):
            txt_paths.append(os.path.abspath(path))
    return txt_paths

def main() -> None:
    start = input('Directory to search: ').strip() or '.'
    try:
        files = find_txt_files(start)
        print(f'Found {len(files)} *.txt* file(s):')
        for f in files:
            print(f)
    except Exception as exc:
        print(f'Error: {exc}')

if __name__ == '__main__':
    main()

'''binary_search_recursive.py
Recursive binary search implementation with clear base cases.
The function returns the index of *target* in a sorted list or -1 if not found.
'''

from typing import List, Any

def binary_search(arr: List[Any], target: Any, low: int = 0, high: int = None) -> int:
    """Recursively search *arr[low:high]* for *target*.

    Base cases:
    * high is None – initialise to len(arr)
    * low > high – target not present, return -1
    * arr[mid] == target – found, return mid
    """
    if high is None:
        high = len(arr) - 1
    if low > high:
        return -1  # Base case: empty interval
    mid = (low + high) // 2
    if arr[mid] == target:
        return mid  # Base case: element found
    elif arr[mid] < target:
        return binary_search(arr, target, mid + 1, high)
    else:
        return binary_search(arr, target, low, mid - 1)

def main() -> None:
    # Simple demo with a sorted list of integers
    sorted_numbers = list(range(0, 101, 5))  # [0, 5, 10, ..., 100]
    while True:
        txt = input('Enter integer to find (blank to quit): ')
        if txt == '':
            break
        try:
            n = int(txt)
            idx = binary_search(sorted_numbers, n)
            if idx != -1:
                print(f'{n} found at index {idx}.')
            else:
                print(f'{n} not present in the list.')
        except ValueError:
            print('Please enter a valid integer.')

if __name__ == '__main__':
    main()

