from collections import deque

def max_window(arr, k):
    q = deque()
    res = []
    for i, v in enumerate(arr):
        while q and arr[q[-1]] < v:
            q.pop()
        q.append(i)
        if q[0] <= i - k:
            q.popleft()
        if i >= k - 1:
            res.append(arr[q[0]])
    return res
